#define claySizingFit(...) (CLAYI_INIT(CLAY_SizingAxis) {                                                            \
    .size = { .minMax = CLAYI_SIZING_MIN_MAX(__VA_ARGS__), .percent = 0 }, .type = CLAY_SIZING_TYPE_FIT })

#define claySizingGrow(...) (CLAYI_INIT(CLAY_SizingAxis) {                                                           \
    .size = { .minMax = CLAYI_SIZING_MIN_MAX(__VA_ARGS__), .percent = 0 }, .type = CLAY_SIZING_TYPE_GROW })

