#define claySizingPercent(percentOfParent) (CLAYI_INIT(CLAY_SizingAxis) {                                           \
    .size = { .minMax = { 0, 0 }, .percent = (percentOfParent) }, .type = CLAY_SIZING_TYPE_PERCENT })

#define claySizingPercentMinMax(percentOfParent, ...) (CLAYI_INIT(CLAY_SizingAxis) {                                \
    .size = { .minMax = CLAYI_SIZING_MIN_MAX(__VA_ARGS__), .percent = (percentOfParent) },                        \
    .type = CLAY_SIZING_TYPE_PERCENT })

#define clayId(label) claySid(clayString(label))

