#define clayIdi(label, index) claySidi(clayString(label), index)

#define claySidi(label, index) clayHashStringWithOffset(label, index, 0)

#define clayIdLocal(label) claySidLocal(clayString(label))

#define claySidLocal(label) clayHashString(label, clayGetOpenElementId())

#define clayIdiLocal(label, index) claySidiLocal(clayString(label), index)

#define claySidiLocal(label, index) clayHashStringWithOffset(label, index, clayGetOpenElementId())

#define CLAYI_STRING_LENGTH(s) ((sizeof(s) / sizeof((s)[0])) - sizeof((s)[0]))

#define CLAYI_ENSURE_STRING_LITERAL(x) ("" x "")

#define clayString(string) (CLAYI_INIT(CLAY_String) { .isStaticallyAllocated = true, .length = CLAYI_STRING_LENGTH(CLAYI_ENSURE_STRING_LITERAL(string)), .chars = (string) })

#define clayStringConst(string) { .isStaticallyAllocated = true, .length = CLAYI_STRING_LENGTH(CLAYI_ENSURE_STRING_LITERAL(string)), .chars = (string) }

