#define CLAYI_ARRAY_DEFINE_FUNCTIONS(typeName, arrayName, sliceName, fnPrefix)                                     \
                                                                                                                \
typedef struct                                                                                                  \
{                                                                                                               \
    int32_t length;                                                                                             \
    typeName *internalArray;                                                                                    \
} sliceName;                                                                                                    \
                                                                                                                \
static typeName fnPrefix##_default = CLAYI_DEFAULT_STRUCT;                                                             \
                                                                                                                \
static inline arrayName fnPrefix##_allocate_arena(int32_t capacity, CLAY_Arena *arena) {                                     \
                   \
    typeName *memory = (typeName *)clayi_array_allocate_arena(capacity, sizeof(typeName), arena);               \
    return CLAYI_INIT(arrayName){.capacity = memory ? capacity : 0, .length = 0, .internalArray = memory};      \
}                                                                                                               \
                                                                                                                \
static inline typeName *fnPrefix##_get(arrayName *array, int32_t index) {                                                    \
    return clayi_array_range_check(index, array->length) ? &array->internalArray[index] : &fnPrefix##_default;   \
}                                                                                                               \
                                                                                                                \
static inline typeName fnPrefix##_get_value(arrayName *array, int32_t index) {                                                \
    return clayi_array_range_check(index, array->length) ? array->internalArray[index] : fnPrefix##_default;     \
}                                                                                                               \
                                                                                                                \
static inline typeName *fnPrefix##_get_check_capacity(arrayName *array, int32_t index) {                                                    \
    return clayi_array_range_check(index, array->capacity) ? &array->internalArray[index] : &fnPrefix##_default;   \
}                                                                                                               \
                                                                                                                \
static inline typeName *fnPrefix##_add(arrayName *array, typeName item) {                                                    \
    if (clayi_array_add_capacity_check(array->length, array->capacity)) {                                         \
        array->internalArray[array->length++] = item;                                                           \
        return &array->internalArray[array->length - 1];                                                        \
    }                                                                                                           \
    return &fnPrefix##_default;                                                                                 \
}                                                                                                               \
                                                                                                                \
static inline typeName *fnPrefix##_slice_get(sliceName *slice, int32_t index) {                                 \
    return clayi_array_range_check(index, slice->length) ? &slice->internalArray[index] : &fnPrefix##_default;   \
}                                                                                                               \
                                                                                                                \
static inline typeName fnPrefix##_remove_swapback(arrayName *array, int32_t index) {                                          \
	if (clayi_array_range_check(index, array->length)) {                                                         \
		array->length--;                                                                                        \
		typeName removed = array->internalArray[index];                                                         \
		array->internalArray[index] = array->internalArray[array->length];                                      \
		return removed;                                                                                         \
	}                                                                                                           \
	return fnPrefix##_default;                                                                                  \
}                                                                                                               \
                                                                                                                \
static inline typeName* fnPrefix##_set(arrayName *array, int32_t index, typeName value) {                                    \
	if (clayi_array_range_check(index, array->capacity)) {                                                       \
		array->internalArray[index] = value;                                                                    \
		array->length = index < array->length ? array->length : index + 1;                                      \
        return &array->internalArray[index];\
	}                                                                                                           \
    return NULL;\
}                                                                                                               \
                                                                                                                \
static inline typeName* fnPrefix##_set_dont_touch_length(arrayName *array, int32_t index, typeName value) {                                    \
	if (clayi_array_range_check(index, array->capacity)) {                                                       \
		array->internalArray[index] = value;                                                                    \
        return &array->internalArray[index];\
	}                                                                                                           \
    return NULL;\
}  \

#define CLAYI_ARRAY_DEFINE(typeName, arrayName, sliceName, fnPrefix)     \
typedef struct                                      \
{                                                   \
    int32_t capacity;                               \
    int32_t length;                                 \
    typeName *internalArray;                        \
} arrayName;                                        \
                                                    \
CLAYI_ARRAY_DEFINE_FUNCTIONS(typeName, arrayName, sliceName, fnPrefix)   \

