void claySetTextBreakFunction(CLAY_TextBreakCallback textBreakFunction, void *userData) {
    CLAY_Context* context = clayGetCurrentContext();
    if (!context || (context->textBreakFunction == textBreakFunction && context->textBreakUserData == userData)) {
        return;
    }
    context->textBreakFunction = textBreakFunction;
    context->textBreakUserData = userData;
    if (context->textBreakPolicy == 126) {

        for (int32_t i = 1; i < context->measureTextHashMapInternal.length
                            && i < context->measureTextHashMapInternal.capacity; i++) {
            context->measureTextHashMapInternal.internalArray[i].breakPolicy = 127;
        }
    }
    context->textBreakPolicy = (uint8_t)(context->textBreakPolicy % 126 + 1);
}

