typedef struct RCI_LoopHost {

    void (*wake)(void *user);

    bool (*live)(void *user);

    void (*changed)(void *user);
    void *user;
#if defined(__ANDROID__)

    void *(*javaVm)(void);

    void *(*javaActivity)(void *user);
#endif
} RCI_LoopHost;

typedef enum RCI_LoopOwner {
    RCI_LOOP_OWNER_NONE    = 0,
    RCI_LOOP_OWNER_RUNNER  = 1,
    RCI_LOOP_OWNER_PROGRAM = 2
} RCI_LoopOwner;

typedef struct RCI_LoopService {
    size_t (*update)(void);
    double (*deadline)(void);
    void   (*shutdown)(void);
} RCI_LoopService;

#define RCI_LOOP_PIXELS_RGBA8 1
#define RCI_LOOP_PIXELS_BGRA8 2
#define RCI_LOOP_PIXELS_RGBX8 3
#define RCI_LOOP_PIXELS_BGRX8 4

#define RCI_LOOP_PIXELS_EXTERNAL 0x100

#define RCI_LOOP_PIXELS_ELEMENT 16

#define RCI_LOOP_PIXELS_I420 32

#define RCI_LOOP_YUV_BT601  0
#define RCI_LOOP_YUV_BT709  1
#define RCI_LOOP_YUV_BT2020 2

typedef struct RCI_LoopFrame {
    const unsigned char *pixels;
    int                  width, height, stride;
    int                  format;
    uint32_t             rev;
    uint32_t             gen;
    void                *hold;
    int                  element;
    const unsigned char *u, *v;
    int                  uStride, vStride;
    int                  matrix;
    int                  fullRange;
} RCI_LoopFrame;

#define RCI_LOOP_MEDIA_OPEN    1u
#define RCI_LOOP_MEDIA_FRAME   2u
#define RCI_LOOP_MEDIA_PENDING 4u
#define RCI_LOOP_MEDIA_EXTERNAL 8u

typedef struct RCI_LoopMedia {
    RCI_LoopService service;

    unsigned (*acquire)(uint32_t media, uint32_t have, RCI_LoopFrame *frame, double *next);

    void     (*release)(RCI_LoopFrame *frame);

    void     (*watch)(void (*closed)(uint32_t media));

    void     (*lend)(uint32_t media, void *target);

    void     (*fail)(uint32_t media, const char *why);
} RCI_LoopMedia;

extern const RCI_LoopHost    *rci_base_loop_host;
extern RCI_LoopOwner          rci_base_loop_owner;
extern const RCI_LoopService *rci_base_loop_service;
extern const RCI_LoopService *rci_base_loop_net;
extern const RCI_LoopMedia   *rci_base_loop_media;

static inline void rci_loop_attach(const RCI_LoopHost *host, RCI_LoopOwner owner) {
#if defined(__ANDROID__)
    __atomic_store_n(&rci_base_loop_host, host, __ATOMIC_SEQ_CST);
#else
    rci_base_loop_host = host;
#endif
    rci_base_loop_owner = host ? owner : RCI_LOOP_OWNER_NONE;
}

static inline size_t rci_loop_update(void) {
    return rci_base_loop_service ? rci_base_loop_service->update() : 0;
}

static inline double rci_loop_deadline(void) {
    return rci_base_loop_service ? rci_base_loop_service->deadline() : INFINITY;
}

static inline void rci_loop_shutdown(void) {
    if (rci_base_loop_service)
        rci_base_loop_service->shutdown();
}

static inline void rci_loop_register(const RCI_LoopService *service) {
    rci_base_loop_net = service;
    if (!rci_base_loop_media)
        rci_base_loop_service = service;
}

static inline void rci_loop_register_media(const RCI_LoopMedia *media,
                                           const RCI_LoopService *both) {
    rci_base_loop_media   = media;
    rci_base_loop_service = media ? both : rci_base_loop_net;
}

static inline const RCI_LoopService *rci_loop_net(void) {
    return rci_base_loop_net;
}

static inline const RCI_LoopMedia *rci_loop_media(void) {
    return rci_base_loop_media;
}

static inline const RCI_LoopHost *rci_loop_host(void) {
    return rci_base_loop_host;
}

#if defined(__ANDROID__)

static inline const RCI_LoopHost *rci_loop_host_any(void) {
    return __atomic_load_n(&rci_base_loop_host, __ATOMIC_SEQ_CST);
}
#endif

static inline RCI_LoopOwner rci_loop_owner(void) {
    return rci_base_loop_owner;
}

static inline bool rci_loop_live(void) {
    const RCI_LoopHost *host = rci_base_loop_host;

    return host && (!host->live || host->live(host->user));
}

static inline bool rci_loop_runner_owns(void) {
    return rci_loop_owner() == RCI_LOOP_OWNER_RUNNER && rci_loop_live();
}

static inline void rci_loop_changed(void) {
    const RCI_LoopHost *host = rci_base_loop_host;

    if (host && host->changed)
        host->changed(host->user);
}

