RCI_LoopOwner          rci_base_loop_owner   = RCI_LOOP_OWNER_NONE;
const RCI_LoopService *rci_base_loop_service = NULL;
const RCI_LoopService *rci_base_loop_net     = NULL;
const RCI_LoopMedia   *rci_base_loop_media   = NULL;

