static inline uint8_t rci_internal_scroll_fade_run(const RCI_ScrollReg *reg, uint8_t fade) {
    return fade > reg->fadeSteps ? (uint8_t)(fade - reg->fadeSteps) : 0;
}

static inline void rci_internal_scroll_fade_note(RCI_ScrollReg *reg, uint8_t fade) {
    if (fade && (!reg->fadeLeast || fade < reg->fadeLeast))
        reg->fadeLeast = fade;
}

