static inline bool rci_internal_color_set(RC_Color c) {
    uint32_t r, g, b, a;
    memcpy(&r, &c.r, sizeof r);
    memcpy(&g, &c.g, sizeof g);
    memcpy(&b, &c.b, sizeof b);
    memcpy(&a, &c.a, sizeof a);
    return ((r | g | b | a) << 1) != 0u;
}

static inline CLAY_Color rci_internal_class_color(const uint8_t c[4]) {

    const CLAY_Color set = { (float)c[0] + RCI_COLOR_SET_BIAS, (float)c[1], (float)c[2], (float)c[3] };
    return set;
}

static inline RC_OptFloat rci_internal_opt_floor(float v) {
    return v > 0.0f ? RC_VAL(v) : RC_UNSET_VAL;
}

