static inline float rci_internal_optf(RC_OptFloat o, float dflt) {
    return o.set ? o.value : dflt;
}

static inline float rci_internal_maxf(float a, float b) {
    return a > b ? a : b;
}

static inline float rci_internal_minf(float a, float b) {
    return a < b ? a : b;
}

static inline uint16_t rci_internal_scale_u16(uint16_t v, float k) {
    if (!v) return 0;
    float s = (float)v * k;
    if (!(s > 0.0f)) return 0;
    return (s >= (float)UINT16_MAX) ? (uint16_t)UINT16_MAX : (uint16_t)(s + 0.5f);
}

static inline int16_t rci_internal_scale_i16(int16_t v, float k) {
    if (!v) return 0;
    float s = (float)v * k;
    if (!(s == s)) return 0;
    if (s >= (float)INT16_MAX) return (int16_t)INT16_MAX;
    if (s <= (float)INT16_MIN) return (int16_t)INT16_MIN;
    return (int16_t)(s >= 0.0f ? s + 0.5f : s - 0.5f);
}

