static inline uint16_t rci_internal_class_line(const RCI_ClassText *t, float px) {
    const float ratio = t->lineHeightRatio * px + 0.5f;

    if (t->set & RCI_CLASS_TEXT_SET_LEAD_PX)
        return t->lineHeightPx;
    if (t->set & RCI_CLASS_TEXT_SET_LEADING)
        return ratio < (float)UINT16_MAX ? (uint16_t)ratio : (uint16_t)UINT16_MAX;
    if (t->set & RCI_CLASS_TEXT_SET_SIZE_LEAD)
        return t->lineHeightPx ? t->lineHeightPx : (uint16_t)px;
    return 0u;
}

static inline int16_t rci_internal_class_track(const RCI_ClassText *t, float px) {
    const float v = t->trackingEm * px;

    if (!(t->set & RCI_CLASS_TEXT_SET_TRACK))
        return 0;
    return (int16_t)(v < 0.0f ? v - 0.5f : v + 0.5f);
}

