#define RCI_TEXT_SIZE_FRAC      0x8000u
#define RCI_TEXT_SIZE_WHOLE_MAX 0x7FFFu
#define RCI_TEXT_SIZE_STEPS     64u

static inline uint16_t rci_internal_text_size_encode(float px) {
    const float fracCap = (float)(RCI_TEXT_SIZE_FRAC / RCI_TEXT_SIZE_STEPS);
    uint32_t    q;

    if (!(px > 1.0f))
        return 1;
    if (px >= fracCap)
        return px >= (float)RCI_TEXT_SIZE_WHOLE_MAX ? (uint16_t)RCI_TEXT_SIZE_WHOLE_MAX
                                                    : (uint16_t)(px + 0.5f);
    q = (uint32_t)(px * (float)RCI_TEXT_SIZE_STEPS + 0.5f);
    if (q % RCI_TEXT_SIZE_STEPS == 0)
        return (uint16_t)(q / RCI_TEXT_SIZE_STEPS);
    return (uint16_t)(RCI_TEXT_SIZE_FRAC | q);
}

static inline float rci_internal_text_size_px(uint16_t v) {
    return (v & RCI_TEXT_SIZE_FRAC)
         ? (float)(v & RCI_TEXT_SIZE_WHOLE_MAX) * (1.0f / (float)RCI_TEXT_SIZE_STEPS)
         : (float)v;
}

#define RCI_TEXTSEL_MAGIC      0x5A7u
#define RCI_TEXTSEL_MODE_BITS  2
#define RCI_TEXTSEL_ORD_BITS   18
#define RCI_TEXT_TAG_ELLIPSIS  (1u << (RCI_TEXTSEL_MODE_BITS + RCI_TEXTSEL_ORD_BITS))
#define RCI_TEXTSEL_MAGIC_SHIFT (RCI_TEXTSEL_MODE_BITS + RCI_TEXTSEL_ORD_BITS + 1)

#define RCI_TEXTSEL_ORD_MAX    ((1u << RCI_TEXTSEL_ORD_BITS) - 1u)

#define RCI_TEXTSEL_PACK(mode, ord) \
    ((uint32_t)((RCI_TEXTSEL_MAGIC << RCI_TEXTSEL_MAGIC_SHIFT) \
              | (((uint32_t)(ord) & RCI_TEXTSEL_ORD_MAX) << RCI_TEXTSEL_MODE_BITS) \
              | ((uint32_t)(mode) & 0x3u)))
#define RCI_TEXTSEL_HAS_MAGIC(tag) \
    ((((uint32_t)(tag)) >> RCI_TEXTSEL_MAGIC_SHIFT) == RCI_TEXTSEL_MAGIC)

#define RCI_TEXT_TAG_HAS_ELLIPSIS(tag) \
    (RCI_TEXTSEL_HAS_MAGIC(tag) && (((uint32_t)(tag)) & RCI_TEXT_TAG_ELLIPSIS) != 0u)
#define RCI_TEXTSEL_MODE(tag)  ((uint32_t)(tag) & 0x3u)
#define RCI_TEXTSEL_ORD(tag)   ((((uint32_t)(tag)) >> RCI_TEXTSEL_MODE_BITS) & RCI_TEXTSEL_ORD_MAX)

