#define RCI_TEXT_IS_SPACE(ch) \
    ((ch) == ' ' || (ch) == '\t' || (ch) == '\n' || (ch) == '\r')
static inline void rci_internal_text_word_span(const char *s, int len, int at, int *start,
                                               int *end) {
    int  a, b;
    bool space;

    if (at < 0)   at = 0;
    if (at > len) at = len;

    if (at == len && at > 0) at--;
    else if (at > 0 && RCI_TEXT_IS_SPACE(s[at]) && !RCI_TEXT_IS_SPACE(s[at - 1])) at--;

    space = at < len && RCI_TEXT_IS_SPACE(s[at]);
    a = b = at;
    while (a > 0   && (bool)RCI_TEXT_IS_SPACE(s[a - 1]) == space) a--;
    while (b < len && (bool)RCI_TEXT_IS_SPACE(s[b])     == space) b++;
    *start = a;
    *end   = b;
}

