static inline void rci_internal_hairline_held(const CLAY_ElementDeclaration *d, unsigned pads) {
    const float  uz = rcUnzoomedScale();
    CLAY_Padding held;

    held.left   = (uint16_t)((pads & RCI_CLASS_SET_PAD_L) ? 0u
                                  : rci_core_unzoom_u16(d->border.width.left, uz));
    held.right  = (uint16_t)((pads & RCI_CLASS_SET_PAD_R) ? 0u
                                  : rci_core_unzoom_u16(d->border.width.right, uz));
    held.top    = (uint16_t)((pads & RCI_CLASS_SET_PAD_T) ? 0u
                                  : rci_core_unzoom_u16(d->border.width.top, uz));
    held.bottom = (uint16_t)((pads & RCI_CLASS_SET_PAD_B) ? 0u
                                  : rci_core_unzoom_u16(d->border.width.bottom, uz));
    rci_core_border_held(held);
}

