static inline bool rci_image_gif_info(const unsigned char *p, int len, int *w, int *h) {
    if (len < 13 || p[0] != 'G' || p[1] != 'I' || p[2] != 'F' || p[3] != '8' ||
        (p[4] != '7' && p[4] != '9') || p[5] != 'a')
        return false;
    *w = p[6] | p[7] << 8;
    *h = p[8] | p[9] << 8;
    return true;
}

