static inline bool rci_image_webp_info(const unsigned char *p, int len, int *w, int *h,
                                       bool *animated) {
    if (len < 30 || p[0] != 'R' || p[1] != 'I' || p[2] != 'F' || p[3] != 'F' || p[8] != 'W' ||
        p[9] != 'E' || p[10] != 'B' || p[11] != 'P' || p[12] != 'V' || p[13] != 'P' || p[14] != '8')
        return false;
    *animated = false;
    if (p[15] == 'X') {
        *animated = (p[20] & 0x02) != 0;
        *w        = 1 + (p[24] | p[25] << 8 | p[26] << 16);
        *h        = 1 + (p[27] | p[28] << 8 | p[29] << 16);
        return true;
    }
    if (p[15] == 'L') {
        const uint32_t b = (uint32_t)p[21] | (uint32_t)p[22] << 8 | (uint32_t)p[23] << 16 |
                           (uint32_t)p[24] << 24;

        if (p[20] != 0x2F)
            return false;
        *w = 1 + (int)(b & 0x3FFF);
        *h = 1 + (int)((b >> 14) & 0x3FFF);
        return true;
    }
    if (p[15] == ' ' && p[23] == 0x9D && p[24] == 0x01 && p[25] == 0x2A) {

        *w = (p[26] | p[27] << 8) & 0x3FFF;
        *h = (p[28] | p[29] << 8) & 0x3FFF;
        return true;
    }
    return false;
}

