#ifndef RC_VIEWPORT_MATH_H
#define RC_VIEWPORT_MATH_H

#include <math.h>

static inline RC_Breakpoint rci_viewport_math_breakpoint(float w) {

    if (w >= 1536.0f) return RC_BP_2XL;
    if (w >= 1280.0f) return RC_BP_XL;
    if (w >= 1024.0f) return RC_BP_LG;
    if (w >=  768.0f) return RC_BP_MD;
    if (w >=  640.0f) return RC_BP_SM;
    return RC_BP_BASE;
}

static inline float rci_viewport_math_axis_factor(float layout, float window) {
    float k;
    if (!(window > 0.0f) || !isfinite(window) || !isfinite(layout)) return 1.0f;
    k = layout / window;

    return (isfinite(k) && k > 0.0f) ? k : 1.0f;
}

static inline RC_Insets rci_viewport_math_safe_to_layout(RC_Insets safe,
                                                    float layoutW, float layoutH,
                                                    float windowW, float windowH) {
    float kx = rci_viewport_math_axis_factor(layoutW, windowW);
    float ky = rci_viewport_math_axis_factor(layoutH, windowH);
    RC_Insets out;
    out.top    = safe.top    * ky;
    out.bottom = safe.bottom * ky;
    out.left   = safe.left   * kx;
    out.right  = safe.right  * kx;
    return out;
}

#endif

