typedef struct sg_environment_defaults {
    sg_pixel_format color_format;
    sg_pixel_format depth_format;
    int sample_count;
} sg_environment_defaults;

typedef struct sg_metal_environment {
    const void* device;
} sg_metal_environment;

typedef struct sg_d3d11_environment {
    const void* device;
    const void* device_context;
} sg_d3d11_environment;

typedef struct sg_wgpu_environment {
    const void* device;
} sg_wgpu_environment;

typedef struct sg_vulkan_environment {
    const void* instance;
    const void* physical_device;
    const void* device;
    const void* queue;
    uint32_t queue_family_index;
} sg_vulkan_environment;

typedef struct sg_environment {
    sg_environment_defaults defaults;
    sg_metal_environment metal;
    sg_d3d11_environment d3d11;
    sg_wgpu_environment wgpu;
    sg_vulkan_environment vulkan;
} sg_environment;

typedef struct sg_commit_listener {
    void (*func)(void* user_data);
    void* user_data;
} sg_commit_listener;

typedef struct sg_allocator {
    void* (*alloc_fn)(size_t size, void* user_data);
    void (*free_fn)(void* ptr, void* user_data);
    void* user_data;
} sg_allocator;

typedef struct sg_logger {
    void (*func)(
        const char* tag,
        uint32_t log_level,
        uint32_t log_item_id,
        const char* message_or_null,
        uint32_t line_nr,
        const char* filename_or_null,
        void* user_data);
    void* user_data;
} sg_logger;

typedef struct sg_d3d11_desc {
    bool shader_debugging;
} sg_d3d11_desc;

typedef struct sg_metal_desc {
    bool force_managed_storage_mode;
    bool use_command_buffer_with_retained_references;
} sg_metal_desc;

typedef struct sg_wgpu_desc {
    bool disable_bindgroups_cache;
    int bindgroups_cache_size;
} sg_wgpu_desc;

typedef struct sg_vulkan_desc {
    int copy_staging_buffer_size;
    int stream_staging_buffer_size;
    int descriptor_buffer_size;
} sg_vulkan_desc;

typedef struct sg_desc {
    uint32_t _start_canary;
    int buffer_pool_size;
    int image_pool_size;
    int sampler_pool_size;
    int shader_pool_size;
    int pipeline_pool_size;
    int view_pool_size;
    int uniform_buffer_size;
    int max_commit_listeners;
    bool disable_validation;
    bool enforce_portable_limits;
    sg_d3d11_desc d3d11;
    sg_metal_desc metal;
    sg_wgpu_desc wgpu;
    sg_vulkan_desc vulkan;
    sg_allocator allocator;
    sg_logger logger;
    sg_environment environment;
    uint32_t _end_canary;
} sg_desc;

