    "#version 410\n"
    "uniform sampler2D tex_smp;\n"
    "layout(location = 0) in vec2 uv;\n"
    "layout(location = 1) in vec4 color;\n"
    "layout(location = 0) out vec4 frag_color;\n"
    RCI_PKT_FS_COV_MAIN;
#endif

