    "void main() {\n"
    "    vec4 c = color * texture(tex_smp, uv);\n"
    "    highp float k = rc_clip();\n"
    "    frag_color = vec4(c.rgb * mix(1.0, k, fs_clip[0].y), c.a * k);\n"
    "}\n";
static const char rci_gfx_sokol_pkt_fs_cov_clip_glsl[] =
    "void main() {\n"
    "    frag_color = vec4(color.rgb, color.a * max(texture(tex_smp, uv).r, step(1.5, uv.x)) *\n"
    "                                 rc_clip());\n"
    "}\n";
