    "layout(location = 2) in vec2 lp;\n"
    "layout(location = 0) out vec4 frag_color;\n";
#endif
#if RCI_GFX_SOKOL_GLSL300ES

static const char rci_gfx_sokol_pkt_fs_yuv_glsl300es[] =
    "#version 300 es\n"
    "precision highp float;\n"
    "uniform vec4 fs_params[4];\n"
    "uniform highp sampler2D y_smp;\n"
    "uniform highp sampler2D u_smp;\n"
    "uniform highp sampler2D v_smp;\n"
    "in vec2 uv;\n"
    "in vec4 color;\n"
    "in vec2 lp;\n"
    "layout(location = 0) out vec4 frag_color;\n";
#endif
static const char rci_gfx_sokol_pkt_fs_yuv_main_glsl[] =
    "void main() {\n"
    "    vec2 c = uv * fs_params[3].xy;\n"
    "    vec4 p = vec4(texture(y_smp, uv).r, texture(u_smp, c).r, texture(v_smp, c).r, 1.0);\n"
    "    frag_color = color * vec4(clamp(vec3(dot(fs_params[0], p), dot(fs_params[1], p),\n"
    "                                         dot(fs_params[2], p)), 0.0, 1.0), 1.0);\n"
    "    frag_color.a *= rc_clip();\n"
    "}\n";
#endif
#if defined(RC_GFX_BACKEND_D3D11)

#define RCI_PKT_FS_HLSL4_STRUCT_LP \
    "struct vs_out {\n" \
    "    float2 uv : TEXCOORD0; float4 color : TEXCOORD1; float4 pos : SV_Position;\n" \
    "    float2 lp : TEXCOORD2;\n" \
    "};\n"
static const char rci_gfx_sokol_pkt_fs_clip_head_hlsl4[] =
    "cbuffer fs_clip : register(b0) { float4 fs_clip[17]; };\n"
    "Texture2D<float4> tex : register(t0);\n"
    "SamplerState smp : register(s0);\n"
    RCI_PKT_FS_HLSL4_STRUCT_LP;
static const char rci_gfx_sokol_pkt_fs_clip_hlsl4[] =
    "float rc_clip(float2 lp) {\n"
    "    float a = 1.0;\n"
    "    for (int i = 0; i < (int)fs_clip[0].x; i++) {\n"
    "        float4 ix = fs_clip[3 + 4 * i], iy = fs_clip[4 + 4 * i];\n"
    "        float4 dx = (lp.x - fs_clip[1 + 4 * i]) * float4(-1.0, 1.0, -1.0, 1.0);\n"
    "        float4 dy = (lp.y - fs_clip[2 + 4 * i]) * float4(-1.0, -1.0, 1.0, 1.0);\n"
    "        float4 u = dx * ix, v = dy * iy;\n"
    "        float4 d = 0.5 * (u * u + v * v - 1.0) *\n"
    "                   rsqrt(max(u * u * ix * ix + v * v * iy * iy, 1e-20));\n"
    "        float4 k = lerp(1.0, saturate(0.5 - d * fs_clip[0].z), step(0.0, min(dx, dy)));\n"
    "        a *= k.x * k.y * k.z * k.w;\n"
    "    }\n"
    "    return a;\n"
    "}\n";
static const char rci_gfx_sokol_pkt_fs_rgba_clip_hlsl4[] =
    "float4 main(vs_out i) : SV_Target0 {\n"
    "    float4 c = i.color * tex.Sample(smp, i.uv);\n"
    "    float k = rc_clip(i.lp);\n"
    "    return float4(c.rgb * lerp(1.0, k, fs_clip[0].y), c.a * k);\n"
    "}\n";
static const char rci_gfx_sokol_pkt_fs_cov_clip_hlsl4[] =
    "float4 main(vs_out i) : SV_Target0 {\n"
    "    return float4(i.color.rgb, i.color.a * max(tex.Sample(smp, i.uv).r, step(1.5, i.uv.x)) *\n"
    "                               rc_clip(i.lp));\n"
    "}\n";

static const char rci_gfx_sokol_pkt_fs_yuv_hlsl4[] =
    "cbuffer fs_params : register(b0) { float4 fs_params[4]; float4 fs_clip[17]; };\n"
    "Texture2D<float4> y_tex : register(t0);\n"
    "Texture2D<float4> u_tex : register(t1);\n"
    "Texture2D<float4> v_tex : register(t2);\n"
    "SamplerState smp : register(s0);\n"
    RCI_PKT_FS_HLSL4_STRUCT_LP;
static const char rci_gfx_sokol_pkt_fs_yuv_main_hlsl4[] =
    "float4 main(vs_out i) : SV_Target0 {\n"
    "    float2 c = i.uv * fs_params[3].xy;\n"
    "    float4 p = float4(y_tex.Sample(smp, i.uv).r, u_tex.Sample(smp, c).r,\n"
    "                      v_tex.Sample(smp, c).r, 1.0);\n"
    "    float4 o = i.color * float4(saturate(float3(dot(fs_params[0], p), dot(fs_params[1], p),\n"
    "                                                dot(fs_params[2], p))), 1.0);\n"
    "    return float4(o.rgb, o.a * rc_clip(i.lp));\n"
    "}\n";
#endif
#if defined(RC_GFX_BACKEND_METAL)

static const char rci_gfx_sokol_pkt_fs_clip_msl[] =
    "#include <metal_stdlib>\n"
    "using namespace metal;\n"
    "struct fs_in { float2 uv; float4 color; float2 lp; };\n"
    "static float rc_clip(float2 lp, constant float4 *k) {\n"
    "    float a = 1.0;\n"
    "    for (int i = 0; i < int(k[0].x); i++) {\n"
    "        float4 ix = k[3 + 4 * i], iy = k[4 + 4 * i];\n"
    "        float4 dx = (lp.x - k[1 + 4 * i]) * float4(-1.0, 1.0, -1.0, 1.0);\n"
    "        float4 dy = (lp.y - k[2 + 4 * i]) * float4(-1.0, -1.0, 1.0, 1.0);\n"
    "        float4 u = dx * ix, v = dy * iy;\n"
    "        float4 d = 0.5 * (u * u + v * v - 1.0) *\n"
    "                   rsqrt(max(u * u * ix * ix + v * v * iy * iy, 1e-20));\n"
    "        float4 c = mix(float4(1.0), saturate(0.5 - d * k[0].z), step(0.0, min(dx, dy)));\n"
    "        a *= c.x * c.y * c.z * c.w;\n"
    "    }\n"
    "    return a;\n"
    "}\n";
#define RCI_PKT_FS_MSL_CLIP_HEAD \
    "fragment float4 _main(fs_in i [[stage_in]], texture2d<float> tex [[texture(0)]],\n" \
    "                      sampler smp [[sampler(0)]], constant float4 *k [[buffer(0)]]) {\n"
static const char rci_gfx_sokol_pkt_fs_rgba_clip_msl[] =
    RCI_PKT_FS_MSL_CLIP_HEAD
    "    float4 c = i.color * tex.sample(smp, i.uv);\n"
    "    float a = rc_clip(i.lp, k);\n"
    "    return float4(c.rgb * mix(1.0, a, k[0].y), c.a * a);\n"
    "}\n";
static const char rci_gfx_sokol_pkt_fs_cov_clip_msl[] =
    RCI_PKT_FS_MSL_CLIP_HEAD
    "    return float4(i.color.rgb, i.color.a * max(tex.sample(smp, i.uv).r, step(1.5, i.uv.x)) *\n"
    "                               rc_clip(i.lp, k));\n"
    "}\n";

static const char rci_gfx_sokol_pkt_fs_yuv_msl[] =
    "struct fs_params { float4 m[21]; };\n"
    "fragment float4 _main(fs_in i [[stage_in]], constant fs_params &f [[buffer(0)]],\n"
    "                      texture2d<float> y_tex [[texture(0)]],\n"
    "                      texture2d<float> u_tex [[texture(1)]],\n"
    "                      texture2d<float> v_tex [[texture(2)]], sampler smp [[sampler(0)]]) {\n"
    "    float2 c = i.uv * f.m[3].xy;\n"
    "    float4 p = float4(y_tex.sample(smp, i.uv).r, u_tex.sample(smp, c).r,\n"
    "                      v_tex.sample(smp, c).r, 1.0);\n"
    "    float4 o = i.color * float4(saturate(float3(dot(f.m[0], p), dot(f.m[1], p),\n"
    "                                                dot(f.m[2], p))), 1.0);\n"
    "    return float4(o.rgb, o.a * rc_clip(i.lp, f.m + 4));\n"
    "}\n";
#endif

