#if RCI_GFX_REPLAY

static CLAY_Color rci_gfx_rp_get_color(const uint32_t *w) {
    return (CLAY_Color){ rci_gfx_rp_f(w[0]), rci_gfx_rp_f(w[1]), rci_gfx_rp_f(w[2]),
                         rci_gfx_rp_f(w[3]) };
}
static RCI_Corners rci_gfx_rp_get_corners(const uint32_t *w) {
    return (RCI_Corners){ rci_gfx_rp_f(w[0]), rci_gfx_rp_f(w[1]), rci_gfx_rp_f(w[2]),
                          rci_gfx_rp_f(w[3]) };
}

static void rci_gfx_replay_encode(uint32_t from, uint32_t end) {
    unsigned char       *p = rci_gfx_replay.log[rci_gfx_replay.cur] + from;
    const unsigned char *stop = rci_gfx_replay.log[rci_gfx_replay.cur] + end;
    const int            mode = rci_gfx_replay.mode;
#define F(i) rci_gfx_rp_f(a[i])

    rci_gfx_replay.mode = RCI_GFX_REPLAY_OFF;
    rci_gfx_state.faded = rci_gfx_replay.faded;
    rci_gfx_state.alpha = rci_gfx_replay.alpha;
    while (p < stop) {
        uint32_t  head[2];
        uint32_t *a = (uint32_t *)(void *)(p + 8);

        memcpy(head, p, sizeof head);
        switch (head[0]) {
        case RCI_GFX_RP_RECT:
            rci_gfx_rect(F(0), F(1), F(2), F(3), rci_gfx_rp_get_color(a + 4), rci_gfx_rp_get_corners(a + 8));
            break;
        case RCI_GFX_RP_TEXT_BAND:
            rci_gfx_text_band(F(0), F(1), F(2), F(3), rci_gfx_rp_get_color(a + 4));
            break;
        case RCI_GFX_RP_GRADIENT:
            rci_gfx_rect_gradient(F(0), F(1), F(2), F(3), rci_gfx_rp_get_color(a + 4),
                                  rci_gfx_rp_get_color(a + 8), (RCI_GradientDir)a[12],
                                  rci_gfx_rp_get_corners(a + 13));
            break;
        case RCI_GFX_RP_SHADOW:
            rci_gfx_shadow(F(0), F(1), F(2), F(3), rci_gfx_rp_get_color(a + 4), rci_gfx_rp_get_corners(a + 8),
                           F(12), F(13), F(14), F(15));
            break;
        case RCI_GFX_RP_SHADOW_CUT:
            rci_gfx_shadow_cut(F(0), F(1), F(2), F(3), rci_gfx_rp_get_color(a + 4),
                               rci_gfx_rp_get_corners(a + 8), F(12), F(13), F(14), F(15));
            break;
        case RCI_GFX_RP_SHADOW_RING:
            rci_gfx_shadow_ring(F(0), F(1), F(2), F(3), rci_gfx_rp_get_color(a + 4),
                                rci_gfx_rp_get_corners(a + 8), F(12));
            break;
        case RCI_GFX_RP_SHADOW_INSET:
            rci_gfx_shadow_inset(F(0), F(1), F(2), F(3), rci_gfx_rp_get_color(a + 4),
                                 rci_gfx_rp_get_corners(a + 8), F(12), F(13), F(14), F(15), F(16));
            break;
        case RCI_GFX_RP_BORDER:
            rci_gfx_border(F(0), F(1), F(2), F(3), rci_gfx_rp_get_color(a + 4), rci_gfx_rp_get_corners(a + 8),
                           F(12), F(13), F(14), F(15));
            break;
        case RCI_GFX_RP_RECT_STROKE:
            rci_gfx_rect_stroke(F(0), F(1), F(2), F(3), F(4), rci_gfx_rp_get_color(a + 5), F(9));
            break;
        case RCI_GFX_RP_CIRCLE:
            rci_gfx_circle_filled(F(0), F(1), F(2), rci_gfx_rp_get_color(a + 3));
            break;
        case RCI_GFX_RP_CIRCLE_STROKE:
            rci_gfx_circle_stroke(F(0), F(1), F(2), rci_gfx_rp_get_color(a + 3), F(7));
            break;
        case RCI_GFX_RP_TEXT:
            rci_gfx_text((uint16_t)a[0], F(1), F(2), F(3), F(4), rci_gfx_rp_get_color(a + 5),
                         (const char *)(a + 10), (int)a[9]);
            break;
        case RCI_GFX_RP_IMAGE: {
            void *t;

            memcpy(&t, a + 1, sizeof t);
            rci_gfx_image(t, F(3), F(4), F(5), F(6), rci_gfx_rp_get_color(a + 7),
                          rci_gfx_rp_get_corners(a + 11), (RCI_UvRect){ F(15), F(16), F(17), F(18) });
            break;
        }
        case RCI_GFX_RP_LINE:
            rci_gfx_line(F(0), F(1), F(2), F(3), rci_gfx_rp_get_color(a + 4), F(8));
            break;
        case RCI_GFX_RP_POLYLINE:
            rci_gfx_polyline((const float *)(const void *)(a + 7), (int)a[0], rci_gfx_rp_get_color(a + 1),
                             F(5), a[6] != 0);
            break;
        case RCI_GFX_RP_ROUND_JOIN:
            rci_gfx_round_join(F(0), F(1), F(2), F(3), F(4), F(5), rci_gfx_rp_get_color(a + 6), F(10));
            break;
        case RCI_GFX_RP_POLY_INDEXED: {
            const uint16_t *idx = (const uint16_t *)(const void *)(a + 6);
            const uint32_t  ip  = (a[0] * 2u + 3u) & ~3u;

            rci_gfx_poly_filled_indexed((const float *)(const void *)((const unsigned char *)idx + ip),
                                        (int)a[0], idx, rci_gfx_rp_get_color(a + 2));
            break;
        }
        case RCI_GFX_RP_POLY:
            rci_gfx_poly_filled((const float *)(const void *)(a + 5), (int)a[0], rci_gfx_rp_get_color(a + 1));
            break;
        case RCI_GFX_RP_QUAD_SHADED:
            rci_gfx_quad_shaded((const float *)(const void *)a, (const CLAY_Color *)(const void *)(a + 8));
            break;
        case RCI_GFX_RP_PUSH_CLIP:
            rci_gfx_push_clip(F(0), F(1), F(2), F(3));
            break;
        case RCI_GFX_RP_CLIP_ROUND:
            rci_gfx_clip_round(F(0), F(1), F(2), F(3), rci_gfx_rp_get_corners(a + 4), F(8), F(9), F(10),
                               F(11));
            break;
        case RCI_GFX_RP_CLIP_OWN:
            rci_gfx_clip_own(a[0] != 0);
            break;
        case RCI_GFX_RP_POP_CLIP:
            rci_gfx_pop_clip();
            break;
        case RCI_GFX_RP_ALPHA:
            rci_gfx_set_alpha(F(0));
            break;
        case RCI_GFX_RP_GROUP_BEGIN:
            a[1] = rci_gfx_group_begin(F(0));
            break;
        case RCI_GFX_RP_LEAF_BEGIN:
            a[1] = rci_gfx_leaf_begin(F(0));
            break;
        case RCI_GFX_RP_SUSPEND:
            a[0] = (uint32_t)rci_gfx_group_suspend();
            break;
        case RCI_GFX_RP_RESUME:
            a[2] = rci_gfx_group_resume((int)a[0], F(1));
            break;
        case RCI_GFX_RP_GROUP_END:
            rci_gfx_group_end();
            break;
        case RCI_GFX_RP_LEAF_END:
            rci_gfx_leaf_end();
            break;
        default:
            assert(!"a record of no kind");
            break;
        }
        p += head[1];
    }
    rci_gfx_replay.faded = rci_gfx_state.faded;
    rci_gfx_replay.alpha = rci_gfx_state.alpha;
    rci_gfx_replay.mode  = mode;
#undef F
}
#endif
#endif
