static char *rci_file_beside_base(size_t *len, RCI_FileStatus *st) {
    size_t cap = 256;
    ssize_t n;
    char *buf;

    for (;;) {
        if ((buf = (char *)malloc(cap)) == NULL) {
            *st = RCI_FILE_OOM;
            return NULL;
        }
        n = readlink("/proc/self/exe", buf, cap);
        if (n > 0 && (size_t)n < cap)
            break;
        free(buf);
        if (n <= 0 || cap >= RCI_FILE_BESIDE_MAX)
            return NULL;
        cap *= 2;
    }
    while (n > 0 && buf[n - 1] != '/')
        n--;
    if (!n) {
        free(buf);
        return NULL;
    }
    buf[--n] = 0;
    *len = (size_t)n;
    return buf;
}
