static char *rci_file_beside_find(const char *path, RCI_FileStatus *st) {
    const char *rel = rci_file_beside_rel(path);
    size_t rl = rel ? strlen(rel) : 0, bl = 0;
    char *base, *cand;
    struct stat sb;

    if (!rel || rl > RCI_FILE_BESIDE_MAX || (base = rci_file_beside_base(&bl, st)) == NULL)
        return NULL;
    if ((cand = (char *)malloc(bl + 1 + rl + 1)) == NULL) {
        *st = RCI_FILE_OOM;
        free(base);
        return NULL;
    }
    memcpy(cand, base, bl);
    cand[bl] = '/';
    memcpy(cand + bl + 1, rel, rl + 1);
    free(base);
    if (stat(cand, &sb) != 0 || !S_ISREG(sb.st_mode)) {
        free(cand);
        return NULL;
    }
    return cand;
}

static unsigned char *rci_file_beside(const char *path, long max_len, int terminate,
                                      long *out_len, RCI_FileStatus *st,
                                      const RCI_FileHead *head) {
    char *cand = rci_file_beside_find(path, st);
    unsigned char *buf = NULL;
    FILE *f;

    if (!cand)
        return NULL;
    if ((f = fopen(cand, "rb")) != NULL)
        buf = rci_file_read_open(f, max_len, terminate, out_len, st, head);
    else
        *st = rci_file_beside_why(errno);
    free(cand);
    return buf;
}

