#define rci_file_read(path, max_len, terminate, out_len, status) \
    rci_file_read_head((path), (max_len), (terminate), (out_len), (status), NULL)
static unsigned char *rci_file_read_head(const char *path, long max_len, int terminate,
                                         long *out_len, RCI_FileStatus *status,
                                         const RCI_FileHead *head) {
    RCI_FileStatus st = RCI_FILE_OK;
    unsigned char *buf = NULL;
    FILE *f;
    int err;
#ifdef _WIN32
    unsigned long doserr = 0;
    int oom = 0;
    wchar_t *wpath = rci_file_utf16(path);
    wchar_t *lpath = rci_file_long(path, wpath, &oom);

    if (oom) {
        free(wpath);
        if (status)
            *status = RCI_FILE_OOM;
        return NULL;
    }
#endif

#if defined(_MSC_VER)
#  pragma warning(push)
#  pragma warning(disable : 4996)
#endif

#ifdef _WIN32
    f = lpath ? _wfopen(lpath, L"rb") : wpath ? _wfopen(wpath, L"rb") : fopen(path, "rb");
    err = errno;
    if (!f && err == ENOENT)
        doserr = _doserrno;
    free(lpath);
    free(wpath);
#else
    f = fopen(path, "rb");
    err = status || RCI_FILE_BESIDE ? errno : 0;
#endif
#if defined(_MSC_VER)
#  pragma warning(pop)
#endif
    if (!f) {
        st = RCI_FILE_MISSING;
#if defined(__ANDROID__)

        if (path[0] != '/' && rci_load_file_asset_reader)
            buf = rci_load_file_asset_reader(path, max_len, terminate, out_len, &st);
#elif RCI_FILE_BESIDE && defined(_WIN32)
        if (err == ENOENT)
            buf = rci_file_beside(path, doserr, max_len, terminate, out_len, &st, head);
#elif RCI_FILE_BESIDE
        if (err == ENOENT)
            buf = rci_file_beside(path, max_len, terminate, out_len, &st, head);
#endif
        if (status)
            *status = st != RCI_FILE_MISSING          ? st               :
                      err == ENOENT || err == ENOTDIR ? RCI_FILE_MISSING :
                      err == EACCES || err == EPERM   ? RCI_FILE_DENIED  : RCI_FILE_OPEN_FAILED;
        return buf;
    }
    buf = rci_file_read_open(f, max_len, terminate, out_len, &st, head);
    if (status)
        *status = st;
    return buf;
}

