RC_FileStatus rcLoadFile(const char *path, void **bytes, size_t *length) {
    RCI_FileStatus st = RCI_FILE_OK;
    RC_PathInfo info;
    long n = 0;

    if (bytes)
        *bytes = NULL;
    if (length)
        *length = 0;
    if (!path || !*path || !bytes || !length)
        return RC_FILE_INVALID;

    if (rcPathInfo(path, &info) == RC_FILE_OK && info.isDirectory)
        return RC_FILE_WRONG_TYPE;
    *bytes = rci_file_read(path, LONG_MAX - 1, 1, &n, &st);
    if (*bytes) {
        *length = (size_t)n;
        return RC_FILE_OK;
    }
    return st == RCI_FILE_MISSING ? RC_FILE_NOT_FOUND :
           st == RCI_FILE_DENIED  ? RC_FILE_DENIED    : RC_FILE_IO;
}

void rcFreeFile(void *bytes) {
    free(bytes);
}

