char *rci_load_file_beside_path(const char *path) {
    RCI_FileStatus st = RCI_FILE_MISSING;
    const int k = MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, path, -1, NULL, 0);
    wchar_t *w = k > 0 ? (wchar_t *)malloc((size_t)k * sizeof(*w)) : NULL, *cand;
    DWORD a = INVALID_FILE_ATTRIBUTES, e = ERROR_INVALID_NAME;
    char *out = NULL;
    int n;

    if (w && MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, path, -1, w, k) == k &&
        (a = GetFileAttributesW(w)) == INVALID_FILE_ATTRIBUTES)
        e = GetLastError();
    free(w);

    if (a != INVALID_FILE_ATTRIBUTES || (e != ERROR_FILE_NOT_FOUND && e != ERROR_PATH_NOT_FOUND))
        return NULL;
    if ((cand = rci_file_beside_find(path, e, &st)) == NULL)
        return NULL;
    n = WideCharToMultiByte(CP_UTF8, 0, cand, -1, NULL, 0, NULL, NULL);
    if (n > 0 && (out = (char *)malloc((size_t)n)) != NULL &&
        WideCharToMultiByte(CP_UTF8, 0, cand, -1, out, n, NULL, NULL) != n) {
        free(out);
        out = NULL;
    }
    free(cand);
    return out;
}

