typedef enum RCI_TouchPhase {
    RCI_TOUCH_DOWN,
    RCI_TOUCH_MOVE,
    RCI_TOUCH_UP,
    RCI_TOUCH_CANCEL
} RCI_TouchPhase;

typedef struct RCI_TouchEvent {
    RCI_TouchPhase phase;
    double x, y;
} RCI_TouchEvent;

#define RCI_TOUCH_INPUT_CAPACITY 64

typedef struct RCI_TouchInput {
    RCI_TouchEvent pending[RCI_TOUCH_INPUT_CAPACITY];
    RCI_TouchEvent latched[RCI_TOUCH_INPUT_CAPACITY];
    int pendingCount, latchedCount;
    bool active, blocked, waitLatch;

    bool sourceActive;
} RCI_TouchInput;

static inline void rci_touch_input_cancel(RCI_TouchInput *s) {
    RCI_TouchEvent cancel = { RCI_TOUCH_CANCEL, 0.0, 0.0 };

    s->pending[0] = cancel;
    s->pendingCount = 1;
    s->active = false;
    s->blocked = true;
    s->waitLatch = true;
}

static inline bool rci_touch_input_push(RCI_TouchInput *s,
                                       const RCI_TouchEvent *event) {
    if (event) {
        if (event->phase == RCI_TOUCH_DOWN)
            s->sourceActive = true;
        else if (event->phase == RCI_TOUCH_UP || event->phase == RCI_TOUCH_CANCEL)
            s->sourceActive = false;
    }
    if (s->blocked && (s->waitLatch || !event ||
                       event->phase != RCI_TOUCH_DOWN))
        return false;

    if (!event || event->phase < RCI_TOUCH_DOWN ||
        event->phase > RCI_TOUCH_CANCEL ||
        !(event->x >= -DBL_MAX && event->x <= DBL_MAX) ||
        !(event->y >= -DBL_MAX && event->y <= DBL_MAX) ||
        (event->phase == RCI_TOUCH_DOWN ? s->active : !s->active) ||
        s->pendingCount == RCI_TOUCH_INPUT_CAPACITY) {
        rci_touch_input_cancel(s);
        return false;
    }
    if (event->phase == RCI_TOUCH_DOWN) {
        s->active = true;
        s->blocked = false;
    } else if (event->phase == RCI_TOUCH_UP || event->phase == RCI_TOUCH_CANCEL) {
        s->active = false;
    }
    s->pending[s->pendingCount++] = *event;
    return true;
}

static inline bool rci_touch_input_latch(RCI_TouchInput *s, bool down) {
    bool cancel_mouse = s->blocked && s->sourceActive;
    int  n = 0;

    for (; n < s->pendingCount; n++) {
        if (s->pending[n].phase == RCI_TOUCH_DOWN) {
            if (!down)
                break;
            down = false;
        } else if (s->pending[n].phase == RCI_TOUCH_CANCEL) {
            cancel_mouse = true;
        }
        s->latched[n] = s->pending[n];
    }
    s->latchedCount = n;
    s->pendingCount -= n;
    if (n)
        memmove(s->pending, s->pending + n, (size_t)s->pendingCount * sizeof(s->pending[0]));
    s->waitLatch = false;
    return cancel_mouse;
}

static inline void rci_touch_input_drop(RCI_TouchInput *s)
{
    int a = 0, b;

    while (a < s->pendingCount && s->pending[a].phase != RCI_TOUCH_DOWN)
        a++;
    if (a == s->pendingCount)
        return;
    for (b = a + 1; b < s->pendingCount; b++)
        if (s->pending[b].phase == RCI_TOUCH_DOWN)
            break;
    if (b == s->pendingCount && s->active) {
        s->active  = false;
        s->blocked = true;
    }
    memmove(s->pending + a, s->pending + b,
            (size_t)(s->pendingCount - b) * sizeof(s->pending[0]));
    s->pendingCount -= b - a;
}

