static inline bool rci_input_mods_primary(unsigned mods) {
#if defined(__EMSCRIPTEN__)

    if (mods & RCI_INPUT_MOD_SUPER)
        return true;
    return (mods & (RCI_INPUT_MOD_CTRL | RCI_INPUT_MOD_ALT)) == RCI_INPUT_MOD_CTRL;
#elif defined(__APPLE__)
    return (mods & RCI_INPUT_MOD_SUPER) != 0;
#else
    return (mods & (RCI_INPUT_MOD_CTRL | RCI_INPUT_MOD_ALT)) == RCI_INPUT_MOD_CTRL;
#endif
}

static inline bool rci_input_key_shortcut(RCI_Key key, bool repeat) {
    int mods = rci_input_key_mods(key, repeat);

    return mods >= 0 && (mods & RCI_INPUT_MOD_PRIMARY) != 0;
}

#define RCI_INPUT_TEXT_MAX (1 << 20)

const char *rci_input_text(int *len, int *refused);
#define RCI_INPUT_ERASE_CODEPOINT '\xFE'
#define RCI_INPUT_ERASE_UTF16     '\xFF'
#define RCI_INPUT_KEY_RUN         5

#define RCI_INPUT_KEY_CONSUMED    0x01u

static inline bool rci_input_text_consumed(const char *ev) {
    return ((unsigned char)ev[3] & RCI_INPUT_KEY_CONSUMED) != 0u;
}

static inline const char *rci_input_text_typed_end(const char *ev, const char *end) {
    const char *p = ev + RCI_INPUT_KEY_RUN;

    while (p < end) {
        const unsigned char lead = (unsigned char)p[0];
        const size_t        run  = strlen(p);
        const size_t        one  = lead < 0x80u ? 1u : lead < 0xC0u ? 0u : lead < 0xE0u ? 2u
                                 : lead < 0xF0u ? 3u : lead < 0xF8u ? 4u : 0u;

        if (run == 0u || run != one)
            break;
        p += run + 1u;
    }
    return p;
}

int rci_input_text_consume(const char *ev, bool cut);

unsigned rci_input_text_serial(void);

#define RCI_INPUT_COMMAND         '\xFD'
#define RCI_INPUT_TRACK           '\xFC'
#define RCI_INPUT_TRACK_RUN       9
#define RCI_INPUT_TRACK_BIAS      (1L << 20)

static inline int rci_input_text_command(const char *run, const char **payload) {
    const unsigned c = (unsigned char)run[0] == (unsigned char)RCI_INPUT_COMMAND
                     ? (unsigned char)run[1] : 0u;

    if (!(c & 0x80u) || (c & 0x7Fu) == 0u)
        return 0;
    *payload = run + 2;
    return (int)(c & 0x7Fu);
}

static inline int rci_input_text_track(const char *run, float *dx, float *dy) {
    const unsigned char *b = (const unsigned char *)run;
    long v[2];

    if (b[0] != (unsigned char)RCI_INPUT_TRACK || !(b[1] & 0x80u))
        return -1;
    for (int i = 0; i < 2; i++) {
        const unsigned char *q = b + 2 + 3 * i;

        if (!(q[0] & q[1] & q[2] & 0x80u))
            return -1;
        v[i] = ((long)(q[0] & 0x7Fu) << 14 | (long)(q[1] & 0x7Fu) << 7 | (long)(q[2] & 0x7Fu)) -
               RCI_INPUT_TRACK_BIAS;
    }
    *dx = (float)v[0] / 16.0f;
    *dy = (float)v[1] / 16.0f;
    return (int)(b[1] & 0x7Fu);
}

int rci_input_text_key(const char *ev, RCI_Key key, bool repeat);

