static inline size_t rci_input_fold_cr(char *dst, const char *src) {
    const char *r = src;
    char *w = dst;

    while (*r) {
        if (*r == '\r') {
            if (r[1] == '\n')
                r++;
            *w++ = '\n';
            r++;
        } else {
            *w++ = *r++;
        }
    }
    *w = '\0';
    return (size_t)(w - dst);
}

