RC_ImagePixels rci_image_pixels_memory_with_profile(const void *bytes, size_t length,
                                                    const struct RCI_ImageWebpCodec *webp) {
    return rci_image_pixels_memory(bytes, length, RCI_IMAGE_WEBP_PICK(webp));
}

void rcFreeImagePixels(RC_ImagePixels *pixels) {
    if (!pixels)
        return;
    rci_image_free_rgba(pixels->rgba);
    *pixels = (RC_ImagePixels){0};
}

