#  define RCI_JSON_STEP() ((void)0)
#endif

RCI_STATIC_ASSERT(RCI_JSON_WRITE_DEPTH <= sizeof(((RC_JsonWriter *)0)->inObject) * CHAR_BIT,
                  "RC_JsonWriter keeps one bit per open level");
RCI_STATIC_ASSERT(RCI_JSON_READ_DEPTH == YYJSON_READER_DEPTH_LIMIT,
                  "the index's stack is sized by the depth yyjson admits");

typedef struct RCI_JsonRec {
    uint32_t pos;
    uint32_t count;
    uint32_t desc;
    uint32_t table;
} RCI_JsonRec;

typedef struct RCI_JsonBlock {
    size_t       bytes;
    yyjson_doc  *doc;
    yyjson_val  *vals;
    uint32_t     nvals;
    uint32_t     nrecs;
    RCI_JsonRec *recs;
    uint32_t    *pool;
    size_t       npool;
    char        *text;
    size_t       ntext;
    bool         refused;
    RC_JsonErrorKind kind;
    char         error[RCI_JSON_ERROR_MAX];
} RCI_JsonBlock;

typedef struct RCI_JsonSlot {
    RCI_JsonBlock *block;
    uint32_t       token;
} RCI_JsonSlot;

static RCI_JsonSlot *rci_json_slots;
static uint32_t      rci_json_cap;
static uint32_t      rci_json_live;
static uint32_t      rci_json_count;

static size_t rci_json_budget_limit = RCI_JSON_BUDGET;
static size_t rci_json_budget_used;
static size_t rci_json_budget_peak;

static bool rci_json_budget_reserve(size_t n) {
    if (n > rci_json_budget_limit - rci_json_budget_used)
        return false;
    rci_json_budget_used += n;
    if (rci_json_budget_used > rci_json_budget_peak)
        rci_json_budget_peak = rci_json_budget_used;
    return true;
}

static void rci_json_budget_release(size_t n) {
    rci_json_budget_used -= n;
}

static void *rci_json_take(RCI_JsonBlock *b, size_t n) {
    void *p;

    if (!rci_json_budget_reserve(n)) {
        if (b)
            b->refused = true;
        return NULL;
    }
    p = malloc(n);
    if (!p) {
        rci_json_budget_release(n);
        return NULL;
    }
    if (b)
        b->bytes += n;
    return p;
}

static void rci_json_give(RCI_JsonBlock *b, void *p, size_t n) {
    if (!p)
        return;
    free(p);
    rci_json_budget_release(n);
    if (b)
        b->bytes -= n;
}

typedef union RCI_JsonHead {
    size_t    size;
    double    alignD;
    long long alignLl;
    void     *alignP;
} RCI_JsonHead;

static void *rci_json_yy_malloc(void *ctx, size_t size) {
    RCI_JsonHead *h;

    if (size > SIZE_MAX - sizeof(RCI_JsonHead))
        return NULL;
    h = (RCI_JsonHead *)rci_json_take((RCI_JsonBlock *)ctx, size + sizeof *h);
    if (!h)
        return NULL;
    h->size = size + sizeof *h;
    return h + 1;
}

static void *rci_json_yy_realloc(void *ctx, void *ptr, size_t old_size, size_t size) {
    RCI_JsonBlock *b = (RCI_JsonBlock *)ctx;
    RCI_JsonHead  *h, *grown;
    size_t         want;

    (void)old_size;
    if (!ptr)
        return rci_json_yy_malloc(ctx, size);
    if (size > SIZE_MAX - sizeof(RCI_JsonHead))
        return NULL;
    h = (RCI_JsonHead *)ptr - 1;
    want = size + sizeof *h;
    if (!rci_json_budget_reserve(want)) {
        b->refused = true;
        return NULL;
    }
    grown = (RCI_JsonHead *)realloc(h, want);
    if (!grown) {
        rci_json_budget_release(want);
        return NULL;
    }
    rci_json_budget_release(grown->size);
    b->bytes = b->bytes - grown->size + want;
    grown->size = want;
    return grown + 1;
}

static void rci_json_yy_free(void *ctx, void *ptr) {
    RCI_JsonHead *h;

    if (!ptr)
        return;
    h = (RCI_JsonHead *)ptr - 1;
    rci_json_give((RCI_JsonBlock *)ctx, h, h->size);
}

static void rci_json_unread(RCI_JsonBlock *b) {
    yyjson_doc_free(b->doc);
    rci_json_give(b, b->recs, (size_t)b->nrecs * sizeof *b->recs);
    rci_json_give(b, b->pool, b->npool * sizeof *b->pool);
    rci_json_give(b, b->text, b->ntext);
    b->doc = NULL;
    b->recs = NULL;
    b->pool = NULL;
    b->text = NULL;
    b->nrecs = 0;
    b->npool = 0;
    b->ntext = 0;
}

static void rci_json_block_free(void *p) {
    RCI_JsonBlock *b = (RCI_JsonBlock *)p;

    rci_json_unread(b);
    rci_json_give(NULL, b, sizeof *b);
}

static RCI_JsonBlock *rci_json_block(uint32_t token) {
    const RCI_JsonSlot *s;

    if (!rci_json_cap)
        return NULL;
    s = &rci_json_slots[token & (rci_json_cap - 1u)];
    return s->token == token ? s->block : NULL;
}

static bool rci_json_sentinel(uint32_t token) {
    return token != 0 && token <= RCI_JSON_NO_TEXT;
}

static const char *rci_json_sentinel_error(uint32_t token) {
    switch (token) {
    case RCI_JSON_NO_JSON:   return "JSON is compiled out of this build (RC_NO_JSON)";
    case RCI_JSON_NO_MEMORY: return "JSON not read: out of memory (the JSON budget is exhausted)";
    case RCI_JSON_NO_SLOT:
        return "JSON not read: 4095 documents are alive; free each with rcJsonFree";
    case RCI_JSON_NO_TEXT:   return "JSON not read: the text is NULL";
    default:                 return NULL;
    }
}

static RC_JsonErrorKind rci_json_sentinel_kind(uint32_t token) {
    switch (token) {
    case RCI_JSON_NO_JSON:   return RC_JSON_ERROR_DISABLED;
    case RCI_JSON_NO_MEMORY:
    case RCI_JSON_NO_SLOT:   return RC_JSON_ERROR_LIMIT;
    case RCI_JSON_NO_TEXT:   return RC_JSON_ERROR_NO_TEXT;
    default:                 return RC_JSON_ERROR_NONE;
    }
}

static bool rci_json_slots_grow(void) {
    uint32_t      want = rci_json_cap ? rci_json_cap * 2u : 16u;
    RCI_JsonSlot *grown = (RCI_JsonSlot *)rci_json_take(NULL, want * sizeof *grown);
    uint32_t      i;

    if (!grown)
        return false;
    memset(grown, 0, want * sizeof *grown);
    for (i = 0; i < rci_json_cap; i++)
        if (rci_json_slots[i].block)
            grown[rci_json_slots[i].token & (want - 1u)] = rci_json_slots[i];
    rci_json_give(NULL, rci_json_slots, rci_json_cap * sizeof *grown);
    rci_json_slots = grown;
    rci_json_cap = want;
    return true;
}

static uint32_t rci_json_token_next(void) {
    do {
        rci_json_count++;
    } while (rci_json_count <= RCI_JSON_NO_TEXT ||
             rci_json_slots[rci_json_count & (rci_json_cap - 1u)].block);
    return rci_json_count;
}

static uint32_t rci_json_slot_acquire(RCI_JsonBlock *b) {
    RCI_JsonSlot *s;
    uint32_t      token;

    if (rci_json_live >= RCI_JSON_DOCS_MAX)
        return 0;
    if (2u * (rci_json_live + 1u) > rci_json_cap && !rci_json_slots_grow())
        return 0;
    token = rci_json_token_next();
    s = &rci_json_slots[token & (rci_json_cap - 1u)];
    s->block = b;
    s->token = token;
    rci_json_live++;
    return token;
}

static void rci_json_slot_release(uint32_t token) {
    RCI_JsonSlot *s = &rci_json_slots[token & (rci_json_cap - 1u)];

    s->block = NULL;
    s->token = 0;
    rci_json_live--;
}

static uint32_t rci_json_span(const yyjson_val *v) {
    return (uint32_t)(unsafe_yyjson_get_next(v) - v);
}

static bool rci_json_node_ok(const RCI_JsonBlock *b, uint32_t node) {
    return (node & RCI_JSON_TAG) ? (node & ~RCI_JSON_TAG) < b->nrecs : node < b->nvals;
}

static uint32_t rci_json_pos(const RCI_JsonBlock *b, uint32_t node) {
    return (node & RCI_JSON_TAG) ? b->recs[node & ~RCI_JSON_TAG].pos : node;
}

static uint32_t rci_json_node_at(const RCI_JsonBlock *b, uint32_t p, uint32_t rec) {
    return unsafe_yyjson_is_ctn(b->vals + p) ? (RCI_JSON_TAG | rec) : p;
}

static const yyjson_val *rci_json_name(const RCI_JsonBlock *b, uint32_t node) {
    return b->vals + rci_json_pos(b, node) - 1;
}

static uint32_t rci_json_child(const RCI_JsonBlock *b, uint32_t r, uint32_t i) {
    const RCI_JsonRec *rec = &b->recs[r];
    bool               obj = unsafe_yyjson_is_obj(b->vals + rec->pos);
    uint32_t           p, next, k;

    RCI_JSON_STEP();
    if (rec->table != RCI_JSON_NONE)
        return b->pool[rec->table + i];
    if (rec->desc == 0)
        return obj ? rec->pos + 2u + 2u * i : rec->pos + 1u + i;

    p = rec->pos + 1u;
    next = r + 1u;
    for (k = 0;; k++) {
        if (obj)
            p++;
        if (k == i)
            return rci_json_node_at(b, p, next);
        RCI_JSON_STEP();
        if (unsafe_yyjson_is_ctn(b->vals + p)) {
            p += rci_json_span(b->vals + p);
            next += 1u + b->recs[next].desc;
        } else {
            p++;
        }
    }
}

static int rci_json_order(const char *a, size_t an, const char *b, size_t bn) {
    if (an != bn)
        return an < bn ? -1 : 1;
    return an ? memcmp(a, b, an) : 0;
}

static uint32_t rci_json_find(const RCI_JsonBlock *b, uint32_t r, const char *key, size_t len) {
    const RCI_JsonRec *rec = &b->recs[r];
    uint32_t           i;

    if (rec->count > RCI_JSON_SMALL) {
        const uint32_t *sorted = b->pool + rec->table + rec->count;
        uint32_t        lo = 0, hi = rec->count;

        while (lo < hi) {
            uint32_t           mid = lo + (hi - lo) / 2u;
            const yyjson_val  *name = rci_json_name(b, sorted[mid]);
            int                c;

            RCI_JSON_STEP();
            c = rci_json_order(unsafe_yyjson_get_str(name), unsafe_yyjson_get_len(name), key, len);
            if (c == 0)
                return sorted[mid];
            if (c < 0)
                lo = mid + 1u;
            else
                hi = mid;
        }
        return RCI_JSON_NONE;
    }
    for (i = 0; i < rec->count; i++) {
        uint32_t          node = rci_json_child(b, r, i);
        const yyjson_val *name = rci_json_name(b, node);

        if (unsafe_yyjson_get_len(name) == len &&
            (len == 0 || memcmp(unsafe_yyjson_get_str(name), key, len) == 0))
            return node;
    }
    return RCI_JSON_NONE;
}

static bool rci_json_same_name(const yyjson_val *a, const yyjson_val *b) {
    size_t n = unsafe_yyjson_get_len(a);

    return n == unsafe_yyjson_get_len(b) &&
           (n == 0 || memcmp(unsafe_yyjson_get_str(a), unsafe_yyjson_get_str(b), n) == 0);
}

static bool rci_json_before(const RCI_JsonBlock *b, const uint32_t *m, uint32_t x, uint32_t y) {
    const yyjson_val *nx = rci_json_name(b, m[x]);
    const yyjson_val *ny = rci_json_name(b, m[y]);
    int               c = rci_json_order(unsafe_yyjson_get_str(nx), unsafe_yyjson_get_len(nx),
                                         unsafe_yyjson_get_str(ny), unsafe_yyjson_get_len(ny));

    return c < 0 || (c == 0 && x < y);
}

static void rci_json_sift(const RCI_JsonBlock *b, const uint32_t *m, uint32_t *idx,
                          uint32_t root, uint32_t n) {
    for (;;) {
        uint32_t child = 2u * root + 1u, t;

        if (child >= n)
            return;
        if (child + 1u < n && rci_json_before(b, m, idx[child], idx[child + 1u]))
            child++;
        if (!rci_json_before(b, m, idx[root], idx[child]))
            return;
        t = idx[root];
        idx[root] = idx[child];
        idx[child] = t;
        root = child;
    }
}

static void rci_json_sort(const RCI_JsonBlock *b, const uint32_t *m, uint32_t *idx, uint32_t n) {
    uint32_t i, end, t;

    for (i = n / 2u; i-- > 0;)
        rci_json_sift(b, m, idx, i, n);
    for (end = n; end-- > 1u;) {
        t = idx[0];
        idx[0] = idx[end];
        idx[end] = t;
        rci_json_sift(b, m, idx, 0, end);
    }
}

static uint32_t rci_json_key4(const unsigned char *s, size_t n) {
    return (uint32_t)(n > 0 ? s[0] : 0) << 24 | (uint32_t)(n > 1 ? s[1] : 0) << 16 |
           (uint32_t)(n > 2 ? s[2] : 0) << 8 | (uint32_t)(n > 3 ? s[3] : 0);
}

static uint32_t rci_json_key(const yyjson_val *name) {
    size_t n = unsafe_yyjson_get_len(name);

    if (n >= 255)
        return 0xFF000000u;
    return (uint32_t)n << 24 | rci_json_key4((const unsigned char *)unsafe_yyjson_get_str(name), n) >> 8;
}

static void rci_json_sort_words(uint64_t *v, uint32_t n) {
    uint32_t start = n / 2u, end = n;

    while (end > 1u) {
        uint32_t root, child;
        uint64_t x;

        if (start > 0) {
            x = v[--start];
        } else {
            x = v[--end];
            v[end] = v[0];
        }
        for (root = start; (child = 2u * root + 1u) < end; root = child) {
            if (child + 1u < end && v[child] < v[child + 1u])
                child++;
            if (x >= v[child])
                break;
            v[root] = v[child];
        }
        v[root] = x;
    }
}

#define RCI_JSON_RUN_ROUNDS 2u
#define RCI_JSON_RUN_MIN    4u

static void rci_json_sort_run(const RCI_JsonBlock *b, const uint32_t *t, uint32_t *idx, uint32_t n,
                              uint64_t *words, size_t at, unsigned rounds) {
    const yyjson_val    *first = rci_json_name(b, t[idx[0]]);
    const unsigned char *f = (const unsigned char *)unsafe_yyjson_get_str(first);
    size_t               len = unsafe_yyjson_get_len(first), same = len;
    uint32_t             j, s, e;

    if (rounds == 0 || n < RCI_JSON_RUN_MIN) {
        rci_json_sort(b, t, idx, n);
        return;
    }
    for (j = 1; j < n && same > at; j++) {
        const unsigned char *x = (const unsigned char *)unsafe_yyjson_get_str(rci_json_name(b, t[idx[j]]));
        size_t               c = at;

        while (c < same && x[c] == f[c])
            c++;
        same = c;
    }
    if (same >= len || at >= len)
        return;
    for (j = 0; j < n; j++) {
        const unsigned char *x = (const unsigned char *)unsafe_yyjson_get_str(rci_json_name(b, t[idx[j]]));

        words[j] = (uint64_t)rci_json_key4(x + same, len - same) << 32 | idx[j];
    }
    rci_json_sort_words(words, n);
    for (j = 0; j < n; j++)
        idx[j] = (uint32_t)words[j];
    for (s = 0; s < n; s = e) {
        for (e = s + 1u; e < n && words[e] >> 32 == words[s] >> 32;)
            e++;
        if (e - s > 1u)
            rci_json_sort_run(b, t, idx + s, e - s, words + s, same + 4u, rounds - 1u);
    }
}

static uint32_t rci_json_fold_big(const RCI_JsonBlock *b, uint32_t *t, uint32_t k, uint64_t *words) {
    uint32_t *idx = t + k;
    uint32_t  s, e, w = 0, u = 0, j;

    if (words) {
        for (j = 0; j < k; j++)
            words[j] = (uint64_t)rci_json_key(rci_json_name(b, t[j])) << 32 | j;
        rci_json_sort_words(words, k);
        for (j = 0; j < k; j++)
            idx[j] = (uint32_t)words[j];
        for (s = 0; s < k; s = e) {
            for (e = s + 1u; e < k && words[e] >> 32 == words[s] >> 32;)
                e++;
            if (e - s == 1u)
                continue;
            if (words[s] >> 56 == 0xFFu)
                rci_json_sort(b, t, idx + s, e - s);
            else
                rci_json_sort_run(b, t, idx + s, e - s, words + s, 3, RCI_JSON_RUN_ROUNDS);
        }
    } else {
        for (j = 0; j < k; j++)
            idx[j] = j;
        rci_json_sort(b, t, idx, k);
    }
    for (s = 0; s < k; s = e + 1u) {
        uint32_t first = idx[s];

        e = s;
        while (e + 1u < k && rci_json_same_name(rci_json_name(b, t[idx[e + 1u]]),
                                                rci_json_name(b, t[first])))
            e++;
        t[first] = t[idx[e]];
        for (j = s + 1u; j <= e; j++)
            t[idx[j]] = RCI_JSON_NONE;
        idx[w++] = t[first];
    }
    for (j = 0; j < k; j++)
        if (t[j] != RCI_JSON_NONE)
            t[u++] = t[j];
    memmove(t + u, idx, (size_t)w * sizeof *t);
    return u;
}

static uint32_t rci_json_fold_small(const RCI_JsonBlock *b, uint32_t *t, uint32_t k) {
    uint32_t m[RCI_JSON_SMALL];
    uint32_t i, j, u = 0;

    memcpy(m, t, (size_t)k * sizeof *m);
    for (j = 0; j < k; j++) {
        uint32_t last = j;
        bool     seen = false;

        for (i = 0; i < j && !seen; i++)
            seen = rci_json_same_name(rci_json_name(b, m[i]), rci_json_name(b, m[j]));
        if (seen)
            continue;
        for (i = j + 1u; i < k; i++)
            if (rci_json_same_name(rci_json_name(b, m[i]), rci_json_name(b, m[j])))
                last = i;
        t[u++] = m[last];
    }
    return u;
}

static bool rci_json_small_dups(const yyjson_val *vals, uint32_t pos, uint32_t k) {
    const yyjson_val *names[RCI_JSON_SMALL];
    uint32_t          i, j, p = pos + 1u;

    for (i = 0; i < k; i++) {
        names[i] = vals + p;
        p += 1u + rci_json_span(vals + p + 1u);
    }
    for (i = 1; i < k; i++)
        for (j = 0; j < i; j++)
            if (rci_json_same_name(names[i], names[j]))
                return true;
    return false;
}

static bool rci_json_index(RCI_JsonBlock *b) {
    const yyjson_val *vals = b->vals;
    uint32_t          n = b->nvals, nrecs = 0, p, q, r, sp = 0, most = 0;
    uint32_t          stack[RCI_JSON_READ_DEPTH + 1];
    size_t            pool = 0, scratch;
    uint64_t         *words = NULL;

    for (p = 0; p < n; p++)
        if (unsafe_yyjson_is_ctn(vals + p))
            nrecs++;
    if (nrecs == 0)
        return true;
    b->recs = (RCI_JsonRec *)rci_json_take(b, (size_t)nrecs * sizeof *b->recs);
    if (!b->recs)
        return false;
    b->nrecs = nrecs;

    r = 0;
    for (p = 0; p <= n; p++) {
        if (p < n && !unsafe_yyjson_is_ctn(vals + p))
            continue;
        while (sp && (p == n || b->recs[stack[sp - 1u]].table <= p)) {
            uint32_t     closing = stack[--sp];
            RCI_JsonRec *rec = &b->recs[closing];
            bool         obj = unsafe_yyjson_is_obj(vals + rec->pos);
            bool         big = rec->count > RCI_JSON_SMALL;
            bool         table;

            rec->desc = r - closing - 1u;
            if (big)
                table = obj || rec->desc > 0;
            else
                table = obj && rec->count > 1u &&
                        rci_json_small_dups(vals, rec->pos, rec->count);
            rec->table = table ? (uint32_t)pool : RCI_JSON_NONE;
            if (table)
                pool += rec->count + (obj && big ? rec->count : 0u);
            if (obj && big && rec->count > most)
                most = rec->count;
        }
        if (p == n)
            break;
        if (sp == RCI_JSON_READ_DEPTH + 1u)
            return false;
        b->recs[r].pos = p;
        b->recs[r].count = (uint32_t)unsafe_yyjson_get_len(vals + p);
        b->recs[r].desc = 0;
        b->recs[r].table = p + rci_json_span(vals + p);
        stack[sp++] = r++;
    }

    if (pool == 0)
        return true;
    if (pool > UINT32_MAX - 1u)
        return false;
    b->pool = (uint32_t *)rci_json_take(b, pool * sizeof *b->pool);
    if (!b->pool)
        return false;
    b->npool = pool;

    scratch = (size_t)most * sizeof *words;
    if (most && rci_json_budget_reserve(scratch)) {
        words = (uint64_t *)malloc(scratch);
        if (!words)
            rci_json_budget_release(scratch);
    }

    for (q = 0; q < nrecs; q++) {
        RCI_JsonRec *rec = &b->recs[q];
        bool         obj;
        uint32_t    *t, k, i, next;

        if (rec->table == RCI_JSON_NONE)
            continue;
        obj = unsafe_yyjson_is_obj(vals + rec->pos);
        t = b->pool + rec->table;
        k = rec->count;
        p = rec->pos + 1u;
        next = q + 1u;
        for (i = 0; i < k; i++) {
            if (obj)
                p++;
            t[i] = rci_json_node_at(b, p, next);
            if (unsafe_yyjson_is_ctn(vals + p)) {
                p += rci_json_span(vals + p);
                next += 1u + b->recs[next].desc;
            } else {
                p++;
            }
        }
        if (obj)
            rec->count = k > RCI_JSON_SMALL ? rci_json_fold_big(b, t, k, words)
                                            : rci_json_fold_small(b, t, k);
    }
    if (words) {
        free(words);
        rci_json_budget_release(scratch);
    }
    return true;
}

static size_t rci_json_utf8(const unsigned char *s, size_t n, size_t *bad) {
    unsigned char lo = 0x80, hi = 0xBF;
    size_t        need, k;

    if (s[0] < 0x80)
        return 1;
    if (s[0] >= 0xC2 && s[0] <= 0xDF) {
        need = 1;
    } else if (s[0] >= 0xE0 && s[0] <= 0xEF) {
        need = 2;
        if (s[0] == 0xE0) lo = 0xA0;
        if (s[0] == 0xED) hi = 0x9F;
    } else if (s[0] >= 0xF0 && s[0] <= 0xF4) {
        need = 3;
        if (s[0] == 0xF0) lo = 0x90;
        if (s[0] == 0xF4) hi = 0x8F;
    } else {
        *bad = 1;
        return 0;
    }
    for (k = 1; k <= need; k++) {
        if (k >= n || s[k] < lo || s[k] > hi) {
            *bad = k;
            return 0;
        }
        lo = 0x80;
        hi = 0xBF;
    }
    return need + 1;
}

static size_t rci_json_repair(const char *text, size_t length, char *out, bool *bad) {
    const unsigned char *u = (const unsigned char *)text;
    size_t               i = 0, n = 0;

    *bad = false;
    while (i < length) {
        size_t skip = 0, len = rci_json_utf8(u + i, length - i, &skip);

        if (len) {
            if (out)
                memcpy(out + n, text + i, len);
            n += len;
            i += len;
        } else {
            if (out)
                memcpy(out + n, "\xEF\xBF\xBD", 3);
            n += 3;
            i += skip;
            *bad = true;
        }
    }
    return n;
}

static size_t rci_json_unrepair(const char *text, size_t length, size_t pos) {
    const unsigned char *u = (const unsigned char *)text;
    size_t               i = 0, n = 0;

    while (i < length) {
        size_t skip = 0, len = rci_json_utf8(u + i, length - i, &skip);

        if (n + (len ? len : 3) > pos)
            break;
        n += len ? len : 3;
        i += len ? len : skip;
    }
    return i;
}

static RC_Json rci_json_value(uint32_t doc, uint32_t node) {
    RC_Json v;

    v.doc = doc;
    v.node = node;
    return v;
}

static void rci_json_explain(RCI_JsonBlock *b, const char *text, size_t length, size_t bom,
                             const yyjson_read_err *err) {
    const char *read = text;
    size_t      nread = length, byte = err->pos, line = 0, col = 0, chr = 0;
    bool        bad;

    b->kind = RC_JSON_ERROR_LIMIT;
    if (b->refused) {
        snprintf(b->error, sizeof b->error,
                 "JSON not read: it needs more than the %zu MiB JSON budget has left",
                 rci_json_budget_limit >> 20);
        return;
    }
    if (err->code == YYJSON_READ_ERROR_MEMORY_ALLOCATION) {
        snprintf(b->error, sizeof b->error, "JSON not read: out of memory");
        return;
    }
    if (err->code == YYJSON_READ_ERROR_INVALID_PARAMETER ||
        err->code == YYJSON_READ_ERROR_EMPTY_CONTENT) {
        b->kind = RC_JSON_ERROR_SYNTAX;
        snprintf(b->error, sizeof b->error, "invalid JSON: the text is empty");
        return;
    }
    if (b->text) {

        nread = rci_json_repair(text, length, b->text, &bad);
        read = b->text;
        byte = rci_json_unrepair(text, length, err->pos);
    }
    if (!yyjson_locate_pos(read, nread, err->pos, &line, &col, &chr))
        line = col = 0;
    if (err->code == YYJSON_READ_ERROR_DEPTH)
        snprintf(b->error, sizeof b->error,
                 "JSON not read: it nests deeper than %d levels (line %zu, column %zu, byte %zu)",
                 RCI_JSON_READ_DEPTH, line, col, bom + byte);
    else {
        b->kind = RC_JSON_ERROR_SYNTAX;
        snprintf(b->error, sizeof b->error, "invalid JSON: %s (line %zu, column %zu, byte %zu)",
                 err->msg ? err->msg : "unreadable text", line, col, bom + byte);
    }
}

static void rci_json_read_repaired(RCI_JsonBlock *b, const char *text, size_t length,
                                   const yyjson_alc *alc, yyjson_read_err *err) {
    bool   bad;
    size_t n = rci_json_repair(text, length, NULL, &bad);

    if (!bad)
        return;
    b->text = (char *)rci_json_take(b, n + YYJSON_PADDING_SIZE);
    if (!b->text) {
        err->code = YYJSON_READ_ERROR_MEMORY_ALLOCATION;
        return;
    }
    b->ntext = n + YYJSON_PADDING_SIZE;
    rci_json_repair(text, length, b->text, &bad);
    memset(err, 0, sizeof *err);
    b->doc = yyjson_read_opts(b->text, n, RCI_JSON_READ_FLAGS | YYJSON_READ_INSITU, alc, err);
}

RC_Json rcJsonParse(const char *text, size_t length) {
    RCI_ZONE("rc json parse");
    RCI_JsonBlock  *b;
    yyjson_alc      alc;
    yyjson_read_err err;
    uint32_t        token;
    size_t          bom;

    if (!text)
        return rci_json_value(RCI_JSON_NO_TEXT, 0);
    if (length == (size_t)-1)
        length = strlen(text);
    else if (length == 0 && text[0] != '\0')
        RCI_LOG_WARN_ONCE("rcJsonParse: a length of 0 is an empty text; pass (size_t)-1 for a "
                          "NUL-terminated one");

    bom = length >= 3 && memcmp(text, "\xEF\xBB\xBF", 3) == 0 ? 3 : 0;
    text += bom;
    length -= bom;

    b = (RCI_JsonBlock *)rci_json_take(NULL, sizeof *b);
    if (!b) {
        RCI_LOG_WARN_ONCE("rcJsonParse: out of memory for a document (JSON budget %zu MiB)",
                          rci_json_budget_limit >> 20);
        return rci_json_value(RCI_JSON_NO_MEMORY, 0);
    }
    memset(b, 0, sizeof *b);
    b->bytes = sizeof *b;
    token = rci_json_slot_acquire(b);
    if (!token) {
        rci_json_give(NULL, b, sizeof *b);
        if (rci_json_live < RCI_JSON_DOCS_MAX) {
            RCI_LOG_WARN_ONCE("rcJsonParse: out of memory for a document (JSON budget %zu MiB)",
                              rci_json_budget_limit >> 20);
            return rci_json_value(RCI_JSON_NO_MEMORY, 0);
        }
        RCI_LOG_WARN_ONCE("rcJsonParse: %u JSON documents are alive; free each with rcJsonFree",
                          RCI_JSON_DOCS_MAX);
        return rci_json_value(RCI_JSON_NO_SLOT, 0);
    }

    alc.malloc = rci_json_yy_malloc;
    alc.realloc = rci_json_yy_realloc;
    alc.free = rci_json_yy_free;
    alc.ctx = b;
    memset(&err, 0, sizeof err);
    b->doc = yyjson_read_opts((char *)text, length, RCI_JSON_READ_FLAGS, &alc, &err);
    if (!b->doc && !b->refused && err.code != YYJSON_READ_ERROR_MEMORY_ALLOCATION)
        rci_json_read_repaired(b, text, length, &alc, &err);
    if (!b->doc) {
        rci_json_explain(b, text, length, bom, &err);
        rci_json_unread(b);
    } else if (yyjson_doc_get_val_count(b->doc) >= RCI_JSON_TAG) {
        rci_json_unread(b);
        b->kind = RC_JSON_ERROR_LIMIT;
        snprintf(b->error, sizeof b->error, "JSON not read: it holds more than %u values",
                 RCI_JSON_TAG - 1u);
    } else {
        b->vals = yyjson_doc_get_root(b->doc);
        b->nvals = (uint32_t)yyjson_doc_get_val_count(b->doc);
        if (!rci_json_index(b)) {
            rci_json_unread(b);
            b->kind = RC_JSON_ERROR_LIMIT;
            if (b->refused)
                snprintf(b->error, sizeof b->error,
                         "JSON not read: it needs more than the %zu MiB JSON budget has left",
                         rci_json_budget_limit >> 20);
            else
                snprintf(b->error, sizeof b->error, "JSON not read: out of memory");
        }
    }
    if (b->refused)
        RCI_LOG_WARN_ONCE("rcJsonParse: the %zu MiB JSON budget refused a document",
                          rci_json_budget_limit >> 20);
    return rci_json_value(token, b->doc ? rci_json_node_at(b, 0, 0) : 0);
}

void rcJsonFree(RC_Json root) {
    RCI_JsonBlock *b = rci_json_block(root.doc);

    if (!b)
        return;
    rci_json_slot_release(root.doc);
    rci_base_defer_free(b, rci_json_block_free);
}

static const yyjson_val *rci_json_val(RC_Json v, const RCI_JsonBlock **bp) {
    const RCI_JsonBlock *b = rci_json_block(v.doc);

    if (!b || !b->doc || !rci_json_node_ok(b, v.node))
        return NULL;
    if (bp)
        *bp = b;
    return b->vals + rci_json_pos(b, v.node);
}

const char *rcJsonError(RC_Json v) {
    const RCI_JsonBlock *b = rci_json_block(v.doc);

    if (b)
        return b->doc ? NULL : b->error;
    return rci_json_sentinel_error(v.doc);
}

RC_JsonErrorKind rcJsonErrorKind(RC_Json v) {
    const RCI_JsonBlock *b = rci_json_block(v.doc);

    return b ? b->kind : rci_json_sentinel_kind(v.doc);
}

RC_JsonType rcJsonType(RC_Json v) {
    const RCI_JsonBlock *b = rci_json_block(v.doc);
    const yyjson_val    *val;

    if (!b)
        return rci_json_sentinel(v.doc) ? RC_JSON_INVALID : RC_JSON_MISSING;
    if (!b->doc)
        return RC_JSON_INVALID;
    val = rci_json_val(v, NULL);
    if (!val)
        return RC_JSON_MISSING;
    switch (unsafe_yyjson_get_type(val)) {
    case YYJSON_TYPE_NULL: return RC_JSON_NULL;
    case YYJSON_TYPE_BOOL: return RC_JSON_BOOL;
    case YYJSON_TYPE_RAW:  return RC_JSON_NUMBER;
    case YYJSON_TYPE_NUM:  return RC_JSON_NUMBER;
    case YYJSON_TYPE_STR:  return RC_JSON_STRING;
    case YYJSON_TYPE_ARR:  return RC_JSON_ARRAY;
    case YYJSON_TYPE_OBJ:  return RC_JSON_OBJECT;
    default:               return RC_JSON_MISSING;
    }
}

RC_Json rcJsonGet(RC_Json v, const char *path) {
    const RCI_JsonBlock *b = rci_json_block(v.doc);
    RC_Json              missing = rci_json_value(0, 0);
    uint32_t             node = v.node;
    bool                 first = true;
    const char          *p = path;

    if (!b)
        return rci_json_sentinel(v.doc) ? v : missing;
    if (!b->doc)
        return v;
    if (!rci_json_node_ok(b, node))
        return missing;
    while (p && *p) {
        const char        *name;
        size_t             len;
        const yyjson_val  *val = b->vals + rci_json_pos(b, node);
        bool               index = *p == '[';

        if (index) {
            name = ++p;
            while (*p >= '0' && *p <= '9')
                p++;
            len = (size_t)(p - name);
            if (len == 0 || *p != ']')
                return missing;
            p++;
        } else {
            if (*p == '.') {
                if (first)
                    return missing;
                p++;
            } else if (!first) {
                return missing;
            }
            name = p;
            while (*p && *p != '.' && *p != '[')
                p++;
            len = (size_t)(p - name);
            if (len == 0)
                return missing;
        }
        first = false;
        if (!(node & RCI_JSON_TAG))
            return missing;
        if (unsafe_yyjson_is_arr(val)) {
            uint32_t i = 0;
            size_t   d;

            if (!index || (len > 1 && name[0] == '0'))
                return missing;
            for (d = 0; d < len; d++) {
                if (i > (UINT32_MAX - 9u) / 10u)
                    return missing;
                i = i * 10u + (uint32_t)(name[d] - '0');
            }
            if (i >= b->recs[node & ~RCI_JSON_TAG].count)
                return missing;
            node = rci_json_child(b, node & ~RCI_JSON_TAG, i);
        } else {
            node = rci_json_find(b, node & ~RCI_JSON_TAG, name, len);
            if (node == RCI_JSON_NONE)
                return missing;
        }
    }
    return rci_json_value(v.doc, node);
}

int rcJsonCount(RC_Json v) {
    const RCI_JsonBlock *b = NULL;

    if (!rci_json_val(v, &b) || !(v.node & RCI_JSON_TAG))
        return 0;
    return (int)b->recs[v.node & ~RCI_JSON_TAG].count;
}

RC_Json rcJsonAt(RC_Json v, int i) {
    const RCI_JsonBlock *b = NULL;
    uint32_t             r;

    if (rcJsonType(v) == RC_JSON_INVALID)
        return v;
    if (!rci_json_val(v, &b) || !(v.node & RCI_JSON_TAG) || i < 0)
        return rci_json_value(0, 0);
    r = v.node & ~RCI_JSON_TAG;
    if ((uint32_t)i >= b->recs[r].count)
        return rci_json_value(0, 0);
    return rci_json_value(v.doc, rci_json_child(b, r, (uint32_t)i));
}

static RC_String rci_json_string(const char *chars, size_t length) {
    RC_String s;

    memset(&s, 0, sizeof s);
    s.chars = chars;
    s.length = (int32_t)(length > INT32_MAX ? INT32_MAX : length);
    return s;
}

RC_String rcJsonKey(RC_Json v, int i) {
    const RCI_JsonBlock *b = NULL;
    const yyjson_val    *val = rci_json_val(v, &b);
    const yyjson_val    *name;
    uint32_t             r;

    if (!val || !unsafe_yyjson_is_obj(val) || i < 0)
        return rci_json_string("", 0);
    r = v.node & ~RCI_JSON_TAG;
    if ((uint32_t)i >= b->recs[r].count)
        return rci_json_string("", 0);
    name = rci_json_name(b, rci_json_child(b, r, (uint32_t)i));
    return rci_json_string(unsafe_yyjson_get_str(name), unsafe_yyjson_get_len(name));
}

static bool rci_json_text(const yyjson_val *val, const char **s, size_t *n) {
    if (!val)
        return false;
    switch (unsafe_yyjson_get_type(val)) {
    case YYJSON_TYPE_STR:
    case YYJSON_TYPE_RAW:
        *s = unsafe_yyjson_get_str(val);
        *n = unsafe_yyjson_get_len(val);
        return true;
    case YYJSON_TYPE_BOOL:
        *s = unsafe_yyjson_get_bool(val) ? "true" : "false";
        *n = strlen(*s);
        return true;
    default:
        return false;
    }
}

const char *rcJsonString(RC_Json v, const char *path, const char *fallback) {
    const char *s;
    size_t      n;

    return rci_json_text(rci_json_val(rcJsonGet(v, path), NULL), &s, &n) ? s : fallback;
}

RC_String rcJsonText(RC_Json v, const char *path) {
    const char *s;
    size_t      n;

    if (!rci_json_text(rci_json_val(rcJsonGet(v, path), NULL), &s, &n))
        return rci_json_string("", 0);
    return rci_json_string(s, n);
}

static bool rci_json_number(RC_Json v, const char *path, yyjson_val *num,
                            const char **text, bool *overflow) {
    const yyjson_val *val = rci_json_val(rcJsonGet(v, path), NULL);
    yyjson_read_err   err;

    if (!val || !unsafe_yyjson_is_raw(val))
        return false;
    *text = unsafe_yyjson_get_raw(val);
    *overflow = !yyjson_read_number(*text, num, 0, NULL, &err);
    return true;
}

double rcJsonNumber(RC_Json v, const char *path, double fallback) {
    yyjson_val  num;
    const char *text;
    bool        overflow;
    double      value;

    if (!rci_json_number(v, path, &num, &text, &overflow))
        return fallback;
    if (overflow)
        return text[0] == '-' ? -HUGE_VAL : HUGE_VAL;
    value = unsafe_yyjson_get_num(&num);
    return value == 0.0 && text[0] == '-' ? -0.0 : value;
}

int64_t rcJsonInt64(RC_Json v, const char *path, int64_t fallback) {
    yyjson_val  num;
    const char *text;
    bool        overflow;

    if (!rci_json_number(v, path, &num, &text, &overflow) || overflow)
        return fallback;
    if (unsafe_yyjson_is_sint(&num))
        return unsafe_yyjson_get_sint(&num);
    if (unsafe_yyjson_is_uint(&num) && unsafe_yyjson_get_uint(&num) <= (uint64_t)INT64_MAX)
        return (int64_t)unsafe_yyjson_get_uint(&num);
    return fallback;
}

uint64_t rcJsonUint64(RC_Json v, const char *path, uint64_t fallback) {
    yyjson_val  num;
    const char *text;
    bool        overflow;

    if (!rci_json_number(v, path, &num, &text, &overflow) || overflow)
        return fallback;
    if (unsafe_yyjson_is_uint(&num))
        return unsafe_yyjson_get_uint(&num);
    if (unsafe_yyjson_is_sint(&num) && unsafe_yyjson_get_sint(&num) == 0)
        return 0;
    return fallback;
}

bool rcJsonBool(RC_Json v, const char *path, bool fallback) {
    const yyjson_val *val = rci_json_val(rcJsonGet(v, path), NULL);

    if (!val || !unsafe_yyjson_is_bool(val))
        return fallback;
    return unsafe_yyjson_get_bool(val);
}

static void rci_json_misuse(RC_JsonWriter *w) {
    w->failed = true;
    w->misuse = true;
}

RC_JsonWriter rcJsonWriter(char *buffer, size_t capacity) {
    RC_JsonWriter w;

    memset(&w, 0, sizeof w);
    w.buf = buffer;
    w.cap = capacity;
    if (!buffer && capacity)
        rci_json_misuse(&w);
    else if (capacity == 0)
        w.failed = w.full = true;
    return w;
}

static void rci_json_put(RC_JsonWriter *w, const char *s, size_t n) {
    if (w->misuse)
        return;
    w->needed += n;
    if (w->full)
        return;
    if (n >= w->cap - w->len) {
        w->failed = w->full = true;
        return;
    }
    memcpy(w->buf + w->len, s, n);
    w->len += n;
}

static void rci_json_put_string(RC_JsonWriter *w, const char *s, size_t n) {
    static const char hex[] = "0123456789abcdef";
    const unsigned char *u = (const unsigned char *)s;
    size_t               i = 0, run;

    rci_json_put(w, "\"", 1);
    while (i < n && !w->misuse) {
        size_t bad = 0, len;

        for (run = i; run < n && u[run] >= 0x20 && u[run] < 0x80 &&
                      u[run] != '"' && u[run] != '\\'; run++)
            ;
        rci_json_put(w, s + i, run - i);
        i = run;
        if (i >= n)
            break;
        if (u[i] >= 0x80) {
            len = rci_json_utf8(u + i, n - i, &bad);
            if (len)
                rci_json_put(w, s + i, len);
            else
                rci_json_put(w, "\xEF\xBF\xBD", 3);
            i += len ? len : bad;
            continue;
        }
        switch (u[i]) {
        case '"':  rci_json_put(w, "\\\"", 2); break;
        case '\\': rci_json_put(w, "\\\\", 2); break;
        case '\b': rci_json_put(w, "\\b", 2);  break;
        case '\f': rci_json_put(w, "\\f", 2);  break;
        case '\n': rci_json_put(w, "\\n", 2);  break;
        case '\r': rci_json_put(w, "\\r", 2);  break;
        case '\t': rci_json_put(w, "\\t", 2);  break;
        default: {
            char e[6];

            e[0] = '\\'; e[1] = 'u'; e[2] = '0'; e[3] = '0';
            e[4] = hex[u[i] >> 4];
            e[5] = hex[u[i] & 15u];
            rci_json_put(w, e, sizeof e);
            break;
        }
        }
        i++;
    }
    rci_json_put(w, "\"", 1);
}

static bool rci_json_in_object(const RC_JsonWriter *w) {
    unsigned level = (unsigned)w->depth - 1u;

    return ((w->inObject[level / 32u] >> (level % 32u)) & 1u) != 0;
}

static bool rci_json_lead(RC_JsonWriter *w, const char *key) {
    if (!w || w->misuse)
        return false;
    if (w->depth == 0) {
        if (key || w->needed)
            rci_json_misuse(w);
        return !w->misuse;
    }
    if (rci_json_in_object(w) != (key != NULL)) {
        rci_json_misuse(w);
        return false;
    }
    if (!w->first)
        rci_json_put(w, ",", 1);
    w->first = false;
    if (key) {
        rci_json_put_string(w, key, strlen(key));
        rci_json_put(w, ":", 1);
    }
    return !w->misuse;
}

static void rci_json_open(RC_JsonWriter *w, const char *key, bool obj) {
    unsigned level;
    uint32_t bit;

    if (!rci_json_lead(w, key))
        return;
    if (w->depth == RCI_JSON_WRITE_DEPTH) {
        rci_json_misuse(w);
        return;
    }
    rci_json_put(w, obj ? "{" : "[", 1);
    level = (unsigned)w->depth++;
    bit = 1u << (level % 32u);
    if (obj)
        w->inObject[level / 32u] |= bit;
    else
        w->inObject[level / 32u] &= ~bit;
    w->first = true;
}

void rcJsonBeginObject(RC_JsonWriter *w, const char *key) {
    rci_json_open(w, key, true);
}

void rcJsonBeginArray(RC_JsonWriter *w, const char *key) {
    rci_json_open(w, key, false);
}

void rcJsonEnd(RC_JsonWriter *w) {
    if (!w || w->misuse)
        return;
    if (w->depth == 0) {
        rci_json_misuse(w);
        return;
    }
    rci_json_put(w, rci_json_in_object(w) ? "}" : "]", 1);
    w->depth--;
    w->first = false;
}

void rcJsonWriteString(RC_JsonWriter *w, const char *key, const char *value) {
    if (!rci_json_lead(w, key))
        return;
    if (value)
        rci_json_put_string(w, value, strlen(value));
    else
        rci_json_put(w, "null", 4);
}

void rcJsonWriteText(RC_JsonWriter *w, const char *key, RC_String value) {
    if (!rci_json_lead(w, key))
        return;
    if (value.chars)
        rci_json_put_string(w, value.chars, value.length > 0 ? (size_t)value.length : 0);
    else
        rci_json_put(w, "null", 4);
}

static void rci_json_put_number(RC_JsonWriter *w, const yyjson_val *num) {
    char  text[40];
    char *end = yyjson_write_number(num, text);

    if (!end) {
        rci_json_misuse(w);
        return;
    }
    if (end - text > 2 && end[-2] == '.' && end[-1] == '0')
        end -= 2;
    rci_json_put(w, text, (size_t)(end - text));
}

void rcJsonWriteNumber(RC_JsonWriter *w, const char *key, double value) {
    yyjson_val num;

    if (!rci_json_lead(w, key))
        return;
    if (!rci_isfinite_d(value)) {
        rci_json_put(w, "null", 4);
        return;
    }

    if (value == floor(value) && fabs(value) < 9007199254740992.0)
        unsafe_yyjson_set_sint(&num, (int64_t)value);
    else
        unsafe_yyjson_set_real(&num, value);
    rci_json_put_number(w, &num);
}

void rcJsonWriteInt64(RC_JsonWriter *w, const char *key, int64_t value) {
    yyjson_val num;

    if (!rci_json_lead(w, key))
        return;
    unsafe_yyjson_set_sint(&num, value);
    rci_json_put_number(w, &num);
}

void rcJsonWriteUint64(RC_JsonWriter *w, const char *key, uint64_t value) {
    yyjson_val num;

    if (!rci_json_lead(w, key))
        return;
    unsafe_yyjson_set_uint(&num, value);
    rci_json_put_number(w, &num);
}

void rcJsonWriteBool(RC_JsonWriter *w, const char *key, bool value) {
    if (!rci_json_lead(w, key))
        return;
    rci_json_put(w, value ? "true" : "false", value ? 4 : 5);
}

void rcJsonWriteNull(RC_JsonWriter *w, const char *key) {
    if (!rci_json_lead(w, key))
        return;
    rci_json_put(w, "null", 4);
}

static void rci_json_put_value(RC_JsonWriter *w, const RCI_JsonBlock *b, uint32_t node,
                               int level) {
    const yyjson_val *val = b->vals + rci_json_pos(b, node);
    uint32_t          r, i, count;
    bool              obj;

    if (!unsafe_yyjson_is_ctn(val)) {
        switch (unsafe_yyjson_get_type(val)) {
        case YYJSON_TYPE_NULL:
            rci_json_put(w, "null", 4);
            break;
        case YYJSON_TYPE_BOOL: {
            bool on = unsafe_yyjson_get_bool(val);

            rci_json_put(w, on ? "true" : "false", on ? 4 : 5);
            break;
        }
        case YYJSON_TYPE_STR:
            rci_json_put_string(w, unsafe_yyjson_get_str(val), unsafe_yyjson_get_len(val));
            break;
        default:
            rci_json_put(w, unsafe_yyjson_get_raw(val), unsafe_yyjson_get_len(val));
            break;
        }
        return;
    }
    if (level > RCI_JSON_WRITE_DEPTH) {
        rci_json_misuse(w);
        return;
    }
    obj   = unsafe_yyjson_is_obj(val);
    r     = node & ~RCI_JSON_TAG;
    count = b->recs[r].count;
    rci_json_put(w, obj ? "{" : "[", 1);
    for (i = 0; i < count && !w->misuse; i++) {
        uint32_t child = rci_json_child(b, r, i);

        if (i > 0)
            rci_json_put(w, ",", 1);
        if (obj) {
            const yyjson_val *name = rci_json_name(b, child);

            rci_json_put_string(w, unsafe_yyjson_get_str(name), unsafe_yyjson_get_len(name));
            rci_json_put(w, ":", 1);
        }
        rci_json_put_value(w, b, child, level + 1);
    }
    rci_json_put(w, obj ? "}" : "]", 1);
}

void rcJsonWriteValue(RC_JsonWriter *w, const char *key, RC_Json value) {
    const RCI_JsonBlock *b = NULL;

    if (!w || w->misuse)
        return;
    if (rci_json_val(value, &b)) {
        if (rci_json_lead(w, key))
            rci_json_put_value(w, b, value.node, w->depth + 1);
    } else if (value.doc != 0) {
        rci_json_misuse(w);
    } else if (w->depth > 0 && !rci_json_in_object(w)) {
        rcJsonWriteNull(w, key);
    } else if ((w->depth > 0) != (key != NULL)) {
        rci_json_misuse(w);
    }
}

const char *rcJsonWriterFinish(RC_JsonWriter *w) {
    if (!w || w->failed || w->depth != 0 || w->len == 0)
        return NULL;
    w->buf[w->len] = '\0';
    return w->buf;
}

