static const unsigned char rci_update_crypto_order[32] = {
    0xed, 0xd3, 0xf5, 0x5c, 0x1a, 0x63, 0x12, 0x58, 0xd6, 0x9c, 0xf7, 0xa2, 0xde, 0xf9, 0xde, 0x14,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x10
};

static bool rci_update_crypto_below_order(const unsigned char *s) {
    int i;

    for (i = 31; i >= 0; i--) {
        if (s[i] != rci_update_crypto_order[i])
            return s[i] < rci_update_crypto_order[i];
    }
    return false;
}

