typedef struct RCI_WindowTextState {
    bool  focused, editable, secret, has_text, has_selection, allSelected;
    float caret[4], selection[4];
} RCI_WindowTextState;

static inline bool rci_window_text_offers(const RCI_WindowTextState *st, int command,
                                          bool clip_has_text) {
    if (!st || !st->focused)
        return false;
    switch (command) {
    case RCI_WINDOW_TEXT_CUT:        return st->has_selection && st->editable && !st->secret;
    case RCI_WINDOW_TEXT_COPY:       return st->has_selection && !st->secret;
    case RCI_WINDOW_TEXT_PASTE:      return st->editable && clip_has_text;
    case RCI_WINDOW_TEXT_SELECT:     return st->has_text && !st->has_selection;
    case RCI_WINDOW_TEXT_SELECT_ALL: return st->has_text && !st->allSelected;
    default:                         return false;
    }
}

