#include <stdbool.h>

#define RCI_TEXT_TOUCH_REACH 22.0f

typedef struct RCI_TextTouch {
    bool  caretDrag;
    bool  floating;
    float fingerX, fingerY;
    float anchorX, anchorY;
} RCI_TextTouch;

static inline bool rci_text_touch_in(const float r[4], float x, float y) {
    return r[2] > 0.0f && r[3] > 0.0f &&
           x >= r[0] && x <= r[0] + r[2] && y >= r[1] && y <= r[1] + r[3];
}

static inline bool rci_text_touch_on_caret(const float r[4], float x, float y, float reachY) {
    const float cx = r[0] + r[2] * 0.5f;
    const float dx = x < cx ? cx - x : x - cx;
    const float dy = y < r[1] ? r[1] - y : y > r[1] + r[3] ? y - (r[1] + r[3]) : 0.0f;

    return r[3] > 0.0f && dx <= RCI_TEXT_TOUCH_REACH && dy <= reachY;
}

static inline int rci_text_touch_tap(bool wasFocused, bool hasSelection, bool onCaret,
                                     bool inSelection, bool *place) {
    const bool toggles = wasFocused && (hasSelection ? inSelection : onCaret);

    *place = !toggles;
    return toggles ? 2 : 0;
}

#define RCI_TEXT_TOUCH_TAP_S (RCI_TOUCH_LONGPRESS_S + 0.1)

static inline bool rci_text_touch_menu_was_shown(bool shown, double dismissed, double now) {
    return shown || (now >= dismissed && now - dismissed < RCI_TEXT_TOUCH_TAP_S);
}

static inline void rci_text_touch_long_begin(RCI_TextTouch *t, float x, float y) {
    t->caretDrag = true;
    t->fingerX   = x;
    t->fingerY   = y;
}

static inline bool rci_text_touch_long_move(RCI_TextTouch *t, float x, float y) {
    if (!t->caretDrag || (x == t->fingerX && y == t->fingerY))
        return false;
    t->fingerX = x;
    t->fingerY = y;
    return true;
}

static inline bool rci_text_touch_long_end(RCI_TextTouch *t, bool canceled) {
    const bool held = t->caretDrag;

    t->caretDrag = false;
    return held && !canceled;
}

static inline void rci_text_touch_float_begin(RCI_TextTouch *t, const float caret[4]) {
    t->floating = true;
    t->anchorX  = caret[0] + caret[2] * 0.5f;
    t->anchorY  = caret[1] + caret[3] * 0.5f;
}

static inline bool rci_text_touch_float_target(const RCI_TextTouch *t, float dx, float dy,
                                               float *x, float *y) {
    if (!t->floating)
        return false;
    *x = t->anchorX + dx;
    *y = t->anchorY + dy;
    return true;
}

static inline void rci_text_touch_float_end(RCI_TextTouch *t) {
    t->floating = false;
}

#define RCI_TEXT_QUEUE_MAX 16

enum { RCI_TEXT_QUEUE_COMMAND, RCI_TEXT_QUEUE_TRACK };

typedef struct RCI_TextQueueEvent {
    int   kind;
    int   code;
    float dx, dy;
} RCI_TextQueueEvent;

typedef struct RCI_TextQueue {
    RCI_TextQueueEvent ev[RCI_TEXT_QUEUE_MAX];
    int n;
    int dropped;
} RCI_TextQueue;

static inline bool rci_text_queue_push(RCI_TextQueue *q, int kind, int code, float dx, float dy) {
    RCI_TextQueueEvent *last = q->n > 0 ? &q->ev[q->n - 1] : 0;

    if (kind == RCI_TEXT_QUEUE_TRACK && code == 1 && last && last->kind == RCI_TEXT_QUEUE_TRACK &&
        last->code == 1) {
        last->dx = dx;
        last->dy = dy;
        return true;
    }
    if (q->n >= RCI_TEXT_QUEUE_MAX) {
        q->dropped++;
        return false;
    }
    q->ev[q->n].kind = kind;
    q->ev[q->n].code = code;
    q->ev[q->n].dx   = dx;
    q->ev[q->n].dy   = dy;
    q->n++;
    return true;
}

