static inline void rci_textedit_wipe(void *data, size_t size) {
    volatile unsigned char *bytes = data;
    while (size--)
        *bytes++ = 0;
}

static inline int rci_textedit_registry_find(const RCI_TexteditContext *c, uint32_t id) {
    unsigned int mask = 2u * (unsigned int)c->inputCap - 1u;
    unsigned int s    = id & mask;
    while (c->inputIndex[s] && c->inputs[c->inputIndex[s] - 1].borderId != id)
        s = (s + 1u) & mask;
    return (int)s;
}

#ifndef RC_EDIT_BLINK_TIMEOUT
#define RC_EDIT_BLINK_TIMEOUT 10.0
#endif

static inline void rci_textedit_comp_end(void) {
    rci_textedit_context->compA = rci_textedit_context->compB = 0;
}

static inline int rci_textedit_clampi(int v, int lo, int hi) {
    return v < lo ? lo : (v > hi ? hi : v);
}

static inline bool rci_textedit_edit_sel_range(int len, int *a, int *e) {
    if (*a == *e) return false;
    if (*a > *e) { int t = *a; *a = *e; *e = t; }
    *a = rci_textedit_clampi(*a, 0, len);
    *e = rci_textedit_clampi(*e, 0, len);
    return true;
}
