int rci_textedit_textinput_focused_keyboard(void) {
    const RCI_TexteditContext *c = rci_textedit_context;

    if (!rci_focus_field())
        return RCI_KEYBOARD_TEXT;
    return c->focusedKindKnown ? c->focusedKeyboard : RCI_KEYBOARD_PASSWORD;
}

bool rci_textedit_textinput_read_only(void) {
    return rci_focus_field() && rci_textedit_context->focusedReadOnly;
}

bool rci_textedit_textinput_edited(void) {
#ifdef __EMSCRIPTEN__
    return rci_focus_field() &&
           (rci_textedit_context->dirty || rci_textedit_context->pulled);
#else
    return rci_focus_field() && rci_textedit_context->dirty;
#endif
}

