static void rci_textedit_publish(RCI_TexteditContext *c) {
    RCI_WindowTextState st;
    const RCI_TexteditInputReg *f = NULL;
    CLAY_BoundingBox r;

    memset(&st, 0, sizeof st);

    for (int i = rci_focus_field() ? c->inputCount - 1 : -1; i >= 0 && !f; i--)
        if (c->inputs[i].idHash == rci_focus_id())
            f = &c->inputs[i];
    if (f && c->imeField == rci_focus_id()) {
        int a = c->edit.select_start, b = c->edit.select_end;

        st.focused       = true;
        st.editable      = !f->inert && !f->disabled && !f->readOnly;
        st.secret        = f->password;
        st.has_text      = f->len > 0;
        st.has_selection = rci_textedit_edit_sel_range(f->len, &a, &b);
        st.allSelected  = st.has_selection && a == 0 && b == f->len;
        r = rci_api_window_box(c->imeCaret);
        st.caret[0] = r.x;
        st.caret[1] = r.y;
        st.caret[2] = r.width;
        st.caret[3] = r.height;
        if (st.has_selection && c->selNoted) {
            r = rci_api_window_box(c->selBox);
            st.selection[0] = r.x;
            st.selection[1] = r.y;
            st.selection[2] = r.width;
            st.selection[3] = r.height;
        }
    }
    c->selNoted = false;
    if (!st.focused && !c->published.focused)
        return;
    if (!st.focused) {
        c->touch.caretDrag = false;
        c->touch.floating  = false;
        c->menuMaybe       = false;
    }
    c->published = st;
    rci_window_text_state(&st);
}
#endif

void rci_textedit_textinput_frame_reset(void) {
    RCI_TexteditContext *c = rci_textedit_context;
    rci_textedit_registry_clear(c);
    rci_focus_frame_reset();
#ifdef __EMSCRIPTEN__
    rci_textedit_context->pulled = false;
#endif
    rci_textedit_context->frameStart = rci_input_time();
    if (rci_input_mouse_pressed(RC_POINTER_LEFT))
        rci_textedit_context->pressCount++;
}

void rci_textedit_textinput_layout_end(void) {
    RCI_TexteditContext *c = rci_textedit_context;
    rci_focus_layout_end();

    rci_textedit_area_sweep(c);
    c->areaSwept = true;
}

bool rci_textedit_wheel_claim(float dx, float dy) {
    RCI_TexteditContext *c = rci_textedit_context;

    if (dy == 0.0f || !isfinite(dy) || (isfinite(dx) && fabsf(dx) > fabsf(dy)))
        return false;
    const RCI_TexteditArea *a    = NULL;
    int32_t                 rank = 0;
    for (int i = 0; i < c->areaCount; ++i) {
        const RCI_TexteditArea *e = &c->areas[i];
        int32_t                 r;
        if (!clayPointerOver((CLAY_ElementId){ .id = e->id }))
            continue;
        r = rci_core_clay_paint_rank(e->id);
        if (!a || r > rank) {
            a    = e;
            rank = r;
        }
    }
    if (!a)
        return false;
    const float y = rci_focus_field() && rci_focus_id() == a->id ? c->scrollY : a->scrollY;
    if (dy < 0.0f ? y <= 0.0f : y >= a->maxY)
        return false;
    c->wheelId = a->id;
    c->wheelDy = dy;
    return true;
}

uint32_t rci_textedit_wheel_target(void) {
    return rci_textedit_context->wheelId;
}

bool rci_textedit_wheel_to(uint32_t id, float dx, float dy) {
    RCI_TexteditContext *c = rci_textedit_context;
    (void)dx;
    for (int i = 0; i < c->areaCount; ++i) {
        if (c->areas[i].id != id)
            continue;
        if (c->wheelId == id) {
            c->wheelDy += dy;
        } else {
            c->wheelId = id;
            c->wheelDy = dy;
        }
        return true;
    }
    return false;
}

bool rci_textedit_area_pan(uint32_t id, double dy, double *at) {
    RCI_TexteditContext *c = rci_textedit_context;
    RCI_TexteditArea    *a = rci_textedit_area(id, false);
    if (!a || rci_widgets_modal_declared_inert(a->scope))
        return false;
    const bool  focused = rci_focus_field() && rci_focus_id() == id;
    float      *y       = focused ? &c->scrollY : &a->scrollY;
    const float hi      = a->maxY > *y ? a->maxY : *y;
    if (!(hi > 0.0f))
        return false;
    float to = *y - (float)dy;
    if (to > hi)
        to = hi;
    if (!(to > 0.0f))
        to = 0.0f;
    if (to != *y) {
        *y = to;
        if (focused)
            c->viewFree = c->edit.cursor + 1;
    }
    if (at)
        *at = (double)*y;
    return true;
}

void rci_textedit_textinput_shutdown(void) {
    rci_focus_shutdown();
    rci_textedit_context_release(rci_textedit_context);
    rci_textedit_wipe(rci_textedit_context, sizeof(*rci_textedit_context));
}

static void rci_textedit_ime_report(RCI_TexteditContext *c) {
    if (c->imeClaimed)
        c->imeField = 0u;
    else if (c->imeNoted)
        rci_api_ime_rect(c->imeCaret, c->imeScroll != 0u && !c->imeYield);
    c->imeNoted   = false;
    c->imeClaimed = false;
}

void rci_textedit_ime_claim(void) {
    rci_textedit_context->imeClaimed = true;
}

bool rci_textedit_ime_scroller(CLAY_BoundingBox *caret, uint32_t *scroller) {
    const RCI_TexteditContext *c = rci_textedit_context;
    CLAY_ElementData           f;

    if (!c->imeScroll || !rci_focus_field() || rci_focus_id() != c->imeField)
        return false;
    f = clayGetElementData((CLAY_ElementId){ .id = c->imeField });
    *caret    = (CLAY_BoundingBox){ f.boundingBox.x + c->imeDx, f.boundingBox.y + c->imeDy,
                                    c->imeCaret.width, c->imeCaret.height };
    *scroller = c->imeScroll;
    return f.found;
}

bool rci_textedit_ime_caret(CLAY_BoundingBox *caret) {
    const RCI_TexteditContext *c = rci_textedit_context;
    CLAY_ElementData           f;

    if (!c->imeField || rci_focus_id() != c->imeField)
        return false;
    f = clayGetElementData((CLAY_ElementId){ .id = c->imeField });
    *caret = (CLAY_BoundingBox){ f.boundingBox.x + c->imeDx, f.boundingBox.y + c->imeDy,
                                 c->imeCaret.width, c->imeCaret.height };
    return f.found;
}

void rci_textedit_ime_yield(bool yield) {
    RCI_TexteditContext *c    = rci_textedit_context;
    const bool           flip = c->imeYield != yield;

    c->imeYield = yield;
    if (flip && c->imeField)
        rci_api_ime_rect(c->imeCaret, c->imeScroll != 0u && !yield);
}

void rci_textedit_textinput_walk_end(void) {
    for (int i = 0; i < rci_textedit_context->inputCount; ++i)
        rci_textedit_context->inputs[i].drawn = true;
}

void rci_textedit_draw_text_inputs(void) {
    RCI_TexteditContext *c = rci_textedit_context;

    if (rci_textedit_draw_fallback_hook)
        rci_textedit_draw_fallback_hook();
#if RCI_WINDOW_HAS_TEXT_INTERACTION
    rci_textedit_publish(c);
#endif
    rci_textedit_registry_clear(c);
    rci_textedit_ime_report(c);
}

