static inline unsigned rci_linebreak_run_find(const uint32_t *runs, uint32_t n, uint32_t cp) {
    uint32_t lo = 0, hi = n;

    while (hi - lo > 1) {
        const uint32_t mid = lo + (hi - lo) / 2;

        if ((runs[mid] >> 8) <= cp)
            lo = mid;
        else
            hi = mid;
    }
    return (unsigned)(runs[lo] & 0xFFu);
}

static inline unsigned rci_linebreak_prop(uint32_t cp) {
    unsigned p;

    if (cp < 0x80u)
        return rci_linebreak_ascii[cp];
    p = rci_linebreak_run_find(rci_linebreak_runs,
                               (uint32_t)(sizeof rci_linebreak_runs / sizeof rci_linebreak_runs[0]), cp);
    if (cp >= 0xAC00u && cp <= 0xD7A3u)
        p = (p & ~RCI_LINEBREAK_CLASS_MASK)
            | ((cp - 0xAC00u) % 28u == 0u ? RCI_LINEBREAK_CLASS_H2 : RCI_LINEBREAK_CLASS_H3);
    return p;
}

static inline unsigned rci_linebreak_guard_kind(uint32_t cp) {
    return rci_linebreak_run_find(rci_linebreak_guard,
                                  (uint32_t)(sizeof rci_linebreak_guard / sizeof rci_linebreak_guard[0]),
                                  cp);
}

