static enum LineBreakClass rci_linebreak_word_break_class(enum LineBreakClass lbc)
{
    if (rci_linebreak_mode == CLAY_TEXT_WRAP_WORDS_KEEP_ALL) {
        switch (lbc) {
        case LBP_ID: case LBP_H2: case LBP_H3: case LBP_JL: case LBP_JV: case LBP_JT:
            return LBP_AL;
        default:
            return lbc;
        }
    }
    if (rci_linebreak_mode == CLAY_TEXT_WRAP_WORDS_BREAK_ALL) {
        switch (lbc) {
        case LBP_AL: case LBP_HL: case LBP_NU:
            return LBP_ID;
        default:
            return lbc;
        }
    }
    return lbc;
}

