{
    return set_linebreaks(s, len, lang, LBOT_PER_CODE_POINT, brks,
                          (get_next_char_t)ub_get_next_char_utf16);
}

void set_linebreaks_utf32(
        const utf32_t *s,
        size_t len,
        const char *lang,
        char *brks)
{
    set_linebreaks(s, len, lang, LBOT_PER_CODE_UNIT, brks,
                   (get_next_char_t)ub_get_next_char_utf32);
}

int is_line_breakable(
        utf32_t char1,
        utf32_t char2,
        const char *lang)
{
    utf32_t s[2];
    char brks[2];
    s[0] = char1;
    s[1] = char2;
    set_linebreaks_utf32(s, 2, lang, brks);
    return brks[0];
}

enum {
    RCI_LB_MUST   = LINEBREAK_MUSTBREAK,
    RCI_LB_ALLOW  = LINEBREAK_ALLOWBREAK,
    RCI_LB_INSIDE = LINEBREAK_INSIDEACHAR,
};
enum {
    RCI_LBC_CM = LBP_CM, RCI_LBC_ZWJ = LBP_ZWJ, RCI_LBC_SP = LBP_SP, RCI_LBC_QU = LBP_QU,
    RCI_LBC_HY = LBP_HY, RCI_LBC_HH = LBP_HH, RCI_LBC_SY = LBP_SY, RCI_LBC_IS = LBP_IS,
    RCI_LBC_CL = LBP_CL, RCI_LBC_CP = LBP_CP, RCI_LBC_RI = LBP_RI, RCI_LBC_VI = LBP_VI,
    RCI_LBC_VF = LBP_VF, RCI_LBC_JL = LBP_JL, RCI_LBC_JV = LBP_JV, RCI_LBC_H2 = LBP_H2,
};

static unsigned rci_linebreak_engine_class(uint32_t cp)
{
    return (unsigned)resolve_lb_class(get_char_lb_class_default(cp), false, true, cp);
}

static utf32_t rci_linebreak_engine_char(const void *s, size_t len, size_t *ip)
{
    unsigned cp;
    const char *b = (const char *)s;

    if (*ip >= len)
        return EOS;
    *ip += (size_t)rci_font_utf8_decode_one(b + *ip, b + len, &cp);
    return cp;
}

static void rci_linebreak_engine_run(const char *s, size_t len, unsigned char *brk)
{
    set_linebreaks(s, len, "-strict", LBOT_PER_CODE_UNIT, (char *)brk,
                   rci_linebreak_engine_char);
}

