void rci_widgets_shutdown(void) {
    rci_widgets_context->touchTargetCount = 0;
    rci_widgets_context->activeId         = 0;
    rci_widgets_context->release_id        = 0;
    rci_widgets_context->modal_depth       = 0;
    rci_core_in_exit                       = false;
    rci_widgets_context->modalRanFrame   = false;
    rci_widgets_context->modalScopeLatch = false;
    rci_widgets_context->modalLatchHash  = 0;
    rci_widgets_context->popupRanFrame   = 0;
    rci_widgets_context->popupScopeLatch = 0;

    rci_widgets_context->scope_rolled_by_overlay = false;
    rci_widgets_context->modalTopHash    = 0;
    rci_widgets_context->modalDismissed  = 0;
    rci_widgets_context->open_combo_id     = 0;
    rci_widgets_context->openMenuId      = 0;

    rci_widgets_context->splitDepth       = 0;
    rci_widgets_context->tableDepth       = 0;
    for (int i = 0; i < RCI_TABLE_MAX; i++) rci_widgets_context->tableStack[i].rowOpen = false;

    for (int i = 0; i < RCI_CAPTION_OCCLUDERS; i++) rci_widgets_context->captionOccluder[i] = 0;
    rci_widgets_context->captionOccluderNext = 0;
    rci_widgets_context->menuAnchorId    = NULL;
    rci_widgets_context->menuPopupId[0]  = '\0';

    memset(rci_widgets_context->menuIconMenus, 0, sizeof rci_widgets_context->menuIconMenus);
    rci_widgets_context->menuItemIndex   = 0;
    rci_widgets_context->menuInScope     = false;
    rci_widgets_context->menuCtxX        = 0.0f;
    rci_widgets_context->menuCtxY        = 0.0f;
    rci_widgets_context->scrollDragGrab  = 0.0f;
    rci_widgets_context->dragFrom         = 0.0f;
    rci_widgets_context->dragGrab         = 0.0f;
#if !defined(__EMSCRIPTEN__) && !RCI_PLATFORM_MOBILE
    rci_widgets_chip_anims_reset();
#endif
    rci_widgets_frame_registries_reset();
}

void rci_widgets_draw_overlays(void) {

    int ntip   = rci_widgets_context->tooltipCount;
    rci_widgets_context->tooltipCount   = 0;

    rci_textedit_draw_text_inputs();

    rci_widgets_draw_tooltips(ntip);

    rci_widgets_context->frame_modal_open   = false;

    rci_widgets_context->modalScopeLatch  = rci_widgets_context->modalRanFrame;
    rci_widgets_context->modalRanFrame    = false;
    rci_widgets_context->modalLatchHash   = rci_widgets_context->modalTopHash;
    rci_widgets_context->popupScopeLatch  = rci_widgets_context->popupRanFrame;
    rci_widgets_context->popupRanFrame    = 0;
    rci_widgets_context->scope_rolled_by_overlay = true;
}

static const char *rci_widgets_tip_line(uint16_t font, float size, const char *p,
                                        const char *end, float maxW,
                                        const char **next) {
    const char *q = p;
    float       lw = 0.0f;
    while (q < end && *q != '\n') {
        const char *e = q + 1;
        while (e < end && *e != ' ' && *e != '\n') e++;
        if (q == p) {

            while (q < e) {
                unsigned int cp;
#if RC_COLOR_EMOJI
                float        gw;
                int          n  = rci_emoji_step(font, size, q, e, &cp, &gw);
#else
                int          n  = rci_font_utf8_decode_one(q, e, &cp);
                float        gw = rci_font_measure(font, size, q, q + n);
#endif
                if (q > p && lw + gw > maxW) {
                    *next = q;
                    return q;
                }
                lw += gw;
                q  += n;
            }
            continue;
        }
        float sw = rci_font_measure(font, size, q, e);
        if (lw + sw > maxW) {
            *next = (*q == ' ') ? q + 1 : q;
            return q;
        }
        lw += sw;
        q   = e;
    }
    *next = (q < end) ? q + 1 : q;
    return q;
}

static void rci_widgets_draw_tooltips(int count) {
    const uint16_t font = RCI_TOOLTIP_FONT;

    const float    size = (float)rci_font_size(font);
    const float    padX = 8.0f, padY = 5.0f, gap = 6.0f;

    const float    line = rci_text_line_normal(font, size);
    const float    lead = rci_text_half_leading(font, size, line);

    float vpW = rci_api_viewport_w(), vpH = rci_api_viewport_h();
    if (vpW <= 0.0f || vpH <= 0.0f) {
        CLAY_Dimensions ld = clayGetLayoutDimensions();
        vpW = ld.width;
        vpH = ld.height;
    }

    const CLAY_BoundingBox safe = rci_widgets_safe_rect((CLAY_Dimensions){ vpW, vpH });

    for (int i = 0; i < count; ++i) {
        RCI_WidgetsTooltipReg t   = rci_widgets_context->tooltips[i];
        CLAY_ElementId        eid = { .id = t.id };
        if (!rci_interact_intent_hover_reveal_eid(eid, RCI_TOOLTIP_DELAY)) continue;

        CLAY_ElementData ed = clayGetElementData(eid);
        if (!ed.found) continue;

        if (rci_widgets_modal_overlay_inert(rci_internal_clay_box(ed.boundingBox))) continue;

        CLAY_BoundingBox b = rci_internal_pan_box(ed.boundingBox);

        RCI_WidgetsTipInk ink;
        memcpy(&ink, rci_widgets_context->tipText + t.off, sizeof ink);
        const char *text = rci_widgets_context->tipText + t.off + sizeof ink;
        const char *end  = text + strlen(text);
        const float maxW = safe.width - 2.0f * padX;
        float tw = 0.0f;
        int   lines = 0;
        for (const char *p = text, *next; p < end; p = next, lines++) {
            const char *le = rci_widgets_tip_line(font, size, p, end, maxW, &next);
            float       lw = rci_font_measure(font, size, p, le);
            if (lw > tw) tw = lw;
        }
        float bw = tw + 2.0f * padX;
        float bh = (float)lines * line + 2.0f * padY;

        float bx = b.x;
        float by = b.y + b.height + gap;
        if (by + bh > safe.y + safe.height) by = b.y - gap - bh;
        if (bx + bw > safe.x + safe.width)  bx = safe.x + safe.width - bw;
        if (bx < safe.x) bx = safe.x;
        if (by < safe.y) by = safe.y;

        const RCI_Corners tipC = { ink.radius, ink.radius, ink.radius, ink.radius };

        const CLAY_BoundingBox panel = rci_gfx_snap_box((CLAY_BoundingBox){ bx, by, bw, bh });
        rci_gfx_rect(panel.x, panel.y, panel.width, panel.height, ink.surface, tipC);
        float ly = by + padY + lead;
        for (const char *p = text, *next; p < end; p = next, ly += line) {
            const char *le = rci_widgets_tip_line(font, size, p, end, maxW, &next);
            if (le > p)
                rci_gfx_text(font, size, 0.0f, bx + padX, ly, ink.text,
                             p, (int)(le - p));
        }

        float el = 1.0f, er = 1.0f, et = 1.0f, eb = 1.0f;
        rci_gfx_snap_border(&el, &er, &et, &eb);
        rci_gfx_border(panel.x, panel.y, panel.width, panel.height, ink.border, tipC,
                       el, er, et, eb);
    }
}

