typedef struct RCI_ChartBlocks {
    void         **heap;
    unsigned int   count;
    unsigned int   cap;
    unsigned int   cursor;
} RCI_ChartBlocks;

static RCI_ChartPayload rci_chart_pool[RCI_CHART_POOL];
static RCI_ChartText    rci_chart_text[RCI_CHART_POOL];
static RCI_ChartBlocks  rci_chart_payloads, rci_chart_texts;
static unsigned int     rci_chart_epoch = 0;

static void rci_chart_teardown(void) {
    for (unsigned int k = 0; k < rci_chart_payloads.count; k++) {
        RCI_ChartPayload *b = (RCI_ChartPayload *)rci_chart_payloads.heap[k];
        for (int j = 0; j < RCI_CHART_POOL; j++)
            b[j].dd.magic = 0u;
        free(b);
    }
    for (unsigned int k = 0; k < rci_chart_texts.count; k++)
        free(rci_chart_texts.heap[k]);
    free(rci_chart_payloads.heap);
    free(rci_chart_texts.heap);
    rci_chart_payloads = (RCI_ChartBlocks){0};
    rci_chart_texts    = (RCI_ChartBlocks){0};
}

static void *rci_chart_take(RCI_ChartBlocks *b, void *block0, size_t size) {
    unsigned int i   = b->cursor;
    char        *blk = (char *)block0;

    if (i >= RCI_CHART_POOL) {
        unsigned int k = i / RCI_CHART_POOL - 1;
        if (k == b->count) {
            if (b->count == b->cap) {
                unsigned int cap  = b->cap ? 2 * b->cap : 4;
                void       **heap = (void **)realloc(b->heap, cap * sizeof *heap);
                if (!heap)
                    return NULL;
                b->heap = heap;
                b->cap  = cap;
            }
            void *fresh = calloc(RCI_CHART_POOL, size);
            if (!fresh)
                return NULL;
            b->heap[b->count++] = fresh;
            rci_api_register_teardown(rci_chart_teardown);
        }
        blk = (char *)b->heap[k];
    }
    b->cursor++;
    return blk + (size_t)(i % RCI_CHART_POOL) * size;
}

static RCI_ChartPayload *rci_chart_slot(RCI_ChartText **text) {
    unsigned int now = rci_render_epoch();
    if (now != rci_chart_epoch) {
        rci_chart_epoch           = now;
        rci_chart_payloads.cursor = 0;
        rci_chart_texts.cursor    = 0;
    }

    rci_core_chart_discard_hook = rci_chart_discard_frame;

    RCI_ChartPayload *p = (RCI_ChartPayload *)
            rci_chart_take(&rci_chart_payloads, rci_chart_pool, sizeof *p);
    if (p && text) {
        *text = (RCI_ChartText *)
                rci_chart_take(&rci_chart_texts, rci_chart_text, sizeof **text);
        if (!*text)
            p = NULL;
    }

    if (!p) {

        RCI_LOG_WARN_ONCE("rcChart/rcSparkline: out of memory for another block of %d "
                          "charts in one frame - a chart that cannot be stored draws an "
                          "\"out of memory\" placeholder (rcChart) or an empty box "
                          "(rcSparkline), never another chart's data. Charts per frame "
                          "have no limit of their own; the allocator refused",
                          RCI_CHART_POOL);
        return NULL;
    }
    *p = (RCI_ChartPayload){0};
    p->uzk = rcUnzoomedScale();
    return p;
}

void rci_chart_discard_frame(void) {
    rci_chart_payloads.cursor = 0;
    rci_chart_texts.cursor    = 0;
}

