void rcSetImeCaretRect(float x, float y, float width, float height) {

    float *f[4] = { &x, &y, &width, &height };

    for (int i = 0; i < 4; i++) {
        if (*f[i] > 1e6f && *f[i] <= FLT_MAX)
            *f[i] = 1e6f;
        else if (*f[i] < -1e6f && *f[i] >= -FLT_MAX)
            *f[i] = -1e6f;
    }

    rci_textedit_ime_claim();
    rci_api_ime_rect((CLAY_BoundingBox){ x, y, width, height }, false);
}

