enum { RCI_API_TEARDOWN_MAX = 8 };

static void (*rci_api_teardownHooks[RCI_API_TEARDOWN_MAX])(void);
static int    rci_api_teardownCount;

void rci_api_register_teardown(void (*hook)(void)) {
    if (!hook)
        return;
    for (int i = 0; i < rci_api_teardownCount; i++) {
        if (rci_api_teardownHooks[i] == hook)
            return;
    }
    if (rci_api_teardownCount < RCI_API_TEARDOWN_MAX)
        rci_api_teardownHooks[rci_api_teardownCount++] = hook;
    else
        RCI_LOG_WARN_ONCE("internal: more than %d teardown hooks - raise RCI_API_TEARDOWN_MAX; "
                          "this subsystem is not freed at shutdown", RCI_API_TEARDOWN_MAX);
}

void rci_api_run_teardowns(void) {

    int n = rci_api_teardownCount;
    rci_api_teardownCount = 0;
    for (int i = 0; i < n; i++) {
        void (*hook)(void) = rci_api_teardownHooks[i];
        rci_api_teardownHooks[i] = NULL;
        hook();
    }
}

enum { RCI_API_ICON_BLOCKS_MAX = 64 };

static RC_CustomDrawData *rci_api_iconBlocks[RCI_API_ICON_BLOCKS_MAX];
static unsigned int       rci_api_iconBlockCount;
static unsigned int       rci_api_iconCursor;
static unsigned int       rci_api_iconSeenStamp;

static void rci_api_icon_pool_ceiling_warn(unsigned int ceiling) {
    RCI_LOG_WARN_ONCE("rc_icons: more than %u icons in ONE frame - the pool is at its ceiling and "
                      "cannot grow, so icons past it will keep NOT DRAWING. The ceiling is %d "
                      "blocks of RC_ICON_POOL_CAPACITY; raising that knob moves it, but a frame "
                      "emitting this many is a runaway layout, not a sizing problem.",
                      ceiling, (int)RCI_API_ICON_BLOCKS_MAX);
}

static void rci_api_icon_pool_oom_warn(unsigned int blocks) {
    if (blocks == 0) {
        RCI_LOG_WARN_ONCE("rc_icons: could not allocate the first icon block (%d entries); icons "
                          "will not draw. This is an allocation failure, not a capacity one - "
                          "RC_ICON_POOL_CAPACITY is not the knob for it.",
                          (int)RC_ICON_POOL_CAPACITY);
    } else {
        RCI_LOG_WARN_ONCE("rc_icons: could not allocate icon block %u (%d entries); the icons past "
                          "the first %u in a frame will not draw while the allocator refuses. "
                          "This is an allocation failure, not a capacity one - "
                          "RC_ICON_POOL_CAPACITY is not the knob for it.",
                          blocks + 1u, (int)RC_ICON_POOL_CAPACITY,
                          blocks * (unsigned int)RC_ICON_POOL_CAPACITY);
    }
}

static bool rci_api_icon_pool_add_block(void) {
    RC_CustomDrawData *block = (RC_CustomDrawData *)
            calloc(RC_ICON_POOL_CAPACITY, sizeof *block);
    if (!block) {
        return false;
    }
    rci_api_iconBlocks[rci_api_iconBlockCount++] = block;
    return true;
}

RC_CustomDrawData *rci_api_icon_next_draw_data(RC_CustomDrawCallback draw,
                                               RC_Color color,
                                               const void *userData) {

    unsigned int now = rci_render_epoch();
    if (now != rci_api_iconSeenStamp) {
        rci_api_iconSeenStamp = now;
        rci_api_iconCursor = 0;
    }

    unsigned int idx = rci_api_iconCursor;
    if (idx >= rci_api_iconBlockCount * (unsigned int)RC_ICON_POOL_CAPACITY) {

        if (rci_api_iconBlockCount >= RCI_API_ICON_BLOCKS_MAX) {
            rci_api_icon_pool_ceiling_warn(idx);
            return NULL;
        }

        if (!rci_api_icon_pool_add_block()) {
            rci_api_icon_pool_oom_warn(rci_api_iconBlockCount);
            return NULL;
        }
    }
    rci_api_iconCursor = idx + 1u;
    RC_CustomDrawData *slot =
            &rci_api_iconBlocks[idx / RC_ICON_POOL_CAPACITY][idx % RC_ICON_POOL_CAPACITY];

    if (!rci_internal_color_set(color)) {
        color = rcGetStylePtr()->text;
    }
    if (rci_core_anim_scope_n)
        color = rci_core_anim_run_color(color, 0u);
    slot->magic    = RCI_CUSTOM_DRAW_MAGIC;
    slot->draw     = draw;
    slot->userData = userData;
    slot->color    = color;
    return slot;
}

void rci_api_icon_pool_shutdown(void) {
    for (unsigned int i = 0; i < rci_api_iconBlockCount; i++) {

        for (int j = 0; j < RC_ICON_POOL_CAPACITY; j++) {
            rci_api_iconBlocks[i][j].magic = 0u;
        }
        free(rci_api_iconBlocks[i]);
        rci_api_iconBlocks[i] = NULL;
    }
    rci_api_iconBlockCount = 0;
    rci_api_iconCursor     = 0;
    rci_api_iconSeenStamp  = 0;
}

