#if RCI_WINDOW_HAS_IME_SHIFT
void rci_window_ime_clear(void);
#endif
void rci_api_ime_rect(CLAY_BoundingBox r, bool lifted) {
    const float z = rci_api_zoom_val > 0.0f ? rci_api_zoom_val : 1.0f;

#if RCI_WINDOW_HAS_IME_SHIFT
    if (lifted && !rci_api_mirror_v) {
        rci_window_ime_clear();
        return;
    }
#else
    (void)lifted;
#endif
    r.x       = (r.x - rci_api_pan_x_val) * z;
    r.y       = (r.y - rci_api_pan_y_val) * z;
    r.width  *= z;
    r.height *= z;
    if (rci_api_mirror_h) r.x = rci_api_mirror_w - r.x - r.width;
    if (rci_api_mirror_v) r.y = rci_api_mirror_ht - r.y - r.height;
#ifdef __EMSCRIPTEN__

    if (rci_textedit_web_ime_hook)
        rci_textedit_web_ime_hook(r.x, r.y, r.width, r.height);
#else
    rci_window_ime_rect(r.x, r.y, r.width, r.height);
#endif
}

#if RCI_WINDOW_HAS_TEXT_INTERACTION

CLAY_BoundingBox rci_api_window_box(CLAY_BoundingBox r);
CLAY_BoundingBox rci_api_window_box(CLAY_BoundingBox r) {
    const float z = rci_api_zoom_val > 0.0f ? rci_api_zoom_val : 1.0f;

    r.x       = (r.x - rci_api_pan_x_val) * z;
    r.y       = (r.y - rci_api_pan_y_val) * z;
    r.width  *= z;
    r.height *= z;
    if (rci_api_mirror_h) r.x = rci_api_mirror_w - r.x - r.width;
    if (rci_api_mirror_v) r.y = rci_api_mirror_ht - r.y - r.height;
    return r;
}
#endif

