#ifndef RC_ATOMIC_H
#define RC_ATOMIC_H

#include <stdbool.h>
#include <stddef.h>

#if defined(__GNUC__) || defined(__clang__)

static inline long rci_atomic_load(long *p) {
    return __atomic_load_n(p, __ATOMIC_SEQ_CST);
}
static inline void rci_atomic_store(long *p, long v) {
    __atomic_store_n(p, v, __ATOMIC_SEQ_CST);
}

static inline long rci_atomic_add(long *p, long v) {
    return __atomic_add_fetch(p, v, __ATOMIC_SEQ_CST);
}
static inline long rci_atomic_swap(long *p, long v) {
    return __atomic_exchange_n(p, v, __ATOMIC_SEQ_CST);
}

static inline bool rci_atomic_cas(long *p, long *expected, long desired) {
    return __atomic_compare_exchange_n(p, expected, desired, false,
                                       __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST);
}
static inline void *rci_atomic_ptr_load(void **p) {
    return __atomic_load_n(p, __ATOMIC_SEQ_CST);
}
static inline void *rci_atomic_ptr_swap(void **p, void *v) {
    return __atomic_exchange_n(p, v, __ATOMIC_SEQ_CST);
}
static inline bool rci_atomic_ptr_cas(void **p, void **expected, void *desired) {
    return __atomic_compare_exchange_n(p, expected, desired, false,
                                       __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST);
}

#elif defined(_MSC_VER)

#include <intrin.h>

static inline long rci_atomic_load(long *p) {
    return _InterlockedOr((long volatile *)p, 0);
}
static inline void rci_atomic_store(long *p, long v) {
    (void)_InterlockedExchange((long volatile *)p, v);
}
static inline long rci_atomic_add(long *p, long v) {
    return _InterlockedExchangeAdd((long volatile *)p, v) + v;
}
static inline long rci_atomic_swap(long *p, long v) {
    return _InterlockedExchange((long volatile *)p, v);
}
static inline bool rci_atomic_cas(long *p, long *expected, long desired) {
    long seen = _InterlockedCompareExchange((long volatile *)p, desired, *expected);

    if (seen == *expected)
        return true;
    *expected = seen;
    return false;
}
static inline void *rci_atomic_ptr_load(void **p) {
    return _InterlockedCompareExchangePointer((void *volatile *)p, NULL, NULL);
}
static inline void *rci_atomic_ptr_swap(void **p, void *v) {
    return _InterlockedExchangePointer((void *volatile *)p, v);
}
static inline bool rci_atomic_ptr_cas(void **p, void **expected, void *desired) {
    void *seen = _InterlockedCompareExchangePointer((void *volatile *)p, desired, *expected);

    if (seen == *expected)
        return true;
    *expected = seen;
    return false;
}

#else
#error "RayClay: no atomic builtins for this compiler (need gcc/clang __atomic or MSVC)"
#endif

static inline void rci_atomic_push(void **head, void *node, void **link) {
    void *top = rci_atomic_ptr_load(head);

    do {
        *link = top;
    } while (!rci_atomic_ptr_cas(head, &top, node));
}

static inline void *rci_atomic_take(void **head) {
    return rci_atomic_ptr_swap(head, NULL);
}

#endif

#include <stdlib.h>
#include <string.h>

static void *rci_opened_head;
static long  rci_opened_waiting;
static long  rci_opened_new;

static int rci_opened_reserve(int want) {
    long have = rci_atomic_load(&rci_opened_waiting);
    long take;

    do {
        take = RCI_OPENED_MAX - have;
        if (take <= 0)
            return 0;
        if (take > want)
            take = want;
    } while (!rci_atomic_cas(&rci_opened_waiting, &have, have + take));
    return (int)take;
}

int rci_opened_post(int count, const char *const *paths) {
    RCI_OpenedBatch *batch;
    size_t text = 0;
    char *at;
    int take;

    if (count <= 0 || !paths)
        return 0;
    for (int i = 0; i < count && i < RCI_OPENED_MAX; i++)
        if (!paths[i])
            return 0;
    take = rci_opened_reserve(count);
    if (!take)
        return 0;
    for (int i = 0; i < take; i++)
        text += strlen(paths[i]) + 1;

    batch = malloc(sizeof *batch + (size_t)take * sizeof(char *) + text);
    if (!batch) {
        rci_atomic_add(&rci_opened_waiting, -(long)take);
        return 0;
    }
    batch->count = take;
    batch->paths = (const char **)(batch + 1);
    at = (char *)(batch->paths + take);
    for (int i = 0; i < take; i++) {
        size_t n = strlen(paths[i]) + 1;

        memcpy(at, paths[i], n);
        batch->paths[i] = at;
        at += n;
    }
    rci_atomic_push(&rci_opened_head, batch, &batch->next);
    rci_atomic_store(&rci_opened_new, 1);
    rci_window_post_empty_event();
    return take;
}

RCI_OpenedBatch *rci_opened_take(void) {
    void *list = rci_atomic_take(&rci_opened_head);
    RCI_OpenedBatch *oldest = NULL;
    long taken = 0;

    while (list) {
        RCI_OpenedBatch *batch = list;

        list = batch->next;
        batch->next = oldest;
        oldest = batch;
        taken += batch->count;
    }
    if (taken)
        rci_atomic_add(&rci_opened_waiting, -taken);
    return oldest;
}

void rci_opened_free(RCI_OpenedBatch *list) {
    while (list) {
        RCI_OpenedBatch *next = list->next;

        free(list);
        list = next;
    }
}

bool rci_opened_fresh(void) {
    return rci_atomic_swap(&rci_opened_new, 0) != 0;
}

