#include <stdlib.h>
#include <string.h>

#if defined(__ANDROID__)
#include <jni.h>
#include <stdio.h>
#include <GLES3/gl3.h>
#ifndef GL_TEXTURE_EXTERNAL_OES
#define GL_TEXTURE_EXTERNAL_OES 0x8D65
#endif
#endif

RCI_STATIC_ASSERT(RCI_LOOP_PIXELS_RGBA8 == RC_PIXEL_RGBA8 && RCI_LOOP_PIXELS_BGRA8 == RC_PIXEL_BGRA8 &&
                  RCI_LOOP_PIXELS_RGBX8 == RC_PIXEL_RGBX8 && RCI_LOOP_PIXELS_BGRX8 == RC_PIXEL_BGRX8,
                  "media's frame layouts are RC_PixelFormat's");
RCI_STATIC_ASSERT(RCI_LOOP_YUV_BT601 == RCI_GFX_YUV_BT601 && RCI_LOOP_YUV_BT709 == RCI_GFX_YUV_BT709 &&
                  RCI_LOOP_YUV_BT2020 == RCI_GFX_YUV_BT2020, "media's matrices are the renderer's");

#define RCI_IMAGE_MEDIA_OWED_S 1.0

#if defined(__ANDROID__)

typedef struct RCI_ImageMediaOes {
    jobject  surface;
    GLuint   oes;
    GLuint   page;
    void    *image;
    int      w, h;
    int      refusedW, refusedH;
    uint32_t epoch;
    unsigned latched;
} RCI_ImageMediaOes;
#endif

typedef struct RCI_ImageMedia {
    RCI_ImageRef           ref;
    RC_Image               image;
#if defined(__EMSCRIPTEN__)
    RCI_GfxElementPage    *page;
    int                    element;
#else
    RC_Image               pixels;
    RCI_GfxYuvPage        *yuv;
    int                    yuvW, yuvH;
#endif
    RC_Media               media;
    uint32_t               rev;
    double                 owedSince;
    bool                   dead;
#if defined(__ANDROID__)
    RCI_ImageMediaOes      oes;
#endif
    struct RCI_ImageMedia *next;
} RCI_ImageMedia;

static RCI_ImageMedia *rci_image_media_list;

#if defined(__ANDROID__)

static struct {
    uint32_t    epoch;
    GLuint      program, fbo;
    GLint       matrix;
    bool        broken;
    int         resolved;
    jclass      cls;
    jmethodID   init, update, transform, release;
    jfloatArray m;
} rci_image_media_oes;

static const char rci_image_media_vs[] =
    "attribute vec2 a;\n"
    "uniform mat4 m;\n"
    "varying highp vec2 v;\n"
    "void main() {\n"
    "    v = (m * vec4(0.5 + 0.5 * a.x, 0.5 - 0.5 * a.y, 0.0, 1.0)).xy;\n"
    "    gl_Position = vec4(a, 0.0, 1.0);\n"
    "}\n";

static const char rci_image_media_fs[] =
    "#extension GL_OES_EGL_image_external : require\n"
    "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
    "precision highp float;\n"
    "#else\n"
    "precision mediump float;\n"
    "#endif\n"
    "varying vec2 v;\n"
    "uniform samplerExternalOES s;\n"
    "void main() {\n"
    "    gl_FragColor = texture2D(s, v);\n"
    "}\n";
static const GLfloat rci_image_media_quad[8] = { -1.0f, -1.0f, 1.0f, -1.0f, -1.0f, 1.0f, 1.0f, 1.0f };

static GLuint rci_image_media_shader(GLenum kind, const char *text) {
    GLuint shader = glCreateShader(kind);
    GLint  ok = GL_FALSE;

    if (!shader)
        return 0;
    glShaderSource(shader, 1, &text, NULL);
    glCompileShader(shader);
    glGetShaderiv(shader, GL_COMPILE_STATUS, &ok);
    if (ok)
        return shader;
    glDeleteShader(shader);
    return 0;
}

static bool rci_image_media_program(uint32_t epoch) {
    GLuint vs, fs, program;
    GLint  ok = GL_FALSE;

    if (rci_image_media_oes.epoch == epoch)
        return rci_image_media_oes.program != 0;

    rci_image_media_oes.epoch   = epoch;
    rci_image_media_oes.program = 0;
    rci_image_media_oes.fbo     = 0;
    vs = rci_image_media_shader(GL_VERTEX_SHADER, rci_image_media_vs);
    fs = vs ? rci_image_media_shader(GL_FRAGMENT_SHADER, rci_image_media_fs) : 0;
    program = fs ? glCreateProgram() : 0;
    if (program) {
        glAttachShader(program, vs);
        glAttachShader(program, fs);
        glBindAttribLocation(program, 0, "a");
        glLinkProgram(program);
        glGetProgramiv(program, GL_LINK_STATUS, &ok);
    }
    if (vs)
        glDeleteShader(vs);
    if (fs)
        glDeleteShader(fs);
    if (!ok) {
        if (program)
            glDeleteProgram(program);
        if (!rci_image_media_oes.broken) {
            rci_image_media_oes.broken = true;
            rci_base_log(RC_LOG_WARNING, "rcMediaImage: this device's GL would not build the "
                         "video blit (samplerExternalOES); videos draw nothing");
        }
        return false;
    }
    rci_image_media_oes.program = program;
    rci_image_media_oes.matrix  = glGetUniformLocation(program, "m");
    glGenFramebuffers(1, &rci_image_media_oes.fbo);
    return rci_image_media_oes.fbo != 0;
}

static bool rci_image_media_jni(JNIEnv *env) {
    jclass      cls;
    jfloatArray m;

    if (rci_image_media_oes.resolved)
        return rci_image_media_oes.resolved > 0;
    rci_image_media_oes.resolved = -1;
    cls = (*env)->FindClass(env, "android/graphics/SurfaceTexture");
    if (!cls || (*env)->ExceptionCheck(env)) {
        (*env)->ExceptionClear(env);
        return false;
    }
    rci_image_media_oes.init      = (*env)->GetMethodID(env, cls, "<init>", "(I)V");
    rci_image_media_oes.update    = (*env)->GetMethodID(env, cls, "updateTexImage", "()V");
    rci_image_media_oes.transform = (*env)->GetMethodID(env, cls, "getTransformMatrix", "([F)V");
    rci_image_media_oes.release   = (*env)->GetMethodID(env, cls, "release", "()V");
    m = (*env)->NewFloatArray(env, 16);
    if (!(*env)->ExceptionCheck(env) && rci_image_media_oes.init && rci_image_media_oes.update &&
        rci_image_media_oes.transform && rci_image_media_oes.release && m) {
        rci_image_media_oes.cls = (jclass)(*env)->NewGlobalRef(env, cls);
        rci_image_media_oes.m   = (jfloatArray)(*env)->NewGlobalRef(env, m);
    }
    (*env)->ExceptionClear(env);
    (*env)->DeleteLocalRef(env, cls);
    if (m)
        (*env)->DeleteLocalRef(env, m);
    if (!rci_image_media_oes.cls || !rci_image_media_oes.m)
        return false;
    rci_image_media_oes.resolved = 1;
    return true;
}

static void rci_image_media_page_free(void *image, GLuint page, uint32_t epoch) {
    rci_gfx_image_destroy(image);
    if (page && epoch == rci_gfx_epoch())
        glDeleteTextures(1, &page);
}

typedef struct {
    void    *image;
    GLuint   page;
    uint32_t epoch;
} RCI_ImageMediaRetired;

static void rci_image_media_retired_free(void *p) {
    RCI_ImageMediaRetired *r = p;

    rci_image_media_page_free(r->image, r->page, r->epoch);
    free(r);
}

static void rci_image_media_oes_drop(RCI_ImageMediaOes *o) {
    JNIEnv *env = (JNIEnv *)rci_window_android_jni_env();

    if (o->surface && env) {
        (*env)->CallVoidMethod(env, o->surface, rci_image_media_oes.release);
        (*env)->ExceptionClear(env);
        (*env)->DeleteGlobalRef(env, o->surface);
    }
    if (o->oes && o->epoch == rci_gfx_epoch())
        glDeleteTextures(1, &o->oes);
    rci_image_media_page_free(o->image, o->page, o->epoch);
    if (o->oes || o->page)
        rci_gfx_gl_touched();
    *o = (RCI_ImageMediaOes){ 0 };
}

static void rci_image_media_lend(RCI_ImageMedia *im, const RCI_LoopMedia *media) {
    RCI_ImageMediaOes *o     = &im->oes;
    const uint32_t     epoch = rci_gfx_epoch();
    JNIEnv            *env;
    jobject            st;
    GLuint             oes = 0;

    if (!epoch || !rci_gfx_frame_active() || (o->surface && o->epoch == epoch))
        return;
    env = (JNIEnv *)rci_window_android_jni_env();
    if (!env || !rci_image_media_jni(env))
        return;
    if (o->surface) {
        media->lend(im->media, NULL);
        rci_image_media_oes_drop(o);
    }
    glGenTextures(1, &oes);
    glBindTexture(GL_TEXTURE_EXTERNAL_OES, oes);
    glTexParameteri(GL_TEXTURE_EXTERNAL_OES, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
    glTexParameteri(GL_TEXTURE_EXTERNAL_OES, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
    glTexParameteri(GL_TEXTURE_EXTERNAL_OES, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
    glTexParameteri(GL_TEXTURE_EXTERNAL_OES, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
    glBindTexture(GL_TEXTURE_EXTERNAL_OES, 0);
    rci_gfx_gl_touched();
    st = oes ? (*env)->NewObject(env, rci_image_media_oes.cls, rci_image_media_oes.init, (jint)oes)
             : NULL;
    if (st && !(*env)->ExceptionCheck(env))
        o->surface = (*env)->NewGlobalRef(env, st);
    (*env)->ExceptionClear(env);
    if (st)
        (*env)->DeleteLocalRef(env, st);
    if (!o->surface) {
        if (oes)
            glDeleteTextures(1, &oes);
        RCI_LOG_WARN_ONCE("rcMediaImage: no SurfaceTexture for a video to draw into; it draws "
                          "nothing");
        return;
    }
    o->oes   = oes;
    o->epoch = epoch;
    media->lend(im->media, o->surface);
}

static void rci_image_media_blit(const RCI_ImageMediaOes *o, const GLfloat m[16], bool fresh) {
    GLint bound = 0;

    glGetIntegerv(GL_FRAMEBUFFER_BINDING, &bound);
    glBindFramebuffer(GL_FRAMEBUFFER, rci_image_media_oes.fbo);
    glFramebufferTexture2D(GL_FRAMEBUFFER, GL_COLOR_ATTACHMENT0, GL_TEXTURE_2D, o->page, 0);
    if (!fresh || glCheckFramebufferStatus(GL_FRAMEBUFFER) == GL_FRAMEBUFFER_COMPLETE) {
        glViewport(0, 0, o->w, o->h);
        glDisable(GL_SCISSOR_TEST);
        glDisable(GL_BLEND);
        glDisable(GL_DEPTH_TEST);
        glDisable(GL_STENCIL_TEST);
        glDisable(GL_CULL_FACE);
        glColorMask(GL_TRUE, GL_TRUE, GL_TRUE, GL_TRUE);
        glUseProgram(rci_image_media_oes.program);
        glUniformMatrix4fv(rci_image_media_oes.matrix, 1, GL_FALSE, m);
        glActiveTexture(GL_TEXTURE0);
        glBindSampler(0, 0);
        glBindTexture(GL_TEXTURE_EXTERNAL_OES, o->oes);

        glBindVertexArray(0);
        glBindBuffer(GL_ARRAY_BUFFER, 0);
        glVertexAttribPointer(0, 2, GL_FLOAT, GL_FALSE, 0, rci_image_media_quad);
        glEnableVertexAttribArray(0);
        glDrawArrays(GL_TRIANGLE_STRIP, 0, 4);
        glDisableVertexAttribArray(0);
        glBindTexture(GL_TEXTURE_EXTERNAL_OES, 0);
    }
    glFramebufferTexture2D(GL_FRAMEBUFFER, GL_COLOR_ATTACHMENT0, GL_TEXTURE_2D, 0, 0);
    glBindFramebuffer(GL_FRAMEBUFFER, (GLuint)bound);
    rci_gfx_gl_touched();
}

static bool rci_image_media_latch(RCI_ImageMedia *im, const RCI_LoopMedia *media, RCI_LoopFrame *f) {
    RCI_ImageMediaOes *o     = &im->oes;
    const uint32_t     epoch = rci_gfx_epoch();
    const int          w = im->image.width, h = im->image.height;
    JNIEnv            *env   = (JNIEnv *)rci_window_android_jni_env();
    GLfloat            m[16];
    bool               fresh = false;

    im->rev = f->rev;
    media->release(f);
    if (!env || !o->surface || o->epoch != epoch || !rci_image_media_program(epoch))
        return false;
    (*env)->CallVoidMethod(env, o->surface, rci_image_media_oes.update);
    if (!(*env)->ExceptionCheck(env))
        (*env)->CallVoidMethod(env, o->surface, rci_image_media_oes.transform, rci_image_media_oes.m);
    if (!(*env)->ExceptionCheck(env))
        (*env)->GetFloatArrayRegion(env, rci_image_media_oes.m, 0, 16, m);
    if ((*env)->ExceptionCheck(env)) {
        (*env)->ExceptionClear(env);
        rci_gfx_gl_touched();
        return false;
    }
    if (!o->page || o->w != f->width || o->h != f->height) {
        RCI_ImageMediaRetired *old;
        GLuint                 page = 0;
        GLint                  max = 0;
        bool                   made;
        void                  *image;

        if (f->width == o->refusedW && f->height == o->refusedH)
            return false;
        glGetIntegerv(GL_MAX_TEXTURE_SIZE, &max);
        if (f->width > max || f->height > max) {
            char why[96];

            o->refusedW = f->width;
            o->refusedH = f->height;
            snprintf(why, sizeof why, "its %dx%d frames are past this device's texture limit, %d",
                     f->width, f->height, (int)max);
            media->fail(im->media, why);
            return false;
        }

        old = o->image ? malloc(sizeof *old) : NULL;
        if (o->image && !old)
            return false;
        for (int i = 0; i < 8 && glGetError() != GL_NO_ERROR; i++)
            continue;
        glGenTextures(1, &page);
        glBindTexture(GL_TEXTURE_2D, page);
        glTexStorage2D(GL_TEXTURE_2D, 1, GL_RGBA8, f->width, f->height);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
        glBindTexture(GL_TEXTURE_2D, 0);
        made  = page && glGetError() == GL_NO_ERROR;
        image = made ? rci_gfx_image_wrap_gl(page, f->width, f->height) : NULL;
        if (!image) {
            if (page)
                glDeleteTextures(1, &page);
            free(old);
            rci_gfx_gl_touched();
            if (!made) {
                o->refusedW = f->width;
                o->refusedH = f->height;
                RCI_LOG_WARN_ONCE("rcMediaImage: this device's GL would not make a %dx%d texture "
                                  "for a video's frames; it draws nothing at that size",
                                  f->width, f->height);
            }
            return false;
        }
        if (old) {
            *old = (RCI_ImageMediaRetired){ o->image, o->page, o->epoch };
            rci_base_defer_free(old, rci_image_media_retired_free);
        }
        o->image = image;
        o->page  = page;
        o->w     = f->width;
        o->h     = f->height;
        fresh    = true;
    }
    rci_image_media_blit(o, m, fresh);
    o->latched++;
    im->ref.width  = im->image.width  = o->w;
    im->ref.height = im->image.height = o->h;
    return im->image.width != w || im->image.height != h;
}

unsigned rci_image_media_latched(uint32_t media) {
    const RCI_ImageMedia *im = rci_image_media_list;

    while (im && (im->dead || im->media != media))
        im = im->next;
    return im ? im->oes.latched : 0u;
}
#else

static bool rci_image_media_latch(RCI_ImageMedia *im, const RCI_LoopMedia *media, RCI_LoopFrame *f) {
    im->rev = f->rev;
    media->release(f);
    return false;
}
#endif

static void rci_image_media_free(void *p) {
    RCI_ImageMedia *im = p, **at = &rci_image_media_list;

    while (*at != im)
        at = &(*at)->next;
    *at = im->next;
#if defined(__EMSCRIPTEN__)
    rci_gfx_element_page_destroy(im->page);
#else
    if (im->pixels.handle)
        ((RCI_ImageRef *)im->pixels.handle)->ops->release(im->pixels.handle);
    rci_gfx_yuv_page_destroy(im->yuv);
#endif
#if defined(__ANDROID__)
    rci_image_media_oes_drop(&im->oes);
#endif
    free(im);
}

static void rci_image_media_retire(RCI_ImageMedia *im) {
    im->dead = true;
    rci_base_defer_free(im, rci_image_media_free);
}

static void rci_image_media_teardown(void) {
    RCI_ImageMedia *im = rci_image_media_list, *next;

    for (; im; im = next) {
        next = im->next;
        if (!im->dead)
            rci_image_media_free(im);
    }
#if defined(__ANDROID__)
    if (rci_image_media_oes.epoch && rci_image_media_oes.epoch == rci_gfx_epoch()) {
        if (rci_image_media_oes.program)
            glDeleteProgram(rci_image_media_oes.program);
        if (rci_image_media_oes.fbo)
            glDeleteFramebuffers(1, &rci_image_media_oes.fbo);
    }
    rci_image_media_oes.epoch   = 0;
    rci_image_media_oes.program = 0;
    rci_image_media_oes.fbo     = 0;
#endif
}

static void rci_image_media_unload(void *ref) {
    (void)ref;
    RCI_LOG_WARN_ONCE("rcUnloadImage: an image from rcMediaImage is its media's; "
                      "rcMediaClose frees it");
}

static void rci_image_media_closed(uint32_t media) {
    RCI_ImageMedia *im = rci_image_media_list;

    while (im && (im->dead || im->media != media))
        im = im->next;
    if (im)
        rci_image_media_retire(im);
}

#if defined(__EMSCRIPTEN__)
static void rci_image_media_free_page(void *page) {
    rci_gfx_element_page_destroy(page);
}

static void rci_image_media_element(RCI_ImageMedia *im, const RCI_LoopFrame *f) {
    if (!im->page || f->width != im->image.width || f->height != im->image.height) {
        RCI_GfxElementPage *page = rci_gfx_element_page_create(f->width, f->height);

        if (!page)
            return;
        if (im->page)
            rci_base_defer_free(im->page, rci_image_media_free_page);
        im->page       = page;
        im->ref.width  = im->image.width  = f->width;
        im->ref.height = im->image.height = f->height;
    }
    im->element = f->element;
}
#else
static void rci_image_media_free_yuv(void *page) {
    rci_gfx_yuv_page_destroy(page);
}

static bool rci_image_media_yuv(RCI_ImageMedia *im, const RCI_LoopFrame *f) {
    const int       w = f->width, h = f->height;
    const int       cw = w - w / 2, ch = h - h / 2;
    RCI_GfxYuvPage *page = im->yuv;

    if (!f->pixels || !f->u || !f->v || w < 1 || h < 1 || w > RCI_GFX_RGBA_SIDE_MAX ||
        h > RCI_GFX_RGBA_SIDE_MAX || w > RCI_IMAGE_MAX_PIXELS / h || f->stride < w ||
        f->uStride < cw || f->vStride < cw) {
        RCI_LOG_WARN_ONCE("rcMediaImage: refused an I420 frame %dx%d, strides %d/%d/%d: a "
                          "plane missing, a side under 1 or over 16384, over 50000000 "
                          "pixels, or a stride under its plane's width", w, h, f->stride,
                          f->uStride, f->vStride);
        return false;
    }
    if (!page || im->yuvW != w || im->yuvH != h) {
        page = rci_gfx_yuv_page_create(w, h);
        if (!page) {
            RCI_LOG_WARN_ONCE("rcMediaImage: no memory for a video's %dx%d planes; it keeps "
                              "its previous picture", w, h);
            return false;
        }
        if (im->yuv)
            rci_base_defer_free(im->yuv, rci_image_media_free_yuv);
        im->yuv  = page;
        im->yuvW = w;
        im->yuvH = h;
    }
    for (int p = 0; p < 3; p++) {
        const unsigned char *src    = p == 0 ? f->pixels : p == 1 ? f->u : f->v;
        const size_t         stride = (size_t)(p == 0 ? f->stride : p == 1 ? f->uStride : f->vStride);
        const size_t         row    = (size_t)(p ? cw : w);
        unsigned char       *dst    = rci_gfx_yuv_page_plane(page, p);

        for (int y = 0, rows = p ? ch : h; y < rows; y++)
            memcpy(dst + (size_t)y * row, src + (size_t)y * stride, row);
    }
    rci_gfx_yuv_page_touch(page, f->matrix, f->fullRange != 0);
    return true;
}
#endif

static bool rci_image_media_write(RCI_ImageMedia *im, const RCI_LoopMedia *media,
                                  RCI_LoopFrame *f) {
    const int width = im->image.width, height = im->image.height;

#if defined(__EMSCRIPTEN__)
    rci_image_media_element(im, f);
#else
    if (f->format == RCI_LOOP_PIXELS_I420 ? rci_image_media_yuv(im, f)
                                          : rcImageUpdate(&im->pixels, f->pixels, f->width,
                                                          f->height, f->stride,
                                                          (RC_PixelFormat)f->format)) {

        if (f->format == RCI_LOOP_PIXELS_I420) {
            if (im->pixels.handle)
                rci_base_defer_free(im->pixels.handle,
                                    ((RCI_ImageRef *)im->pixels.handle)->ops->release);
            im->pixels = (RC_Image){ 0 };
        } else if (im->yuv) {
            rci_base_defer_free(im->yuv, rci_image_media_free_yuv);
            im->yuv = NULL;
        }
        im->ref.width  = im->image.width  = f->width;
        im->ref.height = im->image.height = f->height;
    }
#endif
    im->rev = f->rev;
    media->release(f);
    return im->image.width != width || im->image.height != height;
}

static void *rci_image_media_texture(RCI_ImageRef *ref, float width, float height,
                                     unsigned frame) {
    RCI_ImageMedia      *im    = (RCI_ImageMedia *)ref;
    const RCI_LoopMedia *media = rci_loop_media();
    RCI_LoopFrame        f     = { 0 };
    double               next  = INFINITY;
    unsigned             bits  = 0;

    if (!im->dead && media)
        bits = media->acquire(im->media, im->rev, &f, &next);

    if ((bits & RCI_LOOP_MEDIA_FRAME) &&
        (f.format == RCI_LOOP_PIXELS_EXTERNAL ? rci_image_media_latch(im, media, &f)
                                              : rci_image_media_write(im, media, &f)))
        rci_sched_need_frame();
    if (bits & RCI_LOOP_MEDIA_OPEN) {
        const double now = rci_input_time();

        if (next < INFINITY)
            rci_sched_need_frame_at(now + next);
        if (!(bits & RCI_LOOP_MEDIA_PENDING)) {
            im->owedSince = -1.0;
        } else {
            if (im->owedSince < 0.0)
                im->owedSince = now;
            if (now - im->owedSince < RCI_IMAGE_MEDIA_OWED_S)
                rci_sched_need_frame();
        }
    }
#if defined(__EMSCRIPTEN__)
    (void)width;
    (void)height;
    (void)frame;
    return rci_gfx_element_page_texture(im->page, im->element, im->rev);
#else
#if defined(__ANDROID__)
    if (im->oes.image)
        return rci_gfx_image_wrapped(im->oes.image, im->rev);
#endif
    if (im->yuv)
        return rci_gfx_yuv_page_texture(im->yuv);
    ref = im->pixels.handle;
    return ref ? ref->ops->texture(ref, width, height, frame) : NULL;
#endif
}

static const RCI_ImageOps rci_image_media_ops = { rci_image_media_texture, rci_image_media_unload };

const RC_Image *rcMediaImage(RC_Media media) {
    const RCI_LoopMedia *table = rci_loop_media();
    RCI_ImageMedia      *im    = rci_image_media_list;
    const unsigned       bits  = table ? table->acquire(media, 0, NULL, NULL) : 0u;

    if (!(bits & (RCI_LOOP_MEDIA_FRAME | RCI_LOOP_MEDIA_EXTERNAL)))
        return NULL;
    while (im && (im->dead || im->media != media))
        im = im->next;
    if (!im) {
        im = calloc(1, sizeof *im);
        if (!im) {
            RCI_LOG_WARN_ONCE("rcMediaImage: out of memory; the media draws nothing");
            return NULL;
        }
        im->ref.ops          = &rci_image_media_ops;
        im->media            = media;
        im->owedSince        = -1.0;
        im->next             = rci_image_media_list;
        rci_image_media_list = im;
        table->watch(rci_image_media_closed);
        rci_api_register_teardown(rci_image_media_teardown);
    }
#if defined(__ANDROID__)
    if (bits & RCI_LOOP_MEDIA_EXTERNAL)
        rci_image_media_lend(im, table);
#endif
    if (!(bits & RCI_LOOP_MEDIA_FRAME))
        return NULL;
    if (!im->rev) {

        RCI_LoopFrame f = { 0 };
        double        next;

        if (table->acquire(media, 0, &f, &next) & RCI_LOOP_MEDIA_FRAME) {
            if (f.format != RCI_LOOP_PIXELS_EXTERNAL) {
                (void)rci_image_media_write(im, table, &f);
            } else {
                im->ref.width  = im->image.width  = f.width;
                im->ref.height = im->image.height = f.height;
                table->release(&f);
            }
        }
    }
    im->image.handle = im;
    return &im->image;
}

#include <stdint.h>

#define RCI_DRAGOVER_IDS 128

static uint32_t    rci_dragover_ids[RCI_DRAGOVER_IDS];
static int         rci_dragover_count;
static const void *rci_dragover_window;

#if RCI_WINDOW_HAS_OLE_DROP_TARGET

extern RCI_Window *rci_dragover_win32_armed;
void rci_dragover_win32_arm(RCI_Window *w);
#endif

static void rci_dragover_hit(void) {
    double x, y;
    CLAY_Vector2 at;
    CLAY_ElementId found[RCI_DRAGOVER_IDS];
    int32_t n;

    rci_dragover_count  = 0;
    rci_dragover_window = rci_input_window_token();
    if (!rci_input_drag(&x, &y) || !clayGetCurrentContext())
        return;
    at.x = rci_api_logical_x(x);
    at.y = rci_api_logical_y(y);
    n = clayGetPointerOverIdsAt(at, found, RCI_DRAGOVER_IDS);
    if (n > RCI_DRAGOVER_IDS)
        n = RCI_DRAGOVER_IDS;
    for (int32_t i = 0; i < n; i++)
        rci_dragover_ids[i] = found[i].id;
    rci_dragover_count = n > 0 ? n : 0;
}

bool rcIsDragOver(const char *id) {
    uint32_t want;

#if RCI_WINDOW_HAS_OLE_DROP_TARGET
    if (rci_app_bound_native() != rci_dragover_win32_armed)
        rci_dragover_win32_arm(rci_app_bound_native());
#endif
    if (id)
        rci_core_drag_hit = rci_dragover_hit;
    if (!rci_input_drag(NULL, NULL))
        return false;
    if (!id)
        return true;
    if (!clayGetCurrentContext() || rci_dragover_window != rci_input_window_token())
        return false;
    want = clayGetElementId(rcStringFromCStr(id)).id;
    for (int i = 0; i < rci_dragover_count; i++) {
        if (rci_dragover_ids[i] == want)
            return true;
    }
    return false;
}

