#define RCI_RESIZE_BAND 6

#define RCI_ZOOM_KEY_IN_DEFAULT    RC_KEY_EQUAL
#define RCI_ZOOM_KEY_OUT_DEFAULT   RC_KEY_MINUS
#define RCI_ZOOM_KEY_RESET_DEFAULT RC_KEY_0
