static inline bool rci_window_fit_to_workarea(int win_w, int win_h,
                                              int wa_w, int wa_h,
                                              int *out_w, int *out_h) {

    if (wa_w <= 0 || wa_h <= 0) {
        *out_w = win_w;
        *out_h = win_h;
        return false;
    }
    *out_w = win_w > wa_w ? wa_w : win_w;
    *out_h = win_h > wa_h ? wa_h : win_h;
    return *out_w != win_w || *out_h != win_h;
}

static inline bool rci_window_clamp_to_workarea(int x, int y, int win_w, int win_h,
                                                int wa_x, int wa_y, int wa_w, int wa_h,
                                                int *out_x, int *out_y) {
    int lo_x, lo_y, hi_x, hi_y, cx, cy;

    if (wa_w <= 0 || wa_h <= 0) {
        *out_x = x;
        *out_y = y;
        return false;
    }
    lo_x = wa_x;
    lo_y = wa_y;
    hi_x = wa_x + wa_w - win_w;
    hi_y = wa_y + wa_h - win_h;

    cx = x  > hi_x ? hi_x : x;
    cy = y  > hi_y ? hi_y : y;
    cx = cx < lo_x ? lo_x : cx;
    cy = cy < lo_y ? lo_y : cy;

    *out_x = cx;
    *out_y = cy;
    return cx != x || cy != y;
}

static inline void rci_window_inset_workarea(int *wa_x, int *wa_y, int *wa_w, int *wa_h,
                                             int left, int top, int right, int bottom) {
    const int w = *wa_w - left - right;
    const int h = *wa_h - top - bottom;

    if (left < 0 || top < 0 || right < 0 || bottom < 0 || w <= 0 || h <= 0)
        return;
    *wa_x += left;
    *wa_y += top;
    *wa_w = w;
    *wa_h = h;
}

static inline bool rci_window_rescale(int logical_w, int logical_h, double scale,
                                      const int area[4], bool place, int rect[4]) {
    const double sw = logical_w * scale + 0.5, sh = logical_h * scale + 0.5;
    int w, h, x = rect[0], y = rect[1];
    bool changed;

    if (!(scale > 0.0 && scale < 1e6) || logical_w <= 0 || logical_h <= 0)
        return false;
    w = sw >= INT_MAX ? INT_MAX : sw < 2.0 ? 1 : (int)sw;
    h = sh >= INT_MAX ? INT_MAX : sh < 2.0 ? 1 : (int)sh;
    (void)rci_window_fit_to_workarea(w, h, area[2], area[3], &w, &h);
    if (place)
        (void)rci_window_clamp_to_workarea(x, y, w, h, area[0], area[1], area[2], area[3],
                                           &x, &y);
    changed = x != rect[0] || y != rect[1] || w != rect[2] || h != rect[3];
    rect[0] = x;
    rect[1] = y;
    rect[2] = w;
    rect[3] = h;
    return changed;
}

static inline bool rci_window_dpi_scaled_size(int client_w, int client_h, int from_dpi,
                                              int to_dpi, int frame_w, int frame_h,
                                              int size[2]) {
    double lw, lh, w, h;

    if (client_w <= 0 || client_h <= 0 || from_dpi <= 0 || to_dpi <= 0 || frame_w < 0 ||
        frame_h < 0)
        return false;
    lw = (double)client_w * 96.0 / from_dpi + 0.5;
    lh = (double)client_h * 96.0 / from_dpi + 0.5;
    if (!(lw < INT_MAX && lh < INT_MAX))
        return false;
    w = (int)lw * (double)to_dpi / 96.0 + 0.5 + frame_w;
    h = (int)lh * (double)to_dpi / 96.0 + 0.5 + frame_h;
    if (!(w < INT_MAX && h < INT_MAX))
        return false;
    size[0] = (int)w;
    size[1] = (int)h;
    return true;
}

static inline int rci_window_resize_edge(float mx, float my, int ww, int wh) {
    bool left = mx <= RCI_RESIZE_BAND, right = mx >= (float)(ww - RCI_RESIZE_BAND);
    bool top  = my <= RCI_RESIZE_BAND, bottom = my >= (float)(wh - RCI_RESIZE_BAND);
    if (top    && left)  return RCI_RESIZE_TOPLEFT;
    if (top    && right) return RCI_RESIZE_TOPRIGHT;
    if (bottom && left)  return RCI_RESIZE_BOTTOMLEFT;
    if (bottom && right) return RCI_RESIZE_BOTTOMRIGHT;
    if (left)            return RCI_RESIZE_LEFT;
    if (right)           return RCI_RESIZE_RIGHT;
    if (top)             return RCI_RESIZE_TOP;
    if (bottom)          return RCI_RESIZE_BOTTOM;
    return -1;
}

static inline bool rci_window_cursor_in_content(double x, double y, int w, int h) {
    return x >= 0.0 && y >= 0.0 && x < (double)w && y < (double)h;
}

#define RCI_WINDOW_HAND_SIZE 16
static inline void rci_window_hand_rgba(bool closed, int scale, unsigned char *rgba, int stride) {

    static const unsigned short bits[2][2][RCI_WINDOW_HAND_SIZE] = {
        { { 0x00c0, 0x0720, 0x0938, 0x3924, 0x4924, 0x4926, 0x4925, 0x4921,
            0x4002, 0x4002, 0x4002, 0x4004, 0x2008, 0x1010, 0x1010, 0x0fe0 },
          { 0x00c0, 0x07e0, 0x0ff8, 0x3ffc, 0x7ffc, 0x7ffe, 0x7fff, 0x7fff,
            0x7ffe, 0x7ffe, 0x7ffe, 0x7ffc, 0x3ff8, 0x1ff0, 0x1ff0, 0x0fe0 } },
        { { 0x0000, 0x0000, 0x0000, 0x0000, 0x0d80, 0x1270, 0x3248, 0x5248,
            0x4004, 0x4002, 0x4002, 0x4004, 0x2008, 0x1010, 0x1010, 0x0fe0 },
          { 0x0000, 0x0000, 0x0000, 0x0000, 0x0d80, 0x1ff0, 0x3ff8, 0x7ff8,
            0x7ffc, 0x7ffe, 0x7ffe, 0x7ffc, 0x3ff8, 0x1ff0, 0x1ff0, 0x0fe0 } }
    };
    const unsigned short *ink = bits[closed][0], *hand = bits[closed][1];
    const int side = RCI_WINDOW_HAND_SIZE * scale;

    for (int i = 0; i < side * side; i++) {
        const int y = i / side / scale;
        const unsigned bit = 1u << (i % side / scale);
        const unsigned px = (ink[y] & bit) ? 0xff000000u : (hand[y] & bit) ? 0xffffffffu : 0u;

        memcpy(rgba + (size_t)(i / side) * (size_t)stride + (size_t)(i % side) * 4, &px, 4);
    }
}

static inline int rci_window_hand_scale(float content_scale) {
    return !(content_scale >= 1.5f) ? 1 : content_scale < 2.5f ? 2 : 3;
}

static inline RCI_WindowCursor rci_window_resolve_cursor(int edge, RCI_WindowCursor want) {
    switch (edge) {
    case RCI_RESIZE_LEFT:
    case RCI_RESIZE_RIGHT:       return RCI_WINDOW_CURSOR_RESIZE_EW;
    case RCI_RESIZE_TOP:
    case RCI_RESIZE_BOTTOM:      return RCI_WINDOW_CURSOR_RESIZE_NS;
    case RCI_RESIZE_TOPLEFT:
    case RCI_RESIZE_BOTTOMRIGHT: return RCI_WINDOW_CURSOR_RESIZE_NWSE;
    case RCI_RESIZE_TOPRIGHT:
    case RCI_RESIZE_BOTTOMLEFT:  return RCI_WINDOW_CURSOR_RESIZE_NESW;
    default:                    return want;
    }
}

static inline void rci_window_letter_claim(int letters[26], int letter, int code, int home) {
    int held = letters[letter];
    if (!held || (held == home && code != home))
        letters[letter] = code;
}

