bool rci_window_raise(RCI_Window *w) {
#if !RCI_WINDOW_SDL_MOBILE
    RCI_WindowSdlRecord *s = rci_window_sdl_record(w);

    if (!s)
        return false;
#if RCI_WINDOW_SDL_QUIET_RESTORE

    if (s->quietRestore) {
        s->quietRestore = false;
        (void)SDL_SetWindowFocusable(s->window, true);
    }
#endif
    if (!SDL_RaiseWindow(s->window)) {
        rci_window_sdl_error("raise window");
        return false;
    }
    return true;
#else
    (void)w;
    return false;
#endif
}

bool rci_window_native_parent(RCI_Window *w, RCI_NativeParent *out) {
    RCI_WindowSdlRecord *s = rci_window_sdl_record(w);
    SDL_PropertiesID props = s ? SDL_GetWindowProperties(s->window) : 0;

    memset(out, 0, sizeof *out);
    if (!props)
        return false;
    out->hwnd     = SDL_GetPointerProperty(props, SDL_PROP_WINDOW_WIN32_HWND_POINTER, NULL);
    out->nswindow = SDL_GetPointerProperty(props, SDL_PROP_WINDOW_COCOA_WINDOW_POINTER, NULL);
    out->x11      = (unsigned long)SDL_GetNumberProperty(props, SDL_PROP_WINDOW_X11_WINDOW_NUMBER, 0);
    out->wayland  = SDL_GetStringProperty(props,
                        SDL_PROP_WINDOW_WAYLAND_XDG_TOPLEVEL_EXPORT_HANDLE_STRING, NULL);
    out->uiwindow = SDL_GetPointerProperty(props, SDL_PROP_WINDOW_UIKIT_WINDOW_POINTER, NULL);
    return out->hwnd || out->nswindow || out->x11 || out->wayland || out->uiwindow;
}

