#if RCI_WINDOW_SDL_QUIET_RESTORE

static bool rci_window_sdl_end_quiet_restore(RCI_WindowSdlRecord *s) {
#if RCI_WINDOW_SDL_X11_SCHEME
    SDL_PropertiesID props;
    Display *dpy;
    Window x;
    XWindowAttributes wa;
#endif

    if (!s->quietRestore)
        return false;
#if RCI_WINDOW_SDL_X11_SCHEME
    props = SDL_GetWindowProperties(s->window);
    dpy = (Display *)SDL_GetPointerProperty(props, SDL_PROP_WINDOW_X11_DISPLAY_POINTER, NULL);
    x = (Window)SDL_GetNumberProperty(props, SDL_PROP_WINDOW_X11_WINDOW_NUMBER, 0);
    if (dpy && x != None && !(XGetWindowAttributes(dpy, x, &wa) && wa.map_state == IsViewable))
        return true;
#else
    if (SDL_GetWindowFlags(s->window) & SDL_WINDOW_MINIMIZED)
        return true;
#endif
    s->quietRestore = false;
    if (!SDL_SetWindowFocusable(s->window, true))
        rci_window_sdl_error("restore focusability after a quiet restore");
#if RCI_WINDOW_SDL_X11_SCHEME
    if (dpy)
        XSync(dpy, False);
#endif
    return false;
}

static void rci_window_sdl_quiet_pumped(void) {
    bool left = false;

    for (RCI_WindowSdlRecord *s = rci_window_sdl_records; s; s = s->next)
        left |= rci_window_sdl_end_quiet_restore(s);
    if (!left)
        rci_window_sdl_quiet_pump = NULL;
}
#endif

#if RCI_WINDOW_SDL_X11_SCHEME

static bool rci_window_sdl_wait_shown(Display *dpy, Window x) {
    const Uint64 end = SDL_GetTicksNS() + SDL_NS_PER_SECOND / 2;
    int seen = -1;

    for (;;) {
        XWindowAttributes wa;
        struct pollfd fd;
        Uint64 now;
        int queued;

        if (XGetWindowAttributes(dpy, x, &wa) && wa.map_state == IsViewable)
            return true;
        now = SDL_GetTicksNS();
        if (now >= end)
            return false;
        queued = XEventsQueued(dpy, QueuedAfterReading);
        if (queued != seen) {
            seen = queued;
            continue;
        }
        fd.fd      = ConnectionNumber(dpy);
        fd.events  = POLLIN;
        fd.revents = 0;
        (void)poll(&fd, 1, (int)((end - now) / SDL_NS_PER_MS) + 1);
    }
}

static void rci_window_sdl_restore_quiet(RCI_WindowSdlRecord *s, Display *dpy, Window x) {
    const Atom state   = XInternAtom(dpy, "_NET_WM_STATE", False);
    const Atom hidden  = XInternAtom(dpy, "_NET_WM_STATE_HIDDEN", False);
    const Atom focused = XInternAtom(dpy, "_NET_WM_STATE_FOCUSED", False);
    long held[16];
    int n = 0;
    Atom type;
    int format;
    unsigned long count = 0, after;
    unsigned char *data = NULL;

    if (XGetWindowProperty(dpy, x, state, 0, 16, False, XA_ATOM, &type, &format, &count,
                           &after, &data) == Success && data) {
        const long *atoms = (const long *)(const void *)data;

        for (unsigned long i = 0; i < count && n < 16; i++)
            if ((Atom)atoms[i] != hidden && (Atom)atoms[i] != focused)
                held[n++] = atoms[i];
        XFree(data);
    }

    s->quietRestore = (SDL_GetWindowFlags(s->window) & SDL_WINDOW_NOT_FOCUSABLE) == 0 &&
                      SDL_SetWindowFocusable(s->window, false);
    XWithdrawWindow(dpy, x, DefaultScreen(dpy));
    XMapWindow(dpy, x);
    for (int i = 0; i < n; i++) {
        XEvent e;

        memset(&e, 0, sizeof e);
        e.xclient.type         = ClientMessage;
        e.xclient.window       = x;
        e.xclient.message_type = state;
        e.xclient.format       = 32;
        e.xclient.data.l[0]    = 1;
        e.xclient.data.l[1]    = held[i];
        e.xclient.data.l[3]    = 1;
        XSendEvent(dpy, DefaultRootWindow(dpy), False,
                   SubstructureNotifyMask | SubstructureRedirectMask, &e);
    }
    (void)rci_window_sdl_wait_shown(dpy, x);
    XRaiseWindow(dpy, x);
    XFlush(dpy);
    if (rci_window_sdl_end_quiet_restore(s))
        rci_window_sdl_quiet_pump = rci_window_sdl_quiet_pumped;
}
#endif

void rci_window_restore(RCI_Window *w) {
#if !RCI_WINDOW_SDL_MOBILE
    RCI_WindowSdlRecord *s = rci_window_sdl_record(w);

    if (s && !SDL_RestoreWindow(s->window))
        rci_window_sdl_error("restore window");
#else
    (void)w;
#endif
}

bool rci_window_restore_unfocused(RCI_Window *w) {
#if RCI_WINDOW_SDL_X11_SCHEME
    RCI_WindowSdlRecord *s = rci_window_sdl_record(w);
    SDL_PropertiesID props;
    Display *dpy;
    Window x;

    if (!s || !(SDL_GetWindowFlags(s->window) & SDL_WINDOW_MINIMIZED))
        return false;
    props = SDL_GetWindowProperties(s->window);
    dpy = (Display *)SDL_GetPointerProperty(props, SDL_PROP_WINDOW_X11_DISPLAY_POINTER, NULL);
    x = (Window)SDL_GetNumberProperty(props, SDL_PROP_WINDOW_X11_WINDOW_NUMBER, 0);
    if (!dpy || x == None)
        return false;
    rci_window_sdl_restore_quiet(s, dpy, x);
    return true;
#elif defined(SDL_PLATFORM_MACOS)

    RCI_WindowSdlRecord *s = rci_window_sdl_record(w);

    if (!s || !(SDL_GetWindowFlags(s->window) & SDL_WINDOW_MINIMIZED))
        return false;
    s->quietRestore = (SDL_GetWindowFlags(s->window) & SDL_WINDOW_NOT_FOCUSABLE) == 0 &&
                      SDL_SetWindowFocusable(s->window, false);
    if (!SDL_RestoreWindow(s->window))
        rci_window_sdl_error("restore window");
    if (s->quietRestore)
        rci_window_sdl_quiet_pump = rci_window_sdl_quiet_pumped;
    return true;
#elif defined(SDL_PLATFORM_WINDOWS)

    RCI_WindowSdlRecord *s = rci_window_sdl_record(w);
    HWND hwnd;

    if (!s || !(SDL_GetWindowFlags(s->window) & SDL_WINDOW_MINIMIZED))
        return false;
    hwnd = (HWND)SDL_GetPointerProperty(SDL_GetWindowProperties(s->window),
                                        SDL_PROP_WINDOW_WIN32_HWND_POINTER, NULL);
    if (!hwnd)
        return false;
    ShowWindow(hwnd, SW_SHOWNOACTIVATE);
    return true;
#else
    (void)w;
    return false;
#endif
}

