void rci_window_set_cursor(RCI_Window *w, RCI_WindowCursor shape) {
    RCI_WindowSdlRecord *s = rci_window_sdl_record(w);
    int index = (int)shape;

    if (!s || index < 0 || index >= RCI_WINDOW_CURSOR_COUNT ||
        s->cursor_shape == index)
        return;
    s->cursor_shape = index;
#if RCI_WINDOW_SDL_HAND
    if (!s->cursors[index] &&
        (index == RCI_WINDOW_CURSOR_GRAB || index == RCI_WINDOW_CURSOR_GRABBING))
        s->cursors[index] = rci_window_sdl_hand(s->window, index == RCI_WINDOW_CURSOR_GRABBING);
#endif
    if (SDL_GetMouseFocus() == s->window)
        rci_window_sdl_show_cursor(s);
}

void rci_window_set_refresh_callback(RCI_Window *w, void (*cb)(RCI_Window *)) {
    RCI_WindowSdlRecord *s = rci_window_sdl_record(w);

    if (s)
        s->refresh = cb;
}

void rci_window_set_input_callbacks(RCI_Window *w, const RCI_WindowInputCallbacks *cbs) {
    RCI_WindowSdlRecord *s = rci_window_sdl_record(w);

    if (!s)
        return;
    if (cbs) {
        s->input = *cbs;
    } else {
        memset(&s->input, 0, sizeof(s->input));
    }
#ifdef SDL_PLATFORM_MACOS
    if (rci_window_sdl_cocoa()) {
        if (SDL_GetCurrentThreadID() == rci_window_sdl_owner_thread && SDL_IsMainThread()) {

            if (!s->input.character)
                rci_window_sdl_cocoa_text_input(s->window, false);
            else if (SDL_GetKeyboardFocus() == s->window)
                rci_window_sdl_cocoa_text_input(s->window, true);
        }
        return;
    }
#endif
#ifdef SDL_PLATFORM_IOS

    if (!s->input.character)
        rci_window_sdl_ios_lower(s->window);
#else
    if (s->input.character && !SDL_TextInputActive(s->window)) {
        if (!SDL_StartTextInput(s->window))
            rci_window_sdl_error("start text input");
    } else if (!s->input.character) {
        SDL_StopTextInput(s->window);
    }
#endif
}

void *rci_window_input_user(RCI_Window *w) {
    RCI_WindowSdlRecord *s = rci_window_sdl_record(w);

    return s ? s->input.user : NULL;
}

int rci_window_key_code(RC_Key key) {
    if (key >= RC_KEY_A && key <= RC_KEY_Z)
        return SDL_SCANCODE_A + (key - RC_KEY_A);
    if (key >= RC_KEY_1 && key <= RC_KEY_9)
        return SDL_SCANCODE_1 + (key - RC_KEY_1);
    if (key >= RC_KEY_F1 && key <= RC_KEY_F12)
        return SDL_SCANCODE_F1 + (key - RC_KEY_F1);
    if (key >= RC_KEY_F13 && key <= RC_KEY_F24)
        return SDL_SCANCODE_F13 + (key - RC_KEY_F13);
    if (key >= RC_KEY_KP_1 && key <= RC_KEY_KP_9)
        return SDL_SCANCODE_KP_1 + (key - RC_KEY_KP_1);
    switch (key) {
    case RC_KEY_0:             return SDL_SCANCODE_0;
    case RC_KEY_LEFT:          return SDL_SCANCODE_LEFT;
    case RC_KEY_RIGHT:         return SDL_SCANCODE_RIGHT;
    case RC_KEY_UP:            return SDL_SCANCODE_UP;
    case RC_KEY_DOWN:          return SDL_SCANCODE_DOWN;
    case RC_KEY_HOME:          return SDL_SCANCODE_HOME;
    case RC_KEY_END:           return SDL_SCANCODE_END;
    case RC_KEY_PAGE_UP:       return SDL_SCANCODE_PAGEUP;
    case RC_KEY_PAGE_DOWN:     return SDL_SCANCODE_PAGEDOWN;
    case RC_KEY_INSERT:        return SDL_SCANCODE_INSERT;
    case RC_KEY_DELETE:        return SDL_SCANCODE_DELETE;
    case RC_KEY_BACKSPACE:     return SDL_SCANCODE_BACKSPACE;
    case RC_KEY_TAB:           return SDL_SCANCODE_TAB;
    case RC_KEY_ENTER:         return SDL_SCANCODE_RETURN;
    case RC_KEY_ESCAPE:        return SDL_SCANCODE_ESCAPE;
    case RC_KEY_SPACE:         return SDL_SCANCODE_SPACE;
    case RC_KEY_LEFT_SHIFT:    return SDL_SCANCODE_LSHIFT;
    case RC_KEY_RIGHT_SHIFT:   return SDL_SCANCODE_RSHIFT;
    case RC_KEY_LEFT_CTRL:     return SDL_SCANCODE_LCTRL;
    case RC_KEY_RIGHT_CTRL:    return SDL_SCANCODE_RCTRL;
    case RC_KEY_LEFT_ALT:      return SDL_SCANCODE_LALT;
    case RC_KEY_RIGHT_ALT:     return SDL_SCANCODE_RALT;
    case RC_KEY_LEFT_SUPER:    return SDL_SCANCODE_LGUI;
    case RC_KEY_RIGHT_SUPER:   return SDL_SCANCODE_RGUI;
    case RC_KEY_CAPS_LOCK:     return SDL_SCANCODE_CAPSLOCK;
    case RC_KEY_NUM_LOCK:      return SDL_SCANCODE_NUMLOCKCLEAR;
    case RC_KEY_SCROLL_LOCK:   return SDL_SCANCODE_SCROLLLOCK;
    case RC_KEY_PRINT_SCREEN:  return SDL_SCANCODE_PRINTSCREEN;
    case RC_KEY_PAUSE:         return SDL_SCANCODE_PAUSE;
    case RC_KEY_MENU:          return SDL_SCANCODE_APPLICATION;
    case RC_KEY_APOSTROPHE:    return SDL_SCANCODE_APOSTROPHE;
    case RC_KEY_COMMA:         return SDL_SCANCODE_COMMA;
    case RC_KEY_MINUS:         return SDL_SCANCODE_MINUS;
    case RC_KEY_PERIOD:        return SDL_SCANCODE_PERIOD;
    case RC_KEY_SLASH:         return SDL_SCANCODE_SLASH;
    case RC_KEY_SEMICOLON:     return SDL_SCANCODE_SEMICOLON;
    case RC_KEY_EQUAL:         return SDL_SCANCODE_EQUALS;
    case RC_KEY_LEFT_BRACKET:  return SDL_SCANCODE_LEFTBRACKET;
    case RC_KEY_BACKSLASH:     return SDL_SCANCODE_BACKSLASH;
    case RC_KEY_RIGHT_BRACKET: return SDL_SCANCODE_RIGHTBRACKET;
    case RC_KEY_GRAVE:         return SDL_SCANCODE_GRAVE;
    case RC_KEY_KP_0:          return SDL_SCANCODE_KP_0;
    case RC_KEY_KP_DECIMAL:    return SDL_SCANCODE_KP_PERIOD;
    case RC_KEY_KP_DIVIDE:     return SDL_SCANCODE_KP_DIVIDE;
    case RC_KEY_KP_MULTIPLY:   return SDL_SCANCODE_KP_MULTIPLY;
    case RC_KEY_KP_SUBTRACT:   return SDL_SCANCODE_KP_MINUS;
    case RC_KEY_KP_ADD:        return SDL_SCANCODE_KP_PLUS;
    case RC_KEY_KP_ENTER:      return SDL_SCANCODE_KP_ENTER;
    case RC_KEY_KP_EQUAL:      return SDL_SCANCODE_KP_EQUALS;
    default:                  return RCI_WINDOW_KEY_CODE_NONE;
    }
}

bool rci_window_key_down(RCI_Window *w, RC_Key key) {
    RCI_WindowSdlRecord *s = rci_window_sdl_record(w);
    int code = rci_window_key_code(key);

    return s && code >= 0 && code < RCI_WINDOW_KEY_CODE_LIMIT &&
           !s->background && !SDL_GetAtomicInt(&rci_window_sdl_suspended) &&
           s->keys[code];
}

bool rci_window_mouse_down(RCI_Window *w, RC_PointerButton button) {
    RCI_WindowSdlRecord *s = rci_window_sdl_record(w);

    return s && (int)button >= 0 && (int)button < 3 && !s->background &&
           !SDL_GetAtomicInt(&rci_window_sdl_suspended) && s->buttons[button];
}

void rci_window_cursor_pos(RCI_Window *w, double *x, double *y) {
    RCI_WindowSdlRecord *s = rci_window_sdl_record(w);

    *x = s ? s->x : 0.0;
    *y = s ? s->y : 0.0;
}

bool rci_window_cursor_inside(RCI_Window *w) {
    RCI_WindowSdlRecord *s = rci_window_sdl_record(w);

    if (!s || s->background || SDL_GetAtomicInt(&rci_window_sdl_suspended))
        return false;
    return s->touchPointer ? s->inside : SDL_GetMouseFocus() == s->window;
}

double rci_window_time(void) {
    return (double)SDL_GetTicksNS() / 1000000000.0;
}

int rci_window_key_labeled(RCI_Window *w, char letter) {
    RCI_WindowSdlRecord *s = rci_window_sdl_record(w);

    if (!s || letter < 'a' || letter > 'z')
        return 0;
    if (!s->lettersFresh) {
        memset(s->letters, 0, sizeof(s->letters));

        for (int i = 1; i < SDL_SCANCODE_COUNT; i++) {
            SDL_Keycode key = SDL_GetKeyFromScancode((SDL_Scancode)i, SDL_KMOD_NONE, false);

            if (key >= 'a' && key <= 'z')
                rci_window_letter_claim(s->letters, (int)(key - 'a'), i,
                                        SDL_SCANCODE_A + (int)(key - 'a'));
        }
        s->lettersFresh = true;
    }
    return s->letters[letter - 'a'];
}

const char *rci_window_clipboard_get(RCI_Window *w) {
    RCI_WindowSdlRecord *s = rci_window_sdl_record(w);

    rci_window_sdl_clipboard_clear(s);
    if (!s || !SDL_HasClipboardText())
        return NULL;
    s->clipboard = SDL_GetClipboardText();
    if (!s->clipboard || !*s->clipboard) {
        rci_window_sdl_clipboard_clear(s);
        return NULL;
    }
    rci_input_fold_cr(s->clipboard, s->clipboard);
    return s->clipboard;
}

void rci_window_clipboard_set(RCI_Window *w, const char *text) {
    RCI_WindowSdlRecord *s = rci_window_sdl_record(w);

    if (s && text && !SDL_SetClipboardText(text))
        rci_window_sdl_error("set clipboard text");
    rci_window_sdl_clipboard_clear(s);
}

RCI_WindowPlatform rci_window_platform(void) {
    const char *driver = SDL_GetCurrentVideoDriver();

    if (driver && !strcmp(driver, "x11"))
        return RCI_WINDOW_PLATFORM_X11;
    if (driver && !strcmp(driver, "wayland"))
        return RCI_WINDOW_PLATFORM_WAYLAND;
    return RCI_WINDOW_PLATFORM_OTHER;
}

#if defined(__APPLE__) && !RCI_PLATFORM_MOBILE
#include <CoreFoundation/CFBundle.h>

bool rci_window_bundle_names_icon(void) {
    CFBundleRef bundle = CFBundleGetMainBundle();
    CFStringRef keys[2] = { CFSTR("CFBundleIconFile"), CFSTR("CFBundleIconName") };
    CFURLRef    url = bundle ? CFBundleCopyBundleURL(bundle) : NULL;
    CFStringRef ext = url ? CFURLCopyPathExtension(url) : NULL;
    const bool  app = ext && CFStringCompare(ext, CFSTR("app"), kCFCompareCaseInsensitive) ==
                             kCFCompareEqualTo;

    if (ext) CFRelease(ext);
    if (url) CFRelease(url);
    for (int i = 0; app && i < 2; i++) {
        CFTypeRef name = CFBundleGetValueForInfoDictionaryKey(bundle, keys[i]);
        if (name && CFGetTypeID(name) == CFStringGetTypeID() &&
            CFStringGetLength((CFStringRef)name) > 0)
            return true;
    }
    return false;
}
#endif

