#if RCI_WINDOW_APP_DATA_SEAM
char *rci_window_app_data_path(const char *org, const char *app) {
#ifdef SDL_PLATFORM_EMSCRIPTEN
    size_t len = sizeof "/rayclay/" + strlen(org) + strlen(app) + 2;
    char *path = malloc(len);
    int n;

    if (!path)
        return NULL;
    n = SDL_snprintf(path, len, "/rayclay/%s%s%s", org, *org ? "/" : "", app);
    if (!rci_window_sdl_web_store_open(path, rci_window_sdl_web_store_refused)) {
        free(path);
        return NULL;
    }
    path[n] = '/';
    path[n + 1] = '\0';
    return path;
#else
    char *pref = SDL_GetPrefPath(org, app);
    char *path = NULL;
    size_t len;

    if (!pref)
        return NULL;
#  ifdef SDL_PLATFORM_ANDROID
    len = strlen(pref) + strlen(org) + strlen(app) + 3;
    if ((path = malloc(len)) != NULL) {
        if (*org)
            SDL_snprintf(path, len, "%s%s/%s/", pref, org, app);
        else
            SDL_snprintf(path, len, "%s%s/", pref, app);
        for (char *p = path + strlen(pref); *p; p++) {
            if (*p != '/')
                continue;
            *p = '\0';
            if (mkdir(path, 0700) != 0 && errno != EEXIST) {
                free(path);
                path = NULL;
                break;
            }
            *p = '/';
        }
    }
#  else
    len = strlen(pref) + 1;
    if ((path = malloc(len)) != NULL)
        memcpy(path, pref, len);
#  endif
    SDL_free(pref);
    return path;
#endif
}
#endif

