static bool rci_window_sdl_android_status_bar(int style, bool asked) {
    JNIEnv *env = (JNIEnv *)rci_window_android_jni_env();
    jobject activity = NULL;
    jclass cls = NULL;
    jmethodID apply = NULL;
    bool ok = env != NULL;

    if (ok)
        cls = (*env)->FindClass(env, "org/rayclay/RCActivity");
    ok = ok && cls && !(*env)->ExceptionCheck(env);
    if (ok)
        apply = (*env)->GetStaticMethodID(env, cls, "rcStatusBar", "(Landroid/app/Activity;I)V");
    ok = ok && apply && !(*env)->ExceptionCheck(env);
    if (ok)
        activity = (jobject)rci_window_android_activity();
    ok = ok && activity;
    if (ok)
        (*env)->CallStaticVoidMethod(env, cls, apply, activity, (jint)style);
    ok = ok && !(*env)->ExceptionCheck(env);
    if (env) {
        (*env)->ExceptionClear(env);
        if (activity)
            (*env)->DeleteLocalRef(env, activity);
        if (cls)
            (*env)->DeleteLocalRef(env, cls);
    }
    if (!ok && asked)
        RCI_LOG_WARN_ONCE("rcSetStatusBar: Android's status bar is reached through "
                          "org.rayclay.RCActivity, which this app lacks - add RCActivity.java "
                          "(it ships in RayClay's mobile/android), name it in AndroidManifest.xml "
                          "in place of org.libsdl.app.SDLActivity and keep it whole under R8; "
                          "nothing changed");
    return ok;
}

bool rci_window_set_navigation_bar(RCI_Window *w, int icons);
bool rci_window_set_navigation_bar(RCI_Window *w, int icons) {
    const jint sent = icons == RCI_STATUS_BAR_AUTO_SYSTEM ? RC_STATUS_BAR_AUTO : icons;
    JNIEnv *env;
    jobject activity = NULL;
    jclass cls;
    jmethodID apply = NULL;
    bool ok;

    if (!rci_window_sdl_record(w))
        return false;
    env = (JNIEnv *)rci_window_android_jni_env();
    if (!env)
        return false;
    cls = (*env)->FindClass(env, "org/rayclay/RCActivity");
    ok = cls && !(*env)->ExceptionCheck(env);
    if (ok)
        apply = (*env)->GetStaticMethodID(env, cls, "rcNavigationBar",
                                          "(Landroid/app/Activity;I)V");
    ok = ok && apply && !(*env)->ExceptionCheck(env);
    if (ok)
        activity = (jobject)rci_window_android_activity();
    ok = ok && activity;
    if (ok)
        (*env)->CallStaticVoidMethod(env, cls, apply, activity, sent);
    ok = ok && !(*env)->ExceptionCheck(env);
    (*env)->ExceptionClear(env);
    if (activity)
        (*env)->DeleteLocalRef(env, activity);
    if (cls)
        (*env)->DeleteLocalRef(env, cls);
    return ok;
}

bool rci_window_end_launch_screen(RCI_Window *w);
bool rci_window_end_launch_screen(RCI_Window *w) {
    RCI_WindowSdlRecord *s = rci_window_sdl_record(w);
    JNIEnv *env;
    jclass cls;
    jmethodID done = NULL;

    if (!s || s->close || s->background || SDL_GetAtomicInt(&rci_window_sdl_suspended))
        return false;
    env = (JNIEnv *)rci_window_android_jni_env();
    if (!env)
        return true;
    cls = (*env)->FindClass(env, "org/rayclay/RCActivity");
    if (cls && !(*env)->ExceptionCheck(env))
        done = (*env)->GetStaticMethodID(env, cls, "rcFirstFrame", "()V");
    if (done && !(*env)->ExceptionCheck(env))
        (*env)->CallStaticVoidMethod(env, cls, done);
    (*env)->ExceptionClear(env);
    if (cls)
        (*env)->DeleteLocalRef(env, cls);
    return true;
}
