void rci_window_ime_rect(float x, float y, float width, float height) {
    RCI_WindowSdlRecord *s = rci_window_sdl_current();
    const RCI_WindowSdlMetrics *m;
    SDL_Rect rect, previous;
    int window_width, window_height, cursor = 0;
    double scale, right, bottom;

    if (!s || !isfinite(x) || !isfinite(y) || !isfinite(width) ||
        !isfinite(height) || width < 0.0f || height < 0.0f)
        return;
    m = rci_window_sdl_metrics(s);
    window_width = m->sizeW;
    window_height = m->sizeH;
    if (window_width <= 0 || window_height <= 0)
        return;
    scale = m->scale;
    rect.x = (int)fmin(window_width - 1, fmax(0.0, floor(x * scale)));
    rect.y = (int)fmin(window_height - 1, fmax(0.0, floor(y * scale)));
    right = fmin(window_width, fmax(rect.x + 1.0, ceil(((double)x + width) * scale)));
    bottom = fmin(window_height, fmax(rect.y + 1.0, ceil(((double)y + height) * scale)));
    rect.w = (int)right - rect.x;
    rect.h = (int)bottom - rect.y;

    if (s->ime_area_valid && SDL_GetTextInputArea(s->window, &previous, &cursor) && cursor == 0 &&
        previous.x == rect.x && previous.y == rect.y &&
        previous.w == rect.w && previous.h == rect.h)
        return;

#ifdef SDL_PLATFORM_IOS
    s->ime_area_valid = rci_window_sdl_ios_kb_area(s->window, &rect);
#else
    s->ime_area_valid = SDL_SetTextInputArea(s->window, &rect, 0);
#endif
    if (!s->ime_area_valid)
        rci_window_sdl_error("set IME rectangle");
}

#ifdef SDL_PLATFORM_IOS

void rci_window_ime_clear(void);
void rci_window_ime_clear(void) {
    RCI_WindowSdlRecord *s = rci_window_sdl_current();
    SDL_Rect previous;
    int cursor = 0;

    if (s && !(s->ime_area_valid && SDL_GetTextInputArea(s->window, &previous, &cursor) &&
               previous.h == 0))
        s->ime_area_valid = rci_window_sdl_ios_kb_area(s->window, NULL);
}
#endif

