static double rci_window_sdl_keyboard_height(RCI_WindowSdlRecord *s) {
    id (*get)(id, SEL) = (id (*)(id, SEL))objc_msgSend;
    int (*get_int)(id, SEL) = (int (*)(id, SEL))objc_msgSend;
    id uiwindow, controller;

    uiwindow = (id)SDL_GetPointerProperty(SDL_GetWindowProperties(s->window),
                                          SDL_PROP_WINDOW_UIKIT_WINDOW_POINTER, NULL);
    controller = uiwindow ? get(uiwindow, sel_registerName("rootViewController")) : NULL;
    if (!controller || !class_respondsToSelector(object_getClass(controller),
                                                 sel_registerName("keyboardHeight")))
        return 0.0;
    return (double)get_int(controller, sel_registerName("keyboardHeight"));
}
