static double rci_window_sdl_keyboard_height(RCI_WindowSdlRecord *s) {
    static jmethodID get_window, get_decor, get_root_insets, get_insets, get_height;
    static jfieldID bottom_field;
    static jint ime_mask;
    static int resolved;
    JNIEnv *env = (JNIEnv *)SDL_GetAndroidJNIEnv();
    jobject activity, win = NULL, decor = NULL, root = NULL, insets = NULL;
    double bottom = 0.0, decor_height = 0.0;

    if (!env || resolved < 0)
        return 0.0;
    if (!resolved) {

        static const char *const names[6] = {
            "android/app/Activity", "android/view/Window", "android/view/View",
            "android/view/WindowInsets", "android/view/WindowInsets$Type", "android/graphics/Insets",
        };
        jclass cls[6] = { 0 };
        int i, ok = 1;

        for (i = 0; i < 6 && ok; i++) {
            cls[i] = (*env)->FindClass(env, names[i]);
            if ((*env)->ExceptionCheck(env) || !cls[i]) {
                (*env)->ExceptionClear(env);
                ok = 0;
            }
        }
        if (ok) {
            jmethodID ime_type;

            get_window = (*env)->GetMethodID(env, cls[0], "getWindow", "()Landroid/view/Window;");
            ok = ok && get_window && !(*env)->ExceptionCheck(env);
            if (ok) get_decor = (*env)->GetMethodID(env, cls[1], "getDecorView", "()Landroid/view/View;");
            ok = ok && get_decor && !(*env)->ExceptionCheck(env);
            if (ok) get_root_insets = (*env)->GetMethodID(env, cls[2], "getRootWindowInsets",
                                                          "()Landroid/view/WindowInsets;");
            ok = ok && get_root_insets && !(*env)->ExceptionCheck(env);
            if (ok) get_height = (*env)->GetMethodID(env, cls[2], "getHeight", "()I");
            ok = ok && get_height && !(*env)->ExceptionCheck(env);
            if (ok) get_insets = (*env)->GetMethodID(env, cls[3], "getInsets", "(I)Landroid/graphics/Insets;");
            ok = ok && get_insets && !(*env)->ExceptionCheck(env);
            if (ok) ime_type = (*env)->GetStaticMethodID(env, cls[4], "ime", "()I");
            ok = ok && ime_type && !(*env)->ExceptionCheck(env);
            if (ok) ime_mask = (*env)->CallStaticIntMethod(env, cls[4], ime_type);
            ok = ok && ime_mask && !(*env)->ExceptionCheck(env);
            if (ok) bottom_field = (*env)->GetFieldID(env, cls[5], "bottom", "I");
            ok = ok && bottom_field && !(*env)->ExceptionCheck(env);
            if ((*env)->ExceptionCheck(env))
                (*env)->ExceptionClear(env);
        }
        for (i = 0; i < 6; i++)
            if (cls[i]) (*env)->DeleteLocalRef(env, cls[i]);
        resolved = ok ? 1 : -1;
        if (resolved < 0)
            return 0.0;
    }
    activity = (jobject)SDL_GetAndroidActivity();
    if (!activity)
        return 0.0;

    win = (*env)->CallObjectMethod(env, activity, get_window);
    if ((*env)->ExceptionCheck(env)) { (*env)->ExceptionClear(env); win = NULL; }
    if (win) {
        decor = (*env)->CallObjectMethod(env, win, get_decor);
        if ((*env)->ExceptionCheck(env)) { (*env)->ExceptionClear(env); decor = NULL; }
    }
    if (decor) {
        decor_height = (double)(*env)->CallIntMethod(env, decor, get_height);
        if ((*env)->ExceptionCheck(env)) { (*env)->ExceptionClear(env); decor_height = 0.0; }
        root = (*env)->CallObjectMethod(env, decor, get_root_insets);
        if ((*env)->ExceptionCheck(env)) { (*env)->ExceptionClear(env); root = NULL; }
    }
    if (root) {
        insets = (*env)->CallObjectMethod(env, root, get_insets, ime_mask);
        if ((*env)->ExceptionCheck(env)) { (*env)->ExceptionClear(env); insets = NULL; }
    }
    if (insets) {
        bottom = (double)(*env)->GetIntField(env, insets, bottom_field);
        if ((*env)->ExceptionCheck(env)) { (*env)->ExceptionClear(env); bottom = 0.0; }
    }

    if (bottom > 0.0 && decor_height > 0.0) {
        const int surface_h = rci_window_sdl_metrics(s)->pixel_h;

        if (surface_h > 0 && decor_height > (double)surface_h)
            bottom = fmax(0.0, bottom - (decor_height - (double)surface_h));
    }
    if (insets) (*env)->DeleteLocalRef(env, insets);
    if (root) (*env)->DeleteLocalRef(env, root);
    if (decor) (*env)->DeleteLocalRef(env, decor);
    if (win) (*env)->DeleteLocalRef(env, win);
    (*env)->DeleteLocalRef(env, activity);
    return bottom;
}
#endif

RC_Insets rci_window_keyboard_insets(void) {
    RCI_WindowSdlRecord *s = rci_window_sdl_current();
    const RCI_WindowSdlMetrics *m;
    RC_Insets insets = { 0 };
    double covered;

    if (!s)
        return insets;
    m = rci_window_sdl_metrics(s);
    if (m->sizeH <= 0)
        return insets;

    covered = rci_window_sdl_keyboard_height(s);
#ifdef SDL_PLATFORM_IOS
    covered = rci_window_sdl_ios_kb_cover(s, covered);
#endif
    if (!(covered > 0.0))
        return insets;
    insets.bottom = (float)(fmin(covered, (double)m->sizeH) / m->scale);
    return insets;
}
#endif

#define RCI_WINDOW_SDL_ANDROID_URI_INPUT     0x11
#define RCI_WINDOW_SDL_ANDROID_PHONE_INPUT   0x03

#define RCI_WINDOW_SDL_ANDROID_DECIMAL_INPUT 0x2002

static bool rci_window_sdl_start_text(RCI_WindowSdlRecord *s, RCI_KeyboardKind keyboard) {
    SDL_PropertiesID props;
    SDL_TextInputType type;
    bool started;

#ifdef SDL_PLATFORM_IOS
    rci_window_sdl_ios_lowering = false;

    rci_window_sdl_ios_text_traits(s, keyboard);
    (void)rci_window_sdl_ios_kb_attach(s);
#endif
    switch (keyboard) {
    case RCI_KEYBOARD_PASSWORD:       type = SDL_TEXTINPUT_TYPE_TEXT_PASSWORD_HIDDEN;  break;
    case RCI_KEYBOARD_SHOWN_PASSWORD: type = SDL_TEXTINPUT_TYPE_TEXT_PASSWORD_VISIBLE; break;
    case RCI_KEYBOARD_EMAIL:          type = SDL_TEXTINPUT_TYPE_TEXT_EMAIL;            break;
    case RCI_KEYBOARD_USERNAME:       type = SDL_TEXTINPUT_TYPE_TEXT_USERNAME;         break;
    case RCI_KEYBOARD_NUMBER:
    case RCI_KEYBOARD_DECIMAL:
    case RCI_KEYBOARD_ONE_TIME_CODE:  type = SDL_TEXTINPUT_TYPE_NUMBER;                break;
    case RCI_KEYBOARD_URL:
    case RCI_KEYBOARD_TEL:            type = SDL_TEXTINPUT_TYPE_TEXT;                  break;
    default:                          return SDL_StartTextInput(s->window);
    }
    props = SDL_CreateProperties();
    if (!props)
        return false;
    SDL_SetNumberProperty(props, SDL_PROP_TEXTINPUT_TYPE_NUMBER, type);
    SDL_SetNumberProperty(props, SDL_PROP_TEXTINPUT_CAPITALIZATION_NUMBER, SDL_CAPITALIZE_NONE);
    SDL_SetBooleanProperty(props, SDL_PROP_TEXTINPUT_AUTOCORRECT_BOOLEAN, false);
    SDL_SetBooleanProperty(props, SDL_PROP_TEXTINPUT_MULTILINE_BOOLEAN, false);

    if (keyboard == RCI_KEYBOARD_URL || keyboard == RCI_KEYBOARD_TEL ||
        keyboard == RCI_KEYBOARD_DECIMAL)
        SDL_SetNumberProperty(props, SDL_PROP_TEXTINPUT_ANDROID_INPUTTYPE_NUMBER,
                              keyboard == RCI_KEYBOARD_URL ? RCI_WINDOW_SDL_ANDROID_URI_INPUT
                              : keyboard == RCI_KEYBOARD_TEL ? RCI_WINDOW_SDL_ANDROID_PHONE_INPUT
                                                             : RCI_WINDOW_SDL_ANDROID_DECIMAL_INPUT);
    started = SDL_StartTextInputWithProperties(s->window, props);
    SDL_DestroyProperties(props);
#ifdef SDL_PLATFORM_IOS
    if (started)
        rci_window_sdl_ios_keyboard_type(s, keyboard);
#endif
    return started;
}

bool rci_window_soft_keyboard(bool visible, RCI_KeyboardKind keyboard) {
    RCI_WindowSdlRecord *s = rci_window_sdl_current();

    if (!s)
        return false;
    if (!SDL_HasScreenKeyboardSupport()) {

        RCI_LOG_WARN_ONCE("rcSetSoftKeyboardVisible: this target has no on-screen "
                          "keyboard the app can raise (only Android, iOS and a browser "
                          "with a focused text field have one). The call is a no-op "
                          "here.");

        return !visible;
    }
#ifdef SDL_PLATFORM_IOS

    if (visible) {

        if (!s->input.character || s->close || s->background ||
            SDL_GetAtomicInt(&rci_window_sdl_suspended))
            return false;
        if (SDL_TextInputActive(s->window) && s->kb_keyboard == keyboard) {
            s->kbRefusalLogged = false;
            return true;
        }

        if (!rci_window_sdl_start_text(s, keyboard)) {

            if (!s->kbRefusalLogged) {
                s->kbRefusalLogged = true;
                rci_window_sdl_error("show keyboard");
            }
            return false;
        }
        s->kb_keyboard = keyboard;
        s->kbRefusalLogged = false;
        return true;
    }
    rci_window_sdl_ios_lower(s->window);
    return true;
#else
#ifdef SDL_PLATFORM_ANDROID

    if (visible && rci_window_sdl_android_lowering)
        rci_window_sdl_keyboard_restart = true;
#endif
    if (visible && SDL_ScreenKeyboardShown(s->window)) {
#ifdef SDL_PLATFORM_ANDROID

        if (rci_window_sdl_keyboard_restart)
            return false;
        if (s->kb_keyboard != keyboard) {
            rci_window_sdl_keyboard_restart = true;
            SDL_StopTextInput(s->window);
            return false;
        }
#endif
        s->kbRefusalLogged = false;
        return true;
    }
#ifdef SDL_PLATFORM_ANDROID

    if (visible && s->kb_raised && s->kb_keyboard != keyboard)
        return false;
#endif
    SDL_SetHintWithPriority(SDL_HINT_ENABLE_SCREEN_KEYBOARD, "1", SDL_HINT_OVERRIDE);
    if (visible) {
        if (!rci_window_sdl_start_text(s, keyboard)) {

            if (!s->kbRefusalLogged) {
                s->kbRefusalLogged = true;
                rci_window_sdl_error("show keyboard");
            }
            return false;
        }
        s->kb_keyboard = keyboard;
        s->kb_raised = true;
        s->kbRefusalLogged = false;
        return true;
    } else {
        s->kb_raised = false;
#ifdef SDL_PLATFORM_ANDROID
        if (SDL_ScreenKeyboardShown(s->window))
            rci_window_sdl_android_lowering = true;
#endif
        SDL_StopTextInput(s->window);
        SDL_SetHintWithPriority(SDL_HINT_ENABLE_SCREEN_KEYBOARD, "0", SDL_HINT_OVERRIDE);
        if (s->input.character && !SDL_StartTextInput(s->window))
            rci_window_sdl_error("resume hardware text input");
    }
    return true;
#endif
}

