static RCI_WindowGlfwRecord *rci_window_glfw_record(GLFWwindow *gw) {
    return gw ? (RCI_WindowGlfwRecord *)glfwGetWindowUserPointer(gw) : NULL;
}

static void rci_window_glfw_facts_stale(GLFWwindow *gw) {
    for (RCI_WindowGlfwRecord *s = rci_window_glfw_records; s; s = s->next)
        if (!gw || s->window == gw)
            s->facts.read = s->facts.kept = false;
}

static void rci_window_glfw_size_moved(GLFWwindow *gw, int width, int height) {
    (void)width; (void)height;
    rci_window_glfw_facts_stale(gw);
#if defined(__APPLE__) && !RCI_PLATFORM_MOBILE
    rci_window_glfw_resize_step(gw);
#endif
}
static void rci_window_glfw_state_moved(GLFWwindow *gw, int on) {
    (void)on;
    rci_window_glfw_facts_stale(gw);
}

