static void rci_window_glfw_scale_moved(GLFWwindow *gw, float xscale, float yscale) {
    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(gw);

    (void)xscale; (void)yscale;
    rci_window_glfw_facts_stale(gw);
    if (rec) {
        rci_window_glfw_limits(gw, rec);
        rec->cursorShapeSet = false;
    }
#if defined(_WIN32)
    rci_window_glfw_keep_logical(gw, rec);
#endif
    rci_window_glfw_scale_changed = true;
}
