RCI_STATIC_ASSERT(sizeof(GLFWglproc) == sizeof(void *), "a GL entry point must fit a void *");
void *rci_window_gl_proc(const char *name) {
    GLFWglproc proc = glfwGetProcAddress(name);
    void *object;

    memcpy(&object, &proc, sizeof object);
    return object;
}
