void rci_window_ime_rect(float x, float y, float width, float height) {
#if RCI_WINDOW_GLFW_PREEDIT
    GLFWwindow  *gw = rci_window_glfw_selected();
    double       scale;

    if (!gw || !rci_isfinite_d(x) || !rci_isfinite_d(y) || !rci_isfinite_d(width) ||
        !rci_isfinite_d(height) ||
        width < 0.0f || height < 0.0f)
        return;
    scale = rci_window_glfw_scale(gw);
    glfwSetPreeditCursorRectangle(gw, (int)floor(x * scale), (int)floor(y * scale),
                                  (int)ceil(width * scale), (int)ceil(height * scale));
#elif RCI_WINDOW_IME_WIN32

    GLFWwindow           *gw  = rci_window_glfw_selected();
    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(gw);
    double                scale;
    int                   r[4];

    if (!rci_window_glfw_ime || !rec || !rci_isfinite_d(x) || !rci_isfinite_d(y) ||
        !rci_isfinite_d(width) || !rci_isfinite_d(height) || width < 0.0f || height < 0.0f)
        return;
    scale = rci_window_glfw_scale(gw);
    r[0] = (int)floor(x * scale);
    r[1] = (int)floor(y * scale);
    r[2] = (int)ceil(width * scale);
    r[3] = (int)ceil(height * scale);
    r[2] += !r[2];
    if (!memcmp(r, rec->imeArea, sizeof r))
        return;
    memcpy(rec->imeArea, r, sizeof r);
    rci_window_glfw_ime->area(glfwGetWin32Window(gw), r[0], r[1], r[2], r[3]);
#else
    (void)x;
    (void)y;
    (void)width;
    (void)height;
#endif
}

#if RCI_WINDOW_HAS_IME_SESSION
void rci_window_ime_session(int keyboard);
void rci_window_ime_session(int keyboard) {
#if RCI_WINDOW_GLFW_PREEDIT
    GLFWwindow *gw = rci_window_glfw_selected();

    if (!gw || !rci_window_glfw_record(gw))
        return;
    glfwResetPreeditText(gw);
    glfwSetTextInputFocus(gw, keyboard >= 0 && keyboard != RCI_KEYBOARD_PASSWORD &&
                              keyboard != RCI_KEYBOARD_SHOWN_PASSWORD);
#elif RCI_WINDOW_IME_WIN32
    GLFWwindow           *gw  = rci_window_glfw_selected();
    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(gw);

    if (!rci_window_glfw_ime || !rec)
        return;
    rci_window_glfw_ime->attach(glfwGetWin32Window(gw), keyboard);
    rci_window_glfw_ime_end(rec, false);
    rec->imeArea[2] = 0;
#else
    (void)keyboard;
#endif
}
#endif

