bool rci_window_keep_screen_on(bool on) {
    rci_window_glfw_keep = rci_window_keep_screen_on;
    if (on == rci_window_glfw_keep_on)
        return true;
    if (!SetThreadExecutionState(on ? ES_CONTINUOUS | ES_DISPLAY_REQUIRED : ES_CONTINUOUS))
        return false;
    rci_window_glfw_keep_on = on;
    return true;
}
