static GLFWcursor *rci_window_glfw_hand(GLFWwindow *gw, bool closed) {
    const int platform = glfwGetPlatform();
    float sx = 1.0f, sy = 1.0f;
    int scale = 1;
    GLFWcursor **slot;
    GLFWimage image;

    if (platform == GLFW_PLATFORM_WIN32 || platform == GLFW_PLATFORM_X11) {
        glfwGetWindowContentScale(gw, &sx, &sy);
        scale = rci_window_hand_scale(sx);
    }
    slot = &rci_window_glfw_cursor_hand[closed][scale - 1];
    if (*slot)
        return *slot;
    image.width = image.height = RCI_WINDOW_HAND_SIZE * scale;
    image.pixels = malloc((size_t)image.width * (size_t)image.height * 4);
    if (image.pixels) {
        rci_window_hand_rgba(closed, scale, image.pixels, image.width * 4);
        *slot = glfwCreateCursor(&image, RCI_WINDOW_HAND_SIZE / 2 * scale,
                                 RCI_WINDOW_HAND_SIZE / 2 * scale);
        free(image.pixels);
    }
    return *slot;
}

void rci_window_set_cursor(RCI_Window *w, RCI_WindowCursor shape) {

    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(rci_window_glfw_gw(w));
    if (rec) {
        if (rec->cursorShapeSet && shape == rec->cursor_shape)
            return;
        rec->cursor_shape     = shape;
        rec->cursorShapeSet = true;
    }
    if (!rci_window_glfw_cursors_made) {
        rci_window_glfw_cursor_ew      = glfwCreateStandardCursor(GLFW_RESIZE_EW_CURSOR);
        rci_window_glfw_cursor_ns      = glfwCreateStandardCursor(GLFW_RESIZE_NS_CURSOR);
        rci_window_glfw_cursor_nesw    = glfwCreateStandardCursor(GLFW_RESIZE_NESW_CURSOR);
        rci_window_glfw_cursor_nwse    = glfwCreateStandardCursor(GLFW_RESIZE_NWSE_CURSOR);
        rci_window_glfw_cursor_pointer = glfwCreateStandardCursor(GLFW_POINTING_HAND_CURSOR);
        rci_window_glfw_cursor_ibeam   = glfwCreateStandardCursor(GLFW_IBEAM_CURSOR);
        rci_window_glfw_cursor_no      = glfwCreateStandardCursor(GLFW_NOT_ALLOWED_CURSOR);
        rci_window_glfw_cursor_cross   = glfwCreateStandardCursor(GLFW_CROSSHAIR_CURSOR);
        rci_window_glfw_cursors_made   = true;
    }

    GLFWcursor *c = NULL;
    switch (shape) {
    case RCI_WINDOW_CURSOR_ARROW:
    case RCI_WINDOW_CURSOR_COUNT:       break;
    case RCI_WINDOW_CURSOR_RESIZE_EW:   c = rci_window_glfw_cursor_ew;      break;
    case RCI_WINDOW_CURSOR_RESIZE_NS:   c = rci_window_glfw_cursor_ns;      break;
    case RCI_WINDOW_CURSOR_RESIZE_NESW: c = rci_window_glfw_cursor_nesw;    break;
    case RCI_WINDOW_CURSOR_RESIZE_NWSE: c = rci_window_glfw_cursor_nwse;    break;
    case RCI_WINDOW_CURSOR_POINTER:     c = rci_window_glfw_cursor_pointer; break;
    case RCI_WINDOW_CURSOR_IBEAM:       c = rci_window_glfw_cursor_ibeam;   break;
    case RCI_WINDOW_CURSOR_GRAB:
    case RCI_WINDOW_CURSOR_GRABBING:
        c = rci_window_glfw_hand(rci_window_glfw_gw(w), shape == RCI_WINDOW_CURSOR_GRABBING);
        break;
    case RCI_WINDOW_CURSOR_NOT_ALLOWED: c = rci_window_glfw_cursor_no;      break;
    case RCI_WINDOW_CURSOR_CROSSHAIR:   c = rci_window_glfw_cursor_cross;   break;
    }
    glfwSetCursor(rci_window_glfw_gw(w), c);
}

RCI_STATIC_ASSERT(RC_POINTER_LEFT   == GLFW_MOUSE_BUTTON_LEFT  &&
                  RC_POINTER_RIGHT  == GLFW_MOUSE_BUTTON_RIGHT &&
                  RC_POINTER_MIDDLE == GLFW_MOUSE_BUTTON_MIDDLE,
                  "RC_PointerButton must stay numbered like GLFW's mouse buttons");

RCI_STATIC_ASSERT(GLFW_KEY_LAST < RCI_WINDOW_KEY_CODE_LIMIT,
                  "GLFW key codes must fit under the seam's key-code ceiling");
RCI_STATIC_ASSERT(GLFW_KEY_UNKNOWN == RCI_WINDOW_KEY_CODE_NONE,
                  "the key trampoline hands GLFW_KEY_UNKNOWN through as the seam's no-code value");
RCI_STATIC_ASSERT(RCI_WINDOW_KEY_ACTION_RELEASE == GLFW_RELEASE &&
                  RCI_WINDOW_KEY_ACTION_PRESS   == GLFW_PRESS   &&
                  RCI_WINDOW_KEY_ACTION_REPEAT  == GLFW_REPEAT,
                  "the seam's key actions are handed GLFW's through unchanged");
RCI_STATIC_ASSERT(GLFW_MOD_SHIFT   == RCI_WINDOW_MOD_SHIFT &&
                  GLFW_MOD_CONTROL == RCI_WINDOW_MOD_CTRL  &&
                  GLFW_MOD_ALT     == RCI_WINDOW_MOD_ALT   &&
                  GLFW_MOD_SUPER   == RCI_WINDOW_MOD_SUPER,
                  "GLFW's modifier bits are handed through unmasked but for the locks");

static unsigned rci_window_glfw_mods(int mods) {
    return (unsigned)mods & 0xFu;
}

static void rci_window_glfw_key_trampoline(GLFWwindow *gw, int key, int scancode, int action, int mods) {
    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(gw);
    (void)scancode;
    if (rec && rec->input.key)
        rec->input.key((RCI_Window *)gw, key, (RCI_WindowKeyAction)action,
                       rci_window_glfw_mods(mods));
}
static void rci_window_glfw_char_trampoline(GLFWwindow *gw, unsigned int codepoint) {
    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(gw);
    if (rec && rec->input.character)
        rec->input.character((RCI_Window *)gw, codepoint);
}
static void rci_window_glfw_mouse_button_trampoline(GLFWwindow *gw, int button, int action, int mods) {
    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(gw);

    if (button < GLFW_MOUSE_BUTTON_LEFT || button > GLFW_MOUSE_BUTTON_MIDDLE)
        return;
    if (rec && rec->input.mouse_button)
        rec->input.mouse_button((RCI_Window *)gw, (RC_PointerButton)button, action == GLFW_PRESS,
                                rci_window_glfw_mods(mods));
}
static void rci_window_glfw_scroll_trampoline(GLFWwindow *gw, double dx, double dy) {
    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(gw);
    if (rec && rec->input.scroll)
        rec->input.scroll((RCI_Window *)gw, dx, dy);
}

static void rci_window_glfw_cursor_pos_trampoline(GLFWwindow *gw, double x, double y) {
    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(gw);
    if (rec && rec->input.cursor_pos) {
        const double scale = rci_window_glfw_scale(gw);

        rec->input.cursor_pos((RCI_Window *)gw, x / scale, y / scale);
    }
}
static void rci_window_glfw_cursor_enter_trampoline(GLFWwindow *gw, int entered) {
    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(gw);
    if (rec && rec->input.cursor_enter) {
#if RCI_WINDOW_GLFW_PLATFORM_CHOICE
        rec->pointerOut = false;
#endif
        rec->input.cursor_enter((RCI_Window *)gw, entered == GLFW_TRUE);
    }
}

static void rci_window_glfw_drop_trampoline(GLFWwindow *gw, int count, const char **paths) {
    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(gw);
    if (rec && rec->input.drop && count > 0 && paths)
        rec->input.drop((RCI_Window *)gw, count, paths);
}
#if defined(RC_GLFW_DRAG) && RC_GLFW_DRAG

static void rci_window_glfw_drag_trampoline(GLFWwindow *gw, int over, double x, double y) {
    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(gw);
    if (rec && rec->input.drag) {
        const double scale = rci_window_glfw_scale(gw);

        rec->input.drag((RCI_Window *)gw, over != 0, x / scale, y / scale);
    }
}
#endif

#if RCI_WINDOW_GLFW_PREEDIT

static void rci_window_glfw_preedit_trampoline(GLFWwindow *gw, int count, unsigned int *text,
                                               int blocks, int *sizes, int focused, int caret) {
    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(gw);
    int at = 0, start = caret, length = 0;

    if (!rec || !rec->input.editing)
        return;
    if (count < 0 || !text)
        count = 0;
    if (count * 4 + 1 > rci_window_glfw_compose_cap) {
        char *grown = (char *)realloc(rci_window_glfw_compose_utf8, (size_t)count * 4u + 1u);

        if (!grown)
            return;
        rci_window_glfw_compose_utf8 = grown;
        rci_window_glfw_compose_cap  = count * 4 + 1;
    }
    for (int i = 0; i < count; i++) {
        const unsigned int c = text[i];

        if (c < 0x80u) {
            rci_window_glfw_compose_utf8[at++] = (char)c;
        } else if (c < 0x800u) {
            rci_window_glfw_compose_utf8[at++] = (char)(0xC0u | c >> 6);
            rci_window_glfw_compose_utf8[at++] = (char)(0x80u | (c & 0x3Fu));
        } else if (c < 0x10000u) {
            rci_window_glfw_compose_utf8[at++] = (char)(0xE0u | c >> 12);
            rci_window_glfw_compose_utf8[at++] = (char)(0x80u | (c >> 6 & 0x3Fu));
            rci_window_glfw_compose_utf8[at++] = (char)(0x80u | (c & 0x3Fu));
        } else if (c < 0x110000u) {
            rci_window_glfw_compose_utf8[at++] = (char)(0xF0u | c >> 18);
            rci_window_glfw_compose_utf8[at++] = (char)(0x80u | (c >> 12 & 0x3Fu));
            rci_window_glfw_compose_utf8[at++] = (char)(0x80u | (c >> 6 & 0x3Fu));
            rci_window_glfw_compose_utf8[at++] = (char)(0x80u | (c & 0x3Fu));
        }
    }
    if (rci_window_glfw_compose_utf8)
        rci_window_glfw_compose_utf8[at] = '\0';
    if (blocks > 1 && sizes && focused >= 0 && focused < blocks) {
        start = 0;
        for (int i = 0; i < focused; i++)
            start += sizes[i];
        length = sizes[focused];
    }
    rec->input.editing((RCI_Window *)gw, count > 0 ? rci_window_glfw_compose_utf8 : "",
                       start, length);
}

static void rci_window_glfw_commit_trampoline(GLFWwindow *gw, const char *utf8) {
    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(gw);

    if (rec && rec->input.text && utf8)
        rec->input.text((RCI_Window *)gw, utf8);
}

#endif

