static void rci_window_glfw_client_cursor(RCI_Window *w, double x, double y) {
    rci_window_glfw_cursor_pos_trampoline((GLFWwindow *)w, x, y);
}
static void rci_window_glfw_client_drag(RCI_Window *w, bool over, double x, double y) {
    RCI_WindowGlfwRecord *rec = rci_window_glfw_record((GLFWwindow *)w);
    const double scale = rci_window_glfw_scale((GLFWwindow *)w);

    if (rec && rec->input.drag)
        rec->input.drag(w, over, x / scale, y / scale);
}
