#endif

#include <math.h>
#include <string.h>

static RCI_Sched *rci_sched_current;

void rci_sched_init(RCI_Sched *s) {
    if (!s) return;
    memset(s, 0, sizeof *s);
    s->deadline        = INFINITY;
    s->deadlineOneShot = INFINITY;
    s->pending         = RCI_SCHED_INITIAL;
}

void rci_sched_request(RCI_Sched *s, unsigned reasons) {
    if (!s || !reasons) return;

    if (reasons & ~s->pending) ++s->requests;
    s->pending |= reasons;
}

void rci_sched_request_at(RCI_Sched *s, double when) {

    if (!s || !rci_isfinite_d(when)) return;
    if (when < s->deadline) s->deadline = when;
}

void rci_sched_request_at_oneshot(RCI_Sched *s, double when) {
    if (!s || !rci_isfinite_d(when)) return;
    if (when < s->deadlineOneShot) s->deadlineOneShot = when;
}

void rci_sched_set_continuous(RCI_Sched *s, bool on) {
    if (!s) return;

    if (on && !s->continuousApp) rci_sched_request(s, RCI_SCHED_APP);
    s->continuousApp = on;
}

void rci_sched_lease_begin(RCI_Sched *s) {
    if (!s) return;
    if (s->continuousRefs == 0) rci_sched_request(s, RCI_SCHED_INTERNAL);
    ++s->continuousRefs;
}

void rci_sched_lease_end(RCI_Sched *s) {
    if (!s || s->continuousRefs <= 0) return;
    --s->continuousRefs;
}

bool rci_sched_is_continuous(const RCI_Sched *s) {
    return s && (s->continuousApp || s->continuousRefs > 0);
}

bool rci_sched_admit(RCI_Sched *s, double now) {
    if (!s) return false;

    bool oneShotDue = (now >= s->deadlineOneShot);
    bool due        = (now >= s->deadline) || oneShotDue;
    if (due) {
        s->pending |= RCI_SCHED_DEADLINE;
        ++s->deadlineWakes;
    }
    if (!s->pending && !rci_sched_is_continuous(s)) return false;

    for (int i = 0; i < 8; ++i)
        if (s->pending & (1u << i)) ++s->byReason[i];

    s->pending = 0;

    s->deadline = INFINITY;

    if (oneShotDue) s->deadlineOneShot = INFINITY;

    ++s->admitted;
    return true;
}

double rci_sched_timeout(const RCI_Sched *s, double now) {
    if (!s) return 0.0;
    if (s->pending || rci_sched_is_continuous(s)) return 0.0;

    double next = fmin(s->deadline, s->deadlineOneShot);
    if (!rci_isfinite_d(next)) return INFINITY;
    double dt = next - now;
    return (dt > 0.0) ? dt : 0.0;
}

bool rci_sched_deadline_due(const RCI_Sched *s, double now) {

    return s && ((now >= s->deadline) || (now >= s->deadlineOneShot));
}

void rci_sched_note_spurious(RCI_Sched *s) {
    if (s) ++s->spuriousWakes;
}

void rci_sched_set_current(RCI_Sched *s) { rci_sched_current = s; }
RCI_Sched *rci_sched_get_current(void)       { return rci_sched_current; }

void rci_sched_need_frame(void) {
    rci_sched_request(rci_sched_current, RCI_SCHED_INTERNAL);
}

void rci_sched_need_frame_for(unsigned reasons) {
    rci_sched_request(rci_sched_current, reasons);
}

void rci_sched_need_frame_at(double when) {
    rci_sched_request_at(rci_sched_current, when);
}

const char *rci_sched_reason_name(int i) {
    static const char *n[8] = { "initial", "input", "window", "expose",
                                "resource", "app", "deadline", "internal" };
    return (i >= 0 && i < 8) ? n[i] : "?";
}

