#ifndef RC_CLAY_GROW_H
#define RC_CLAY_GROW_H

#include <stdbool.h>
#include <stdint.h>

typedef struct {
    bool grow;
    int  next;
    bool atCeiling;
} RCI_ClayGrow;

static inline RCI_ClayGrow rci_clay_grow_decide(int cur, int64_t ceiling) {
    RCI_ClayGrow d = { false, 0, false };
    if ((int64_t)cur >= ceiling) {
        d.atCeiling = true;
        return d;
    }
    int64_t next = (int64_t)cur * 2;
    if (next > ceiling) next = ceiling;
    d.grow = true;
    d.next = (int)next;
    return d;
}

static inline int rci_clay_grow_fit(int cur, int64_t declared, int64_t ceiling) {
    while ((int64_t)cur <= declared) {
        RCI_ClayGrow d = rci_clay_grow_decide(cur, ceiling);
        if (!d.grow) break;
        cur = d.next;
    }
    return cur;
}

typedef struct {
    int elements;
    int words;
} RCI_ClayCounts;

static inline RCI_ClayCounts rci_clay_grow_couple_counts(int elements, int words) {
    if (words < 32) words = 32;
    int divisor = words / 32;
    if (elements < divisor) elements = divisor;
    int64_t pair = 2 * (int64_t)elements;
    if (pair > INT32_MAX) pair = INT32_MAX;
    if (words < pair) words = (int)pair;
    RCI_ClayCounts c = { elements, words };
    return c;
}

#endif

