static RCI_WindowDesc rci_app_window_desc(void *owner, int width, int height,
                                        const char *title) {

    bool decorated = true, frame_folds = false;
#if defined(__APPLE__)
    frame_folds = rci_app_chrome->own_titlebar;
#else
    if (rci_app_chrome->own_titlebar) decorated = false;
#endif

    RCI_WindowDesc desc = {
        .width     = width  > 0 ? width  : 1024,
        .height    = height > 0 ? height : 768,
        .title     = title ? title : "RayClay",
        .gl_major  = 4,
        .gl_minor  = 1,

        .samples   = rci_gfx_msaa_samples(),
        .resizable = true,
        .decorated = decorated,
        .frameFolds = frame_folds,
        .user      = owner,
        .chrome_scheme = rci_app_chrome->scheme,
    };
#if RCI_APP_WINDOW_BACKGROUND
    desc.background = rci_app_window_background(owner);
#endif
#if !defined(RC_NO_APP_RUNNER) && !defined(RC_NO_LIVE_RESIZE)
    if (owner)
        desc.modal_frame = rci_app_on_modal_frame;
#endif
#if !defined(RC_NO_APP_RUNNER) && defined(_WIN32)
    if (owner)
        desc.session_end = rci_app_on_session_end;
#endif
#if defined(__EMSCRIPTEN__) || RCI_PLATFORM_MOBILE
    desc.gl_major = 3;
    desc.gl_minor = 0;
#endif

    int floorW  = rci_app_chrome->chips > 0
                     ? RCI_CONTROLS_MIN_W_N(rci_app_chrome->chips)
                     : RCI_CONTROLS_MIN_W;
    int floorH = rci_app_chrome->caption_height > 0 ? rci_app_chrome->caption_height : (int)RCI_TITLEBAR_H;

    int minW = rci_app_chrome->min_width > 0 ? rci_app_chrome->min_width : floorW;
    int minH = rci_app_chrome->min_height > 0 ? rci_app_chrome->min_height : floorH;

    if (rci_app_chrome->own_titlebar && !rci_app_chrome->allow_controls_clip && rci_app_chrome->chips > 0) {
        if (rci_app_chrome->min_width > 0 && minW < floorW) {
            rci_base_log(RC_LOG_WARNING, "RC_AppOptions.minWidth %d raised to %d: the "
                    "window controls would not fit. Set titlebar.allowControlsClip "
                    "to keep your value.", minW, floorW);
            minW = floorW;
        }

        if (rci_app_chrome->min_height > 0 && minH < floorH) {
            rci_base_log(RC_LOG_WARNING, "RC_AppOptions.minHeight %d raised to %d: the "
                    "title bar would not fit. Set titlebar.allowControlsClip to "
                    "keep your value.", minH, floorH);
            minH = floorH;
        }
    }
    rci_app_chrome->min_width = rci_app_chrome->min_height = 0;
    desc.min_width  = minW;
    desc.min_height = minH;
#ifndef RC_NO_APP_RUNNER
    if (owner)
        rci_app_window_keep_min(owner, minW, minH);
#endif
    if (desc.width  < minW) desc.width  = minW;
    if (desc.height < minH) desc.height = minH;
    return desc;
}

static bool rci_app_open_window(void *owner, int width, int height, const char *title) {
    if (rci_app_window) {
        rci_base_log(RC_LOG_WARNING, "rcAppCreate: a window already exists");
        return false;
    }

#if RCI_WINDOW_HAS_OWN_DECORATIONS_HINT

    void rci_window_hint_own_decorations(bool own);

    rci_window_hint_own_decorations(rci_app_chrome->own_titlebar);
#endif
    if (!rci_window_system_init()) {
        rci_base_log(RC_LOG_ERROR, "rcAppCreate: window-system init failed");
        return false;
    }

    RCI_PHASE_MARK(RCI_PHASE_SYSINIT);

    RCI_WindowDesc desc = rci_app_window_desc(owner, width, height, title);
    desc.orientation = rci_app_chrome->orientation;
    desc.status_bar  = rci_app_chrome->status_bar;
    rci_app_chrome->statusIcons  = RCI_STATUS_BAR_AUTO_SYSTEM;
    rci_app_chrome->statusAnswer = -1;
    rci_app_chrome->nav_icons     = -1;
    rci_app_window = rci_app_create_native(&desc, false);
    if (rci_app_window) {
        rci_app_torn_down = false;
    }
    if (!rci_app_window) {
        rci_base_log(RC_LOG_ERROR, "rcAppCreate: window creation failed (the renderer "
                     "needs " RCI_APP_GL_NEED ")");
        rci_window_system_shutdown();
        return false;
    }

    rci_window_make_current(rci_app_window);
    rci_window_swap_interval(1);
    RCI_PHASE_MARK(RCI_PHASE_WINDOW);

    RCI_APP_POOLED(rci_gfx_init(rci_window_gl_proc));
    if (!rci_gfx_ready()) {

        rci_base_log(RC_LOG_ERROR, "rcAppCreate: render backend init failed");
        rci_base_defer_release();
    RCI_APP_POOLED(rci_gfx_shutdown());
        rci_window_destroy(rci_app_window);
        rci_app_window = NULL;
        rci_window_system_shutdown();
        return false;
    }

    RCI_PHASE_MARK(RCI_PHASE_GFX);
    rci_input_init(rci_app_window);
    rci_api_pointer_class_init();
    rci_font_init();
    RCI_PHASE_MARK(RCI_PHASE_FONT_INIT);

#if !defined(__EMSCRIPTEN__) && !RCI_PLATFORM_MOBILE
    rci_app_attach_chrome(rci_app_window, rci_app_chrome, RCI_CAPTION_HIT, owner, "rcAppCreate");
#endif
    return true;
}

struct RCI_Window *rci_app_bound_native(void) { return rci_app_window; }

void rci_app_init_window(int width, int height, const char *title) {
    if (!rci_app_window)
        rci_app_chrome_use(&rci_app_chrome_fallback);
    (void)rci_app_open_window(NULL, width, height, title);
}

void rci_app_close_window(void) {
#ifndef RC_NO_APP_RUNNER
    if (!rci_app_prepare_close())
        return;
#endif

    if (rci_app_pump_depth > 0) {
#ifndef RC_NO_APP_RUNNER
        rci_app_close_deferred = rci_app_window;
#endif
        return;
    }

    if (rci_app_torn_down) {
        return;
    }
    rci_app_torn_down = true;

    if (rci_app_window) {
        rci_window_make_current(rci_app_window);
        rci_window_prepare_teardown();
#if defined(_WIN32) && !defined(RC_WINDOW_BACKEND_SDL3)

        if (rci_core_dragover_window_closing)
            rci_core_dragover_window_closing(rci_app_window);
#endif
    }
    rci_font_shutdown();
#if RC_COLOR_EMOJI
    rci_emoji_shutdown();
#endif
    rci_text_shutdown();
    rci_textedit_textinput_shutdown();
    rci_api_clipboard_shutdown();
    rci_api_icon_pool_shutdown();
    rci_app_net_shutdown();
    rci_api_run_teardowns();
    rci_widgets_shutdown();
    rci_interact_intent_shutdown();
    rci_api_scroll_consumed_set(false);
    rci_input_shutdown();
    rci_base_defer_release();
    RCI_APP_POOLED(rci_gfx_shutdown());

    if (rci_app_window) {

        rci_window_set_refresh_callback(rci_app_window, NULL);
        rci_titlebar_detach();
        rci_window_destroy(rci_app_window);
        rci_app_window = NULL;

#ifndef RC_NO_APP_RUNNER
        rci_app_close_deferred = NULL;
#endif
    }

    rci_app_chrome->own_titlebar   = false;
    rci_app_chrome->bundled_band   = false;
    rci_app_chrome->caption_height      = 0;
    rci_app_chrome->allow_controls_clip = false;
    rci_app_chrome->chips     = 0;
    rci_app_chrome->scheme    = 0;

    rci_window_set_managed_loop(false);
    rci_window_system_shutdown();
    rci_image_release_kept();
    rci_app_forget_app_icon();
#ifndef RC_NO_APP_RUNNER
    rci_app_note_closed();
#endif
}

static CLAY_Dimensions rci_app_dimensions(const RCI_AppWindowFacts *facts) {
    int w = 0, h = 0;

    rci_app_size(facts, rci_app_window, &w, &h);
    if (w > 0 && h > 0)
        return (CLAY_Dimensions){ (float)w, (float)h };
    return (CLAY_Dimensions){ 1.0f, 1.0f };
}

static CLAY_Dimensions rci_app_bound_dimensions(void) {
    return rci_app_dimensions(rci_app_frame_facts());
}

#ifndef RC_NO_APP_RUNNER

static float rci_app_bound_scale(void) {
    const RCI_AppWindowFacts *facts = rci_app_frame_facts();
    int fbw = 0, fbh = 0, lw = 0, lh = 0;

    rci_app_fb_size(facts, rci_app_window, &fbw, &fbh);
    rci_app_size(facts, rci_app_window, &lw, &lh);
    if (lw > 0 && fbw > 0)
        return (float)fbw / (float)lw;
    return 1.0f;
}
#endif

static CLAY_Dimensions rci_app_viewport_dimensions(float z) {
    CLAY_Dimensions d = rci_app_bound_dimensions();
    if (z <= 0.0f) z = 1.0f;

    d.width  = rci_zoom_math_axis_floor(d.width,  z);
    d.height = rci_zoom_math_axis_floor(d.height, z);
    if (d.width  < 1.0f) d.width  = 1.0f;
    if (d.height < 1.0f) d.height = 1.0f;
    return d;
}

static CLAY_Dimensions rci_app_render_dimensions(void) {
    return rci_app_viewport_dimensions(rci_api_zoom_get());
}

static CLAY_Dimensions rci_app_layout_dimensions(void) {
    if (!rci_api_zoom_optical_get()) {

        CLAY_Dimensions r = rci_app_render_dimensions();

        if (r.width  < 1.0f) r.width  = 1.0f;
        if (r.height < 1.0f) r.height = 1.0f;
        return r;
    }

    CLAY_Dimensions win  = rci_app_bound_dimensions();
    CLAY_Dimensions view = rci_app_viewport_dimensions(rci_api_zoom_get());
    CLAY_Dimensions d    = {0};
    d.width  = (float)(int)(win.width  > view.width  ? win.width  : view.width);
    d.height = (float)(int)(win.height > view.height ? win.height : view.height);
    if (d.width  < 1.0f) d.width  = 1.0f;
    if (d.height < 1.0f) d.height = 1.0f;
    return d;
}

RC_Viewport rcViewport(void) {
    CLAY_Dimensions layout = rci_app_layout_dimensions();
    CLAY_Dimensions win    = rci_app_bound_dimensions();
    RC_Insets       safe   = rcGetSafeAreaInsets();

    RC_Viewport     v      = {0};

    v.width  = layout.width;
    v.height = layout.height;

    v.safe = rci_viewport_math_safe_to_layout(safe, layout.width, layout.height,
                                         win.width, win.height);
    v.breakpoint    = rci_viewport_math_breakpoint(v.width);
    v.coarsePointer = rcPointerIsCoarse();

    v.keyboard = rci_viewport_math_safe_to_layout(rcGetKeyboardInsets(), layout.width,
                                             layout.height, win.width, win.height);
    return v;
}

