bool rcSetStatusBar(RC_StatusBar style) {
    int sent = (int)style;
    bool took;

    if ((unsigned)style > (unsigned)RC_STATUS_BAR_HIDDEN) {
        RCI_LOG_WARN_ONCE("rcSetStatusBar: %d is not an RC_StatusBar; nothing changed",
                          (int)style);
        return false;
    }
    if (!rci_app_window)
        return false;
#if RCI_WINDOW_HAS_STATUS_BAR

    if (style == RC_STATUS_BAR_AUTO && rci_app_chrome->status_bar == RC_STATUS_BAR_AUTO &&
        rci_app_chrome->statusAnswer >= 0)
        return rci_app_chrome->statusAnswer != 0;
    rci_app_chrome->statusIcons = RCI_STATUS_BAR_AUTO_SYSTEM;
    if (style == RC_STATUS_BAR_AUTO && rci_app_bound_window) {
        sent = rci_app_status_bar_guess(rci_app_bound_window);
        rci_app_chrome->statusIcons = sent;
        rcWindowRequestFrame(rci_app_bound_window);
    }
#endif
#if RCI_APP_NAVIGATION_BAR

    if ((int)style != rci_app_chrome->status_bar && rci_app_bound_window)
        rcWindowRequestFrame(rci_app_bound_window);
#endif
    rci_app_chrome->status_bar = (int)style;
    took = rci_window_set_status_bar(rci_app_window, sent);
    rci_app_chrome->statusAnswer = took;
    return took;
}

