static void rci_app_ui_contexts_destroy(struct RC_Window *window) {
    rci_core_context_destroy(window->core);
    rci_titlebar_context_destroy(window->titlebar);

    rci_text_sel_window_gone(window->input);
    rci_input_context_destroy(window->input);
    rci_widgets_context_destroy(window->widgets);
    rci_textedit_context_destroy(window->textedit);
    rci_focus_context_destroy(window->focus);
    rci_interact_context_destroy(window->interact);
    window->widgets = NULL;
    window->core = NULL;
    window->textedit = NULL;
    window->focus = NULL;
    window->interact = NULL;
    window->input = NULL;
    window->titlebar = NULL;
    if (rci_app_chrome == &window->chrome)
        rci_app_chrome_use(&rci_app_chrome_fallback);
    if (rci_app_bound_window == window)
        rci_app_bound_window = NULL;
}

static bool rci_app_ui_contexts_create(struct RC_Window *window) {
    window->frameResizeEdge = -1;
#if !defined(NDEBUG) && !defined(__EMSCRIPTEN__) && !RCI_PLATFORM_MOBILE
    window->captionLastZoom = -1.0f;
#endif
    window->interact = rci_interact_context_create();
    window->textedit = rci_textedit_context_create();
    window->focus = rci_focus_context_create();
    window->widgets = rci_widgets_context_create();
    window->core = rci_core_context_create();
    window->input = rci_input_context_create();
    window->titlebar = rci_titlebar_context_create();
    if (!window->interact || !window->textedit || !window->focus || !window->widgets ||
        !window->core || !window->input || !window->titlebar) {
        rci_app_ui_contexts_destroy(window);
        return false;
    }
    return true;
}

static void rci_app_ui_contexts_bind(struct RC_Window *window) {
    rci_app_bound_window = window;
    rci_app_chrome_use(&window->chrome);
    rci_interact_context_bind(window->interact);
    rci_textedit_context_bind(window->textedit);
    rci_focus_context_bind(window->focus);
    rci_widgets_context_bind(window->widgets);
    rci_core_context_bind(window->core);
    rci_input_context_bind(window->input);
    rci_titlebar_context_bind(window->titlebar);
}

static void rci_app_mirror_publish(const RC_Window *window, CLAY_Dimensions win) {
    rci_api_mirror_set((window->committedMirror & RC_MIRROR_HORIZONTAL) != 0,
                       (window->committedMirror & RC_MIRROR_VERTICAL) != 0,
                       win.width, win.height);
}

static void rci_app_window_state_bind(struct RC_Window *window) {
    rci_app_ui_contexts_bind(window);
    rci_app_window = window->native;
    claySetCurrentContext(window->clayCtx);
    rci_core_scroll_reg_set(&window->scrollReg);
    rci_sched_set_current(&window->sched);
    rci_api_zoom_set(window->committedZoom > 0.0f ? window->committedZoom : 1.0f);
    rci_api_zoom_optical_set(window->committedOptical);
    rci_text_set_line_grid(window->committedDensity, window->committedOptical);
    rci_api_pan_set(window->committedPanX, window->committedPanY);
    rci_api_viewport_set(window->committedWidth, window->committedHeight);
    {
        CLAY_Dimensions win = rci_app_dimensions(rci_app_facts_of(window));
        rci_app_mirror_publish(window, win);
        rci_api_overlay_publish(win.width, win.height,
                                window->committedWidth, window->committedHeight,
                                window->committedPanX, window->committedPanY);
    }
}

static void rci_app_restore_ui(RC_Window *window) {
    if (window) {
        rci_app_window_state_bind(window);
        return;
    }
    rci_app_bound_window = NULL;
    rci_app_chrome_use(&rci_app_chrome_fallback);
    rci_app_window = NULL;
    rci_interact_context_bind(NULL);
    rci_textedit_context_bind(NULL);
    rci_focus_context_bind(NULL);
    rci_widgets_context_bind(NULL);
    rci_core_context_bind(NULL);
    rci_input_context_bind(NULL);
    rci_titlebar_context_bind(NULL);
    claySetCurrentContext(NULL);
    rci_core_scroll_reg_set(NULL);
    rci_sched_set_current(NULL);
    rci_api_zoom_set(1.0f);
    rci_api_zoom_optical_set(false);
    rci_text_set_line_grid(1.0f, false);
    rci_api_pan_set(0.0f, 0.0f);
    rci_api_viewport_set(0.0f, 0.0f);
    rci_api_mirror_set(false, false, 0.0f, 0.0f);
    rci_api_overlay_clear();
}

static void rci_app_invalidate_measure_caches(void *user) {
    RC_App *app = user;
    CLAY_Context *previous = clayGetCurrentContext();
    uint32_t generation = rci_font_metrics_generation();

    for (RC_Window *window = &app->mainWindow; window; window = window->next) {
        if (!window->clayCtx)
            continue;
        claySetCurrentContext(window->clayCtx);
        clayResetMeasureTextCache();
        window->measureGeneration = generation;
        rci_sched_request(&window->sched, RCI_SCHED_RESOURCE);
    }
    claySetCurrentContext(previous);
}

static bool rci_app_bind_graphics(RC_Window *window) {
    if (!window || !window->native || !window->gfx)
        return false;
    if (rci_app_gfx_window != window) {
        if (rci_app_gfx_window && !rci_gfx_context_release())
            return false;
        rci_app_gfx_window = NULL;
        rci_window_make_current(window->native);
        if (!rci_window_is_current(window->native) ||
            !rci_gfx_context_bind(window->gfx))
            return false;
        rci_app_gfx_window = window;
    } else if (!rci_window_is_current(window->native)) {
        rci_window_make_current(window->native);
        if (!rci_window_is_current(window->native))
            return false;
    }
    return true;
}

static bool rci_app_bind_resting_graphics(RC_App *app) {
    return rci_app_bind_graphics(rci_app_gfx_window ? rci_app_gfx_window
                                                    : &app->mainWindow);
}

static void rci_app_dispatch_frame(RC_Window *window, int phase) {
    RC_Window *previous = rci_app_callback_window;

    rci_app_callback_window = window;
    rci_app_callback_depth++;
    if (window == &window->app->mainWindow) {
        if (phase == 0 && window->updateCallback)
            window->updateCallback(window->app, window->userData);
        else if (phase == 1 && window->layoutCallback)
            window->layoutCallback(window->app, window->userData);
        else if (phase == 2 && window->frameEndCallback)
            window->frameEndCallback(window->app, window->userData);
    } else {
        if (phase == 0 && window->childUpdate)
            window->childUpdate(window, window->userData);
        else if (phase == 1 && window->childLayout)
            window->childLayout(window, window->userData);
        else if (phase == 2 && window->childFrameEnd)
            window->childFrameEnd(window, window->userData);
    }
    rci_app_callback_depth--;
    rci_app_callback_window = previous;
}

