static void rci_app_pan_reclamp(RC_Window *window) {
    if (window->zoomOpts.mode != RC_ZOOM_OPTICAL) {
        window->panX = window->panY = 0.0f;
        return;
    }
    CLAY_Dimensions view    = rci_app_viewport_dimensions(window->zoom);
    CLAY_Dimensions content = rci_app_bound_dimensions();
    window->panX = rci_zoom_math_pan_clamp(window->panX, content.width,  view.width);
    window->panY = rci_zoom_math_pan_clamp(window->panY, content.height, view.height);
}

static void rci_app_zoom_apply(RC_Window *window, float zoom) {
    if (zoom == window->zoom) return;
    if (window->zoomOpts.mode == RC_ZOOM_OPTICAL) {

        float cx = (float)rci_api_content_raw_x(rci_input_mouse_x());
        float cy = (float)rci_api_content_raw_y(rci_input_mouse_y());
        window->panX = rci_zoom_math_pan_anchor(window->panX, cx, window->zoom, zoom);
        window->panY = rci_zoom_math_pan_anchor(window->panY, cy, window->zoom, zoom);
    }
    window->zoom = zoom;
    window->app->atlasSampled = false;
    rci_app_pan_reclamp(window);

    rci_sched_request(&window->sched, RCI_SCHED_INTERNAL);
}

#ifndef __EMSCRIPTEN__
static void rci_app_zoom_reset(RC_Window *window) {
    float zoom = rci_zoom_math_clamp(1.0f, window->zoomOpts.minZoom, window->zoomOpts.maxZoom);
    if (zoom == window->zoom && window->panX == 0.0f && window->panY == 0.0f) return;
    window->zoom = zoom;
    window->panX = window->panY = 0.0f;
    window->app->atlasSampled = false;
    rci_sched_request(&window->sched, RCI_SCHED_INTERNAL);
}
#endif

