static inline int rci_net_stream_coding(const char *v, size_t n) {
    static const char take[][9] = { "identity", "gzip", "x-gzip", "deflate" };
    size_t i = 0;
    int coded = 0;

    while (i < n) {
        size_t at, k;

        while (i < n && (v[i] == ' ' || v[i] == '\t' || v[i] == ','))
            i++;
        at = i;
        while (i < n && v[i] != ',' && v[i] != ' ' && v[i] != '\t')
            i++;
        if (i == at)
            break;
        for (k = 0; k < sizeof take / sizeof *take; k++) {
            size_t j = 0;

            while (at + j < i && take[k][j] &&
                   (v[at + j] >= 'A' && v[at + j] <= 'Z' ? v[at + j] + 32 : v[at + j]) == take[k][j])
                j++;
            if (at + j == i && !take[k][j])
                break;
        }
        if (k == sizeof take / sizeof *take)
            return -1;
        if (k > 0)
            coded = 1;
    }
    return coded;
}

