    (void)options;
    (void)profile;
    RCI_LOG_WARN_ONCE("rcFetch: networking is compiled out (RC_NO_NET); every request "
                      "reads FAILED / UNAVAILABLE");
    rci_net_host_changed();
    return RCI_NET_SENTINEL(RCI_NET_CAUSE_NO_NET);
