RC_FetchResult rcFetchResult(RC_Fetch fetch) {
    RC_FetchResult r;

    memset(&r, 0, sizeof r);
    if (fetch == RCI_NET_SENTINEL(RCI_NET_CAUSE_NO_NET)) {
        r.state   = RC_FETCH_FAILED;
        r.error   = RC_FETCH_ERROR_UNAVAILABLE;
        r.message = "networking is compiled out of this build (RC_NO_NET)";
    }
    return r;
}

