static void rci_net_ws_lock(void)   { AcquireSRWLockExclusive(&rci_net_ws_mutex); }
static void rci_net_ws_unlock(void) { ReleaseSRWLockExclusive(&rci_net_ws_mutex); }
#else
#include <pthread.h>
