#define RCI_MEDIA_SENTINEL(cause) (((RC_Media)(cause) << 8) | 0xFFu)

static void rci_media_refusal(RC_MediaInfo *info, RC_MediaError error, const char *message) {
    info->state    = RC_MEDIA_FAILED;
    info->error    = error;
    info->message  = message;
    info->duration = NAN;
    info->volume   = 1.0f;
    info->rate     = 1.0f;
}

