static const struct {
    unsigned char  error;
    unsigned short at;
} rci_media_refusals[] = {
    { RC_MEDIA_ERROR_NONE, 0 },
    { RC_MEDIA_ERROR_UNAVAILABLE, 1 },
    { RC_MEDIA_ERROR_UNAVAILABLE, sizeof("\0" RCI_MEDIA_REFUSAL_1) },
    { RC_MEDIA_ERROR_UNSUPPORTED, sizeof("\0" RCI_MEDIA_REFUSAL_1 "\0" RCI_MEDIA_REFUSAL_2) },
};
#define RCI_MEDIA_REFUSAL_WORDS(cause) (rci_media_refusal_words + rci_media_refusals[cause].at)

static bool rci_media_refused(RC_Media token, RC_MediaInfo *info) {
    RC_Media cause = token >> 8;

    if ((token & 0xFFu) != 0xFFu || cause < RCI_MEDIA_NO_PLAYER || cause > RCI_MEDIA_NO_SOURCE)
        return false;
    rci_media_refusal(info, (RC_MediaError)rci_media_refusals[cause].error, RCI_MEDIA_REFUSAL_WORDS(cause));
    return true;
}

#if defined(__EMSCRIPTEN__)

static void rci_media_lock(void)   { }
static void rci_media_unlock(void) { }
#elif defined(_WIN32)
#ifndef WIN32_LEAN_AND_MEAN
#define WIN32_LEAN_AND_MEAN
#endif
#include <windows.h>
static SRWLOCK rci_media_mutex = SRWLOCK_INIT;
static void rci_media_lock(void)   { AcquireSRWLockExclusive(&rci_media_mutex); }
static void rci_media_unlock(void) { ReleaseSRWLockExclusive(&rci_media_mutex); }
#else
#include <pthread.h>
static pthread_mutex_t rci_media_mutex = PTHREAD_MUTEX_INITIALIZER;
static void rci_media_lock(void)   { pthread_mutex_lock(&rci_media_mutex); }
static void rci_media_unlock(void) { pthread_mutex_unlock(&rci_media_mutex); }
#endif

#define RCI_MEDIA_DETAIL_MAX 96
#define RCI_MEDIA_TICK_S     0.25
#define RCI_MEDIA_RATE_MIN   0.0625
#define RCI_MEDIA_RATE_MAX   16.0

typedef struct RCI_MediaRecord {
    RCI_MediaPlayer player;

    RC_MediaState state;
    RC_MediaError error;
    double        time, duration;
    int           width, height;
    bool          waiting, seeking, muted, loop;
    float         volume, rate;
    char          message[RCI_MEDIA_DETAIL_MAX];

    bool          wantPlay;
    bool          shown;
    bool          owed;
    uint32_t      gen;

    RCI_MediaNews news;
    char          newsDetail[RCI_MEDIA_DETAIL_MAX];
    bool          paced;
} RCI_MediaRecord;

static RCI_MediaRecord         rci_media_records[RCI_MEDIA_OPEN_MAX];
static uint32_t                rci_media_count;
static const RCI_MediaBackend *rci_media_override;
static const RCI_MediaBackend *rci_media_player;
static bool                    rci_media_updating;
static bool                    rci_media_tick_armed;
static double                  rci_media_tick_at;
static bool                    rci_media_polled;
static bool                    rci_media_tick_read;
static void                  (*rci_media_closed)(uint32_t media);

static void                  (*rci_media_wake_fn)(void *user);
static void                   *rci_media_wake_user;
static bool                    rci_media_posted;

static RCI_MediaRecord *rci_media_find(RC_Media token) {
    uint32_t slot = (token & 0xFFu) - 1u;

    return token && slot < RCI_MEDIA_OPEN_MAX && rci_media_records[slot].player.token == token
               ? &rci_media_records[slot]
               : NULL;
}

static const RCI_MediaBackend *rci_media_player_now(void) {
    if (rci_media_override)
        return rci_media_override;
#if defined(__APPLE__)
    return &rci_media_apple_backend;
#elif defined(__ANDROID__)
    return &rci_media_android_backend;
#elif defined(__EMSCRIPTEN__)
    return &rci_media_web;
#elif defined(_WIN32)
    return rci_media_win32_backend();
#elif defined(__linux__)
    return &rci_media_player_backend;
#else
    return NULL;
#endif
}

void rci_media_set_backend(const RCI_MediaBackend *backend) {
    rci_media_override = backend;
}

static const struct RCI_MediaProfile *rci_media_profile_kept;

const struct RCI_MediaProfile *rci_media_profile(void) {
    return rci_media_profile_kept;
}

static void rci_media_take_wake(void) {
    const RCI_LoopHost *host = rci_loop_live() ? rci_loop_host() : NULL;

    rci_media_lock();
    rci_media_wake_fn   = host ? host->wake : NULL;
    rci_media_wake_user = host ? host->user : NULL;
    rci_media_posted    = false;
    rci_media_unlock();
}

void rci_media_publish(RC_Media token, const RCI_MediaNews *news) {
    RCI_MediaRecord *r;
    RCI_MediaNews   *n;

    rci_media_lock();
    r = rci_media_find(token);
    if (r) {
        n = &r->news;

        if (news->what & RCI_MEDIA_NEWS_PLAYING)
            n->what &= ~(RCI_MEDIA_NEWS_PAUSED | RCI_MEDIA_NEWS_BLOCKED | RCI_MEDIA_NEWS_ENDED);
        n->what |= news->what;
        if (news->what & (RCI_MEDIA_NEWS_READY | RCI_MEDIA_NEWS_SIZE)) {
            n->width  = news->width;
            n->height = news->height;
        }
        if (news->what & RCI_MEDIA_NEWS_READY)
            n->duration = news->duration;
        if (news->what & RCI_MEDIA_NEWS_WAITING)
            n->waiting = news->waiting;
        if (news->what & RCI_MEDIA_NEWS_SEEKED)
            n->seeked = news->seeked;
        if ((news->what & RCI_MEDIA_NEWS_FAILED) && !n->error) {
            size_t len = news->detail ? strlen(news->detail) : 0;

            len = len < RCI_MEDIA_DETAIL_MAX ? len : RCI_MEDIA_DETAIL_MAX - 1;
            if (len)
                memcpy(r->newsDetail, news->detail, len);
            r->newsDetail[len] = '\0';
            n->error = news->error ? news->error : RC_MEDIA_ERROR_UNAVAILABLE;
        }

        if (!rci_media_posted && rci_media_wake_fn &&
            (!r->paced || (news->what & ~RCI_MEDIA_NEWS_FRAME))) {
            rci_media_posted = true;
            rci_media_wake_fn(rci_media_wake_user);
        }
    }
    rci_media_unlock();
}

static void rci_media_seek_to(RCI_MediaRecord *r, double seconds) {
    r->time    = seconds;
    r->seeking = true;
    r->owed    = true;
    rci_media_player->seek(&r->player, seconds, ++r->gen);
}

static void rci_media_start(RCI_MediaRecord *r) {
    if (r->state == RC_MEDIA_ENDED)
        rci_media_seek_to(r, 0.0);
    r->state = RC_MEDIA_PLAYING;
    r->error = RC_MEDIA_ERROR_NONE;
    rci_media_player->play(&r->player, true);
}

static size_t rci_media_apply(RCI_MediaRecord *r, const RCI_MediaNews *n) {
    unsigned what = n->what;
    size_t         moved = 0;

    if (!what || r->state == RC_MEDIA_FAILED)
        return 0;
    if (what & RCI_MEDIA_NEWS_FAILED) {
        r->state   = RC_MEDIA_FAILED;
        r->error   = n->error;
        r->waiting = r->seeking = false;
        return 1;
    }

    if ((what & RCI_MEDIA_NEWS_PAUSED) && r->state == RC_MEDIA_LOADING &&
        ((what & RCI_MEDIA_NEWS_HALT) || (!r->muted && r->volume > 0.0f)))
        r->wantPlay = false;

    if (r->state == RC_MEDIA_LOADING)
        what &= ~(unsigned)RCI_MEDIA_NEWS_PAUSED;
    if ((what & RCI_MEDIA_NEWS_READY) && r->state == RC_MEDIA_LOADING) {
        r->state    = RC_MEDIA_READY;
        r->duration = n->duration;
        moved++;

        rci_media_player->set(&r->player, r->volume, r->muted, r->rate, r->loop);
        if (r->time > 0.0)
            rci_media_seek_to(r, rci_isfinite_d(r->duration) && r->time > r->duration
                                     ? r->duration : r->time);
        if (r->wantPlay)
            rci_media_start(r);
    }
    if ((what & (RCI_MEDIA_NEWS_READY | RCI_MEDIA_NEWS_SIZE)) &&
        (r->width != n->width || r->height != n->height)) {
        r->width  = n->width;
        r->height = n->height;
        moved++;
    }
    if ((what & RCI_MEDIA_NEWS_WAITING) && r->waiting != n->waiting) {
        r->waiting = n->waiting;
        moved++;
    }
    if ((what & RCI_MEDIA_NEWS_SEEKED) && r->seeking && n->seeked == r->gen) {
        r->seeking = false;
        moved++;
    }

    if (what & RCI_MEDIA_NEWS_FRAME) {
        if (!r->shown || r->state != RC_MEDIA_PLAYING || (what & RCI_MEDIA_NEWS_DUE))
            moved++;
        r->shown = true;
    }

    if ((what & RCI_MEDIA_NEWS_PLAYING) &&
        (r->state == RC_MEDIA_READY || r->state == RC_MEDIA_PAUSED || r->state == RC_MEDIA_ENDED)) {
        r->state = RC_MEDIA_PLAYING;
        r->error = RC_MEDIA_ERROR_NONE;
        moved++;
    }
    if ((what & (RCI_MEDIA_NEWS_PAUSED | RCI_MEDIA_NEWS_BLOCKED)) && r->state == RC_MEDIA_PLAYING) {
        r->state = RC_MEDIA_PAUSED;
        if (what & RCI_MEDIA_NEWS_BLOCKED)
            r->error = RC_MEDIA_ERROR_BLOCKED;
        moved++;
    }
    if ((what & RCI_MEDIA_NEWS_ENDED) && r->state == RC_MEDIA_PLAYING) {
        r->state   = RC_MEDIA_ENDED;
        r->waiting = false;
        if (rci_isfinite_d(r->duration))
            r->time = r->duration;
        moved++;
    }
    return moved;
}

static bool rci_media_ticks(const RCI_MediaRecord *r, bool quiet) {
    return r->state == RC_MEDIA_PLAYING ||
           (quiet && (r->state == RC_MEDIA_LOADING || r->seeking));
}

static bool rci_media_quiet(void) {
    return rci_media_polled || !rci_loop_live();
}

static void rci_media_arm_tick(void) {
    rci_media_tick_armed = true;
    rci_media_tick_at    = rcMonotonicSeconds() + RCI_MEDIA_TICK_S;
}

static size_t rci_media_update(void) {
    RCI_MediaNews news[RCI_MEDIA_OPEN_MAX];
    size_t        moved = 0;
    bool          playing = false;

    if (rci_media_updating || !rci_media_player)
        return 0;
    rci_media_updating = true;

    if (rci_media_player->service) {
        rci_media_lock();
        rci_media_posted = true;
        rci_media_unlock();
        rci_media_polled = rci_media_player->service();
    }
    rci_media_take_wake();

    rci_media_lock();
    for (int i = 0; i < RCI_MEDIA_OPEN_MAX; i++) {
        RCI_MediaRecord *r = &rci_media_records[i];

        news[i] = r->news;
        if ((r->news.what & RCI_MEDIA_NEWS_FAILED) && r->state != RC_MEDIA_FAILED)
            memcpy(r->message, r->newsDetail, sizeof r->message);
        memset(&r->news, 0, sizeof r->news);
    }
    rci_media_unlock();
    for (int i = 0; i < RCI_MEDIA_OPEN_MAX; i++) {
        RCI_MediaRecord *r = &rci_media_records[i];

        if (!r->player.token)
            continue;
        moved += rci_media_apply(r, &news[i]);
        if (r->state == RC_MEDIA_PLAYING && !r->seeking) {
            r->time = rci_media_player->position(&r->player);
            playing = true;
        }
    }

    rci_media_lock();
    for (int i = 0; i < RCI_MEDIA_OPEN_MAX; i++) {
        RCI_MediaRecord *r = &rci_media_records[i];

        r->paced = r->shown && r->state == RC_MEDIA_PLAYING;
    }
    rci_media_unlock();
    if (rci_media_tick_armed && rcMonotonicSeconds() >= rci_media_tick_at) {
        rci_media_tick_armed = false;
        if (playing && rci_media_tick_read)
            moved++;
        rci_media_tick_read = false;
    }

    for (int i = 0; i < RCI_MEDIA_OPEN_MAX && rci_media_polled && !rci_media_tick_armed; i++) {
        if (rci_media_ticks(&rci_media_records[i], true))
            rci_media_arm_tick();
    }
    rci_media_updating = false;
    return moved;
}

static double rci_media_deadline(void) {
    const bool quiet  = rci_media_quiet();
    bool       serves = false;
    double     left;

    for (int i = 0; i < RCI_MEDIA_OPEN_MAX && rci_media_tick_armed && !serves; i++)
        serves = rci_media_ticks(&rci_media_records[i], quiet);
    if (!serves)
        return INFINITY;
    left = rci_media_tick_at - rcMonotonicSeconds();
    return left > 0.0 ? left : 0.0;
}

static unsigned rci_media_acquire(uint32_t media, uint32_t have, RCI_LoopFrame *frame,
                                  double *next) {
    RCI_MediaRecord *r = rci_media_find(media);
    unsigned         bits;

    if (next)
        *next = INFINITY;
    if (!r)
        return 0;
    bits = RCI_LOOP_MEDIA_OPEN | (r->owed ? RCI_LOOP_MEDIA_PENDING : 0u) |
           (rci_media_player->lend ? RCI_LOOP_MEDIA_EXTERNAL : 0u);
    if (!frame)
        return r->shown ? bits | RCI_LOOP_MEDIA_FRAME : bits;
    if (!rci_media_player->frame || !rci_media_player->frame(&r->player, have, frame, next))
        return bits;
    if (frame->gen != r->gen) {
        if (rci_media_player->release)
            rci_media_player->release(frame);
        return bits | RCI_LOOP_MEDIA_PENDING;
    }
    r->owed = false;
    return (bits & ~RCI_LOOP_MEDIA_PENDING) | RCI_LOOP_MEDIA_FRAME;
}

static void rci_media_release(RCI_LoopFrame *frame) {
    if (rci_media_player && rci_media_player->release)
        rci_media_player->release(frame);
}

static void rci_media_drop(RCI_MediaRecord *r) {
    const RC_Media token = r->player.token;

    rci_media_player->close(&r->player);
    rci_media_lock();
    memset(r, 0, sizeof *r);
    rci_media_unlock();
    if (rci_media_closed)
        rci_media_closed(token);
}

static void rci_media_watch(void (*closed)(uint32_t media)) {
    rci_media_closed = closed;
}

static void rci_media_lend(uint32_t media, void *target) {
    RCI_MediaRecord *r = rci_media_find(media);

    if (r && rci_media_player->lend)
        rci_media_player->lend(&r->player, target);
}

static void rci_media_fail(uint32_t media, const char *why) {
    RCI_MediaRecord *r = rci_media_find(media);
    RCI_MediaNews    n;

    if (!r || r->state == RC_MEDIA_FAILED)
        return;
    if (r->state == RC_MEDIA_PLAYING)
        rci_media_player->play(&r->player, false);
    memset(&n, 0, sizeof n);
    n.what   = RCI_MEDIA_NEWS_FAILED;
    n.error  = RC_MEDIA_ERROR_UNSUPPORTED;
    n.detail = why;
    rci_media_publish(media, &n);
}

static void rci_media_teardown(void) {
    if (!rci_media_player)
        return;
    for (int i = 0; i < RCI_MEDIA_OPEN_MAX; i++) {
        if (rci_media_records[i].player.token)
            rci_media_drop(&rci_media_records[i]);
    }
    if (rci_media_player->shutdown)
        rci_media_player->shutdown();
    rci_media_lock();
    rci_media_wake_fn = NULL;
    rci_media_unlock();
    rci_media_player     = NULL;
    rci_media_tick_armed = false;
    rci_media_tick_read  = false;
    rci_media_polled     = false;
    rci_media_join_player(NULL);
}

static const RCI_LoopMedia rci_media_table = {
    { rci_media_update, rci_media_deadline, rci_media_teardown },
    rci_media_acquire,
    rci_media_release,
    rci_media_watch,
    rci_media_lend,
    rci_media_fail
};

RC_Media rci_media_open_with_profile(const char *src, RC_MediaOptions options,
                                     const struct RCI_MediaProfile *profile) {
    const RCI_MediaBackend *b = rci_media_player ? rci_media_player : rci_media_player_now();
    RCI_MediaRecord        *r = NULL;
    RC_Media                token;
    char                   *srcBeside, *altBeside;

    if (profile && !rci_media_profile_kept)
        rci_media_profile_kept = profile;

    if (!src || !*src) {
        RCI_LOG_WARN_ONCE("rcMediaOpen: %s", RCI_MEDIA_REFUSAL_WORDS(RCI_MEDIA_NO_SOURCE));
        return RCI_MEDIA_SENTINEL(RCI_MEDIA_NO_SOURCE);
    }
    if (!b) {
        RCI_LOG_WARN_ONCE("rcMediaOpen: %s; the media reads FAILED / UNAVAILABLE",
                          RCI_MEDIA_REFUSAL_WORDS(RCI_MEDIA_NO_PLAYER));
        return RCI_MEDIA_SENTINEL(RCI_MEDIA_NO_PLAYER);
    }
    for (int i = 0; i < RCI_MEDIA_OPEN_MAX && !r; i++)
        r = rci_media_records[i].player.token ? NULL : &rci_media_records[i];
    if (!r) {
        RCI_LOG_WARN_ONCE("rcMediaOpen: %s", RCI_MEDIA_REFUSAL_WORDS(RCI_MEDIA_FULL));
        return RCI_MEDIA_SENTINEL(RCI_MEDIA_FULL);
    }
    if (!rci_media_player) {
        rci_media_player = b;

        rci_media_polled = b->service != NULL;
        rci_media_join_player(&rci_media_table);
        rci_media_take_wake();
    }

    rci_media_count = rci_media_count < 0xFFFFFFu ? rci_media_count + 1u : 1u;
    token = (rci_media_count << 8) | (RC_Media)(r - rci_media_records + 1);
    r->state    = RC_MEDIA_LOADING;
    r->duration = NAN;
    r->volume   = 1.0f;
    r->rate     = 1.0f;
    r->muted    = options.muted;
    r->loop     = options.loop;
    r->wantPlay = options.autoplay;
    rci_media_lock();
    r->player.token = token;
    rci_media_unlock();

    srcBeside = rci_load_file_beside_path(src);
    altBeside = options.alt && *options.alt ? rci_load_file_beside_path(options.alt) : NULL;
    b->open(&r->player, srcBeside ? srcBeside : src, altBeside ? altBeside : options.alt);
    free(srcBeside);
    free(altBeside);
    return token;
}

RC_Media rci_media_open(const char *src, RC_MediaOptions options) {
    return rci_media_open_with_profile(src, options, NULL);
}

static void rci_media_settings(RCI_MediaRecord *r) {
    if (r->state >= RC_MEDIA_READY && r->state <= RC_MEDIA_ENDED)
        rci_media_player->set(&r->player, r->volume, r->muted, r->rate, r->loop);
    rci_loop_changed();
}

void rcMediaPlay(RC_Media media) {
    RCI_MediaRecord *r = rci_media_find(media);

    if (!r || r->state == RC_MEDIA_PLAYING || r->state == RC_MEDIA_FAILED)
        return;
    if (r->state == RC_MEDIA_LOADING) {
        r->wantPlay = true;
        return;
    }
    rci_media_start(r);
    rci_loop_changed();
}

void rcMediaPause(RC_Media media) {
    RCI_MediaRecord *r = rci_media_find(media);

    if (r && r->state == RC_MEDIA_LOADING) {
        r->wantPlay = false;
    } else if (r && r->state == RC_MEDIA_PLAYING) {
        r->state = RC_MEDIA_PAUSED;
        rci_media_lock();
        r->paced = false;
        rci_media_unlock();
        rci_media_player->play(&r->player, false);
        rci_loop_changed();
    }
}

void rcMediaSeek(RC_Media media, double seconds) {
    RCI_MediaRecord *r = rci_media_find(media);

    if (!rci_isfinite_d(seconds)) {
        RCI_LOG_WARN_ONCE("rcMediaSeek: %f is not a time; the seek is refused", seconds);
        return;
    }
    if (!r || r->state == RC_MEDIA_FAILED)
        return;
    seconds = seconds > 0.0 ? seconds : 0.0;
    if (r->state == RC_MEDIA_LOADING) {
        r->time = seconds;
    } else {
        if (rci_isfinite_d(r->duration) && seconds > r->duration)
            seconds = r->duration;
        rci_media_seek_to(r, seconds);
        if (r->state == RC_MEDIA_ENDED)
            r->state = RC_MEDIA_PAUSED;
    }
    rci_loop_changed();
}

void rcMediaSetRate(RC_Media media, double rate) {
    RCI_MediaRecord *r = rci_media_find(media);

    if (!(rate >= RCI_MEDIA_RATE_MIN && rate <= RCI_MEDIA_RATE_MAX)) {
        RCI_LOG_WARN_ONCE("rcMediaSetRate: %f is outside 0.0625 to 16; the rate is kept", rate);
        return;
    }
    if (r && r->state != RC_MEDIA_FAILED) {
        r->rate = (float)rate;
        rci_media_settings(r);
    }
}

void rcMediaSetVolume(RC_Media media, float volume) {
    RCI_MediaRecord *r = rci_media_find(media);

    if (isnan(volume)) {
        RCI_LOG_WARN_ONCE("rcMediaSetVolume: NaN is not a volume; the volume is kept");
        return;
    }
    if (r && r->state != RC_MEDIA_FAILED) {
        r->volume = volume < 0.0f ? 0.0f : volume > 1.0f ? 1.0f : volume;
        rci_media_settings(r);
    }
}

void rcMediaSetMuted(RC_Media media, bool muted) {
    RCI_MediaRecord *r = rci_media_find(media);

    if (r && r->state != RC_MEDIA_FAILED) {
        r->muted = muted;
        rci_media_settings(r);
    }
}

void rcMediaSetLoop(RC_Media media, bool loop) {
    RCI_MediaRecord *r = rci_media_find(media);

    if (r && r->state != RC_MEDIA_FAILED) {
        r->loop = loop;
        rci_media_settings(r);
    }
}

RC_MediaInfo rcMediaRead(RC_Media media) {
    const bool       live = rci_loop_live();
    RC_MediaInfo     info;
    RCI_MediaRecord *r;

    memset(&info, 0, sizeof info);
    if (rci_media_player && !live)
        rci_media_update();
    if (rci_media_refused(media, &info) || !(r = rci_media_find(media)))
        return info;
    info.state    = r->state;
    info.error    = r->error;
    info.message  = r->state == RC_MEDIA_FAILED ? r->message : NULL;
    info.time     = r->time;
    info.duration = r->duration;
    info.width    = r->width;
    info.height   = r->height;
    info.waiting  = r->waiting;
    info.seeking  = r->seeking;
    info.muted    = r->muted;
    info.loop     = r->loop;
    info.volume   = r->volume;
    info.rate     = r->rate;
    if (rci_media_ticks(r, rci_media_quiet())) {
        rci_media_tick_read = true;
        if (!rci_media_tick_armed)
            rci_media_arm_tick();
    }
    return info;
}

void rcMediaClose(RC_Media media) {
    RCI_MediaRecord *r = rci_media_find(media);

    if (r) {
        rci_media_drop(r);
        rci_loop_changed();
    }
}

void rcAudioSession(RC_AudioSession type) {
    if (type < RC_AUDIO_SESSION_AUTO || type > RC_AUDIO_SESSION_APP) {
        RCI_LOG_WARN_ONCE("rcAudioSession: %d is not an RC_AudioSession; the session is kept",
                          (int)type);
        return;
    }
    rci_media_session_set(type);
}

