#include <math.h>

static bool rci_media_console_refused(const char *call) {
    if (!rci_loop_runner_owns())
        return false;
    RCI_LOG_WARN_ONCE("%s does nothing: RayClay's runner owns the update loop from rcAppCreate to "
                      "rcAppDestroy, and rcMediaUpdate, rcMediaNextDeadline and rcMediaShutdown "
                      "are for a program that runs its own", call);
    return true;
}

int rcMediaUpdate(void) {
    const RCI_LoopMedia *media = rci_loop_media();

    if (rci_media_console_refused("rcMediaUpdate") || !media)
        return 0;

    return (int)media->service.update();
}

double rcMediaNextDeadline(void) {
    const RCI_LoopMedia *media = rci_loop_media();

    if (rci_media_console_refused("rcMediaNextDeadline") || !media)
        return INFINITY;
    return media->service.deadline();
}

void rcMediaShutdown(void) {
    const RCI_LoopMedia *media = rci_loop_media();

    if (!rci_media_console_refused("rcMediaShutdown") && media)
        media->service.shutdown();
}

#if !defined(RC_NO_MEDIA)

#include <math.h>

static const RCI_LoopMedia   *rci_media_seam_player;
static const RCI_LoopService *rci_media_seam_sound;
static void                 (*rci_media_seam_closed)(uint32_t media);
static bool                   rci_media_seam_in;

static size_t rci_media_seam_update(void) {
    const RCI_LoopService *sound = rci_media_seam_sound;
    size_t                 moved = rci_media_seam_player ? rci_media_seam_player->service.update() : 0;

    return sound ? moved + sound->update() : moved;
}

static double rci_media_seam_deadline(void) {
    double a = rci_media_seam_player ? rci_media_seam_player->service.deadline() : INFINITY;
    double b = rci_media_seam_sound ? rci_media_seam_sound->deadline() : INFINITY;

    return a < b ? a : b;
}

static void rci_media_seam_shutdown(void) {
    const RCI_LoopMedia   *player = rci_media_seam_player;
    const RCI_LoopService *sound  = rci_media_seam_sound;

    if (player)
        player->service.shutdown();
    if (sound)
        sound->shutdown();
}

static unsigned rci_media_seam_acquire(uint32_t media, uint32_t have, RCI_LoopFrame *frame,
                                       double *next) {
    if (rci_media_seam_player)
        return rci_media_seam_player->acquire(media, have, frame, next);
    if (next)
        *next = INFINITY;
    return 0;
}

static void rci_media_seam_release(RCI_LoopFrame *frame) {
    if (rci_media_seam_player)
        rci_media_seam_player->release(frame);
}

static void rci_media_seam_watch(void (*closed)(uint32_t media)) {
    rci_media_seam_closed = closed;
    if (rci_media_seam_player)
        rci_media_seam_player->watch(closed);
}

static void rci_media_seam_lend(uint32_t media, void *target) {
    if (rci_media_seam_player)
        rci_media_seam_player->lend(media, target);
}

static void rci_media_seam_fail(uint32_t media, const char *why) {
    if (rci_media_seam_player)
        rci_media_seam_player->fail(media, why);
}

static const RCI_LoopMedia rci_media_seam_table = {
    { rci_media_seam_update, rci_media_seam_deadline, rci_media_seam_shutdown },
    rci_media_seam_acquire,
    rci_media_seam_release,
    rci_media_seam_watch,
    rci_media_seam_lend,
    rci_media_seam_fail
};

static size_t rci_media_seam_both_update(void) {
    const RCI_LoopService *net = rci_loop_net();
    size_t                 moved = net ? net->update() : 0;

    return moved + rci_media_seam_update();
}

static double rci_media_seam_both_deadline(void) {
    const RCI_LoopService *net = rci_loop_net();
    double                 a = net ? net->deadline() : INFINITY;
    double                 b = rci_media_seam_deadline();

    return a < b ? a : b;
}

static void rci_media_seam_both_shutdown(void) {
    const RCI_LoopService *net = rci_loop_net();

    rci_media_seam_shutdown();
    if (net)
        net->shutdown();
}

static const RCI_LoopService rci_media_seam_both = {
    rci_media_seam_both_update, rci_media_seam_both_deadline, rci_media_seam_both_shutdown
};

static void rci_media_seam_register(void) {
    const bool in = rci_media_seam_player || rci_media_seam_sound;

    if (in != rci_media_seam_in) {
        rci_media_seam_in = in;
        rci_loop_register_media(in ? &rci_media_seam_table : NULL, &rci_media_seam_both);
    }
}

void rci_media_join_player(const RCI_LoopMedia *player) {
    rci_media_seam_player = player;
    if (player && rci_media_seam_closed)
        player->watch(rci_media_seam_closed);
    rci_media_seam_register();
}

void rci_media_join_sound(const RCI_LoopService *sound) {
    rci_media_seam_sound = sound;
    rci_media_seam_register();
}

static long rci_media_seam_session;

void rci_media_session_set(RC_AudioSession type) {
#if defined(__GNUC__) || defined(__clang__)
    __atomic_store_n(&rci_media_seam_session, (long)type, __ATOMIC_SEQ_CST);
#else
    rci_media_seam_session = (long)type;
#endif
}

RC_AudioSession rci_media_session(void) {
#if defined(__GNUC__) || defined(__clang__)
    return (RC_AudioSession)__atomic_load_n(&rci_media_seam_session, __ATOMIC_SEQ_CST);
#else
    return (RC_AudioSession)rci_media_seam_session;
#endif
}

#endif

