#if defined(__EMSCRIPTEN__)
#define RCI_SOUND_THREADS 0
static void rci_media_sound_lock(void)   { }
static void rci_media_sound_unlock(void) { }
static void rci_media_sound_signal_worker(void) { }
#elif defined(_WIN32)
#define RCI_SOUND_THREADS 1
#ifndef WIN32_LEAN_AND_MEAN
#define WIN32_LEAN_AND_MEAN
#endif
#include <windows.h>
static SRWLOCK            rci_media_sound_mutex = SRWLOCK_INIT;
static CONDITION_VARIABLE rci_media_sound_cond  = CONDITION_VARIABLE_INIT;
static HANDLE             rci_media_sound_thread;
static void rci_media_sound_lock(void)   { AcquireSRWLockExclusive(&rci_media_sound_mutex); }
static void rci_media_sound_unlock(void) { ReleaseSRWLockExclusive(&rci_media_sound_mutex); }
static void rci_media_sound_signal(void) { WakeAllConditionVariable(&rci_media_sound_cond); }
static void rci_media_sound_signal_worker(void) { rci_media_sound_signal(); }

static void rci_media_sound_wait(double seconds) {
    SleepConditionVariableSRW(&rci_media_sound_cond, &rci_media_sound_mutex, (DWORD)(seconds * 1000.0) + 1, 0);
}
#else
#define RCI_SOUND_THREADS 1
#include <pthread.h>
#include <time.h>
static pthread_mutex_t rci_media_sound_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t  rci_media_sound_cond  = PTHREAD_COND_INITIALIZER;
static pthread_t       rci_media_sound_thread;
static void rci_media_sound_lock(void)   { pthread_mutex_lock(&rci_media_sound_mutex); }
static void rci_media_sound_unlock(void) { pthread_mutex_unlock(&rci_media_sound_mutex); }
static void rci_media_sound_signal(void) { pthread_cond_broadcast(&rci_media_sound_cond); }
static void rci_media_sound_signal_worker(void) { rci_media_sound_signal(); }

static void rci_media_sound_wait(double seconds) {
    struct timespec ts;
    long            ns = (long)(seconds * 1e9);

#if defined(CLOCK_REALTIME)
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        ts.tv_sec  = time(NULL);
        ts.tv_nsec = 0;
    }
#else
    ts.tv_sec  = time(NULL) + 1;
    ts.tv_nsec = 0;
#endif
    ts.tv_sec  += ns / 1000000000L;
    ts.tv_nsec += ns % 1000000000L;
    if (ts.tv_nsec >= 1000000000L) {
        ts.tv_sec  += 1;
        ts.tv_nsec -= 1000000000L;
    }
    pthread_cond_timedwait(&rci_media_sound_cond, &rci_media_sound_mutex, &ts);
}
#endif

