#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef void (*RCI_SoundWebAnswer)(int token, int error, int buffer, int frames, int channels,
                                   int rate);
typedef unsigned char *(*RCI_SoundWebRoom)(int len);
typedef void (*RCI_SoundWebWav)(int token, unsigned char *bytes, int len);

int  rci_media_sound_web_js_open(void);
int  rci_media_sound_web_js_start(int slot, int id, int buffer, double gain, int loop);
void rci_media_sound_web_js_gain(int slot, int id, double gain);
void rci_media_sound_web_js_stop(int slot, int id);
int  rci_media_sound_web_js_done(int slot);
int  rci_media_sound_web_js_blocked(int slot);
int  rci_media_sound_web_js_at(int slot);
int  rci_media_sound_web_js_renders(void);
int  rci_media_sound_web_js_buffer(const float *samples, int frames, int channels, int rate);
void rci_media_sound_web_js_decode(RCI_SoundWebAnswer answer, RCI_SoundWebRoom room, RCI_SoundWebWav wav,
                             char *words, int size, int token, const unsigned char *bytes, int len,
                             const char *path);
void rci_media_sound_web_js_release(int buffer);
void rci_media_sound_web_js_close(void);

static char rci_media_sound_web_words[RCI_SOUND_DETAIL_MAX];

static unsigned char *rci_media_sound_web_room(int len) {
    return (unsigned char *)malloc(len > 0 ? (size_t)len : 1);
}

static void rci_media_sound_web_wav(int token, unsigned char *bytes, int len) {
    rci_media_sound_wav_answer((RC_Sound)(uint32_t)token, bytes, (size_t)len);
    free(bytes);
}

#define RCI_SOUND_WEB_RATE_MIN 3000

RC_MediaError rci_media_sound_web_samples(RCI_SoundPcm *pcm, char *why) {
    float         *s = pcm->samples;
    const int      ch = pcm->channels;
    uint32_t       frames = pcm->frames;
    int            rate = pcm->rate, id;

    if (rate < RCI_SOUND_WEB_RATE_MIN) {

        const uint32_t k  = (uint32_t)((RCI_SOUND_WEB_RATE_MIN + rate - 1) / rate);
        float         *up = frames <= 0x7FFFFFFFu / k / (uint32_t)ch
                                ? (float *)malloc((size_t)frames * k * (size_t)ch * sizeof *up) : NULL;

        if (!up) {
            free(s);
            memset(pcm, 0, sizeof *pcm);
            snprintf(why, RCI_SOUND_DETAIL_MAX, "%s", "out of memory");
            return RC_MEDIA_ERROR_UNAVAILABLE;
        }
        for (uint32_t i = 0; i < frames * k; i++) {
            const uint32_t at = i / k;
            const float    t  = (float)(i % k) / (float)k;

            for (int c = 0; c < ch; c++) {
                const float a = s[(size_t)at * (size_t)ch + (size_t)c];
                const float b = at + 1 < frames ? s[((size_t)at + 1) * (size_t)ch + (size_t)c] : 0.0f;

                up[(size_t)i * (size_t)ch + (size_t)c] = a + (b - a) * t;
            }
        }
        free(s);
        s       = up;
        frames *= k;
        rate   *= (int)k;
    }
    id = rci_media_sound_web_js_buffer(s, (int)frames, ch, rate);
    free(s);
    memset(pcm, 0, sizeof *pcm);
    if (id <= 0) {
        snprintf(why, RCI_SOUND_DETAIL_MAX, id ? "the browser makes no sound buffer at %d Hz"
                                               : "this browser has no Web Audio (AudioContext)", rate);
        return RC_MEDIA_ERROR_UNAVAILABLE;
    }
    pcm->frames   = frames;
    pcm->channels = ch;
    pcm->rate     = rate;
    pcm->buffer   = id;
    return RC_MEDIA_ERROR_NONE;
}

static void rci_media_sound_web_answer(int token, int error, int buffer, int frames, int channels,
                                 int rate) {
    RCI_SoundPcm pcm;

    memset(&pcm, 0, sizeof pcm);
    pcm.frames   = (uint32_t)frames;
    pcm.channels = channels;
    pcm.rate     = rate;
    pcm.buffer   = buffer;
    rci_media_sound_decoded((RC_Sound)(uint32_t)token, (RC_MediaError)error, error ? NULL : &pcm,
                      rci_media_sound_web_words);
}

static bool rci_media_sound_web_open(int *rate, char *why) {
    const int r = rci_media_sound_web_js_open();

    if (r <= 0) {
        snprintf(why, RCI_SOUND_DETAIL_MAX, "%s", "this browser has no Web Audio (AudioContext)");
        return false;
    }
    *rate = r;
    return true;
}

static bool rci_media_sound_web_start(void) { return true; }
static void rci_media_sound_web_nothing(void) { }

const RCI_SoundDevice rci_media_sound_web_device = {
    "Web Audio", rci_media_sound_web_open, rci_media_sound_web_start, rci_media_sound_web_nothing,
    rci_media_sound_web_js_close, NULL
};

bool rci_media_sound_web_push(const RCI_MixCommand *c) {
    if (c->slot < 0 || c->slot >= RCI_MIX_SLOTS)
        return true;
    switch (c->what) {
    case RCI_MIX_START:
        return rci_media_sound_web_js_start(c->slot, (int)c->id, c->buffer, c->gain, c->loop) != 0;
    case RCI_MIX_GAIN:
        rci_media_sound_web_js_gain(c->slot, (int)c->id, c->gain);
        return true;
    case RCI_MIX_STOP:
        rci_media_sound_web_js_stop(c->slot, (int)c->id);
        return true;
    default:
        return true;
    }
}

long rci_media_sound_web_done(int slot)    { return (long)rci_media_sound_web_js_done(slot); }
bool rci_media_sound_web_blocked(int slot) { return rci_media_sound_web_js_blocked(slot) != 0; }
long rci_media_sound_web_at(int slot)      { return (long)rci_media_sound_web_js_at(slot); }
long rci_media_sound_web_renders(void)     { return (long)rci_media_sound_web_js_renders(); }
void rci_media_sound_web_free(int buffer)  { rci_media_sound_web_js_release(buffer); }

void rci_media_sound_web_decode(RC_Sound token, const unsigned char *bytes, size_t len, const char *path) {
    rci_media_sound_web_js_decode(rci_media_sound_web_answer, rci_media_sound_web_room, rci_media_sound_web_wav,
                            rci_media_sound_web_words, (int)sizeof rci_media_sound_web_words, (int)token, bytes,
                            bytes ? (int)len : 0, bytes ? NULL : path);
}

