#include <stdbool.h>
#include <stddef.h>

typedef struct RCI_NetWebCalls {
    bool (*header)(RCI_NetRequest *req, const char *line, size_t length);
    bool (*open)(RCI_NetRequest *req, int status);
    size_t (*room)(RCI_NetRequest *req, size_t want);
    bool (*append)(RCI_NetRequest *req, const void *bytes, size_t length);
    void (*answered)(RCI_NetRequest *req, int status);
    void (*tooLarge)(RCI_NetRequest *req);
    void (*unreached)(RCI_NetRequest *req);
    void (*cut)(RCI_NetRequest *req);
    void (*malformed)(RCI_NetRequest *req);
} RCI_NetWebCalls;

void rci_net_web_fetch(RCI_NetRequest *req, const RCI_NetWebCalls *calls, unsigned char *stage,
                       size_t stageSize, const char *method, const char *url,
                       const char *const *headers, const void *body, size_t bodyLength,
                       size_t maxBytes, int refuseRedirect, int stream);
void rci_net_web_abort(RCI_NetRequest *req);
void rci_net_web_wake(RCI_NetRequest *req);

static unsigned char rci_net_web_stage[RCI_NET_HEADERS_MAX];

static size_t rci_net_web_room(RCI_NetRequest *req, size_t want) {
    return rci_net_body_room(req, want < RCI_NET_STREAM_CHUNK ? want : RCI_NET_STREAM_CHUNK);
}

static void rci_net_web_answered(RCI_NetRequest *req, int status) {
    rci_net_publish(req, status, RC_FETCH_ERROR_NONE, NULL);
}

static void rci_net_web_too_large(RCI_NetRequest *req) {
    rci_net_publish(req, 0, RC_FETCH_ERROR_TOO_LARGE, "its Content-Length is over .maxBytes");
}

static void rci_net_web_unreached(RCI_NetRequest *req) {
    rci_net_publish(req, 0, RC_FETCH_ERROR_NETWORK,
                    req->redirect == RC_FETCH_REDIRECT_ERROR
                        ? "no response; the browser names no cause "
                          "(offline, refused, TLS, CORS, mixed content, redirect)"
                        : "no response; the browser names no cause "
                          "(offline, refused, TLS, CORS or mixed content)");
}

static void rci_net_web_cut(RCI_NetRequest *req) {
    rci_net_publish(req, 0, RC_FETCH_ERROR_NETWORK, "the connection failed while the body was read");
}

static void rci_net_web_malformed(RCI_NetRequest *req) {
    rci_net_publish(req, 0, RC_FETCH_ERROR_INVALID, "the browser refused the URL or a header as malformed");
}

static const RCI_NetWebCalls rci_net_web_calls = {
    rci_net_response_header, rci_net_response_open, rci_net_web_room, rci_net_body_append,
    rci_net_web_answered, rci_net_web_too_large, rci_net_web_unreached, rci_net_web_cut,
    rci_net_web_malformed
};

static void rci_net_web_start(RCI_NetRequest *req) {
    rci_net_web_fetch(req, &rci_net_web_calls, rci_net_web_stage, sizeof rci_net_web_stage,
                      req->method, req->url, req->headers, req->body, req->bodyLength,
                      req->maxBytes, req->redirect == RC_FETCH_REDIRECT_ERROR, req->stream);
}

static void rci_net_web_cancel(RCI_NetRequest *req) {
    rci_net_web_abort(req);
}

static void rci_net_web_resume(RCI_NetRequest *req) {
    rci_net_web_wake(req);
}

const RCI_NetBackend rci_net_web_backend = {
    "web", rci_net_web_start, rci_net_web_cancel, NULL, NULL, rci_net_web_resume, false, false
};

