static double rci_net_curl_idle_now(void) {
#if defined(RCI_NET_CURL_MONOTONIC)
    struct timespec ts;

    if (clock_gettime(RCI_NET_CURL_MONOTONIC, &ts) == 0)
        return (double)ts.tv_sec * 1000.0 + (double)ts.tv_nsec / 1e6;
#endif
    return -1.0;
}

