typedef long          RCI_NetAppleInt;
typedef unsigned long RCI_NetAppleUInt;

#define RCI_NET_APPLE_CHUNK RCI_NET_STREAM_CHUNK

#define RCI_NET_APPLE_CACHE_PROTOCOL      0
#define RCI_NET_APPLE_RESPONSE_CANCEL     0
#define RCI_NET_APPLE_RESPONSE_ALLOW      1
#define RCI_NET_APPLE_CHALLENGE_DEFAULT   1
#define RCI_NET_APPLE_CHALLENGE_REJECT    3
#define RCI_NET_APPLE_LATIN1              5

#define RCI_NET_APPLE_FOREVER (10.0 * 365.0 * 86400.0)

#define RCI_NET_APPLE_GZIP_MIN 20

#define RCI_NET_APPLE_CHUNKED_MIN 3

typedef struct RCI_NetAppleBlock {
    void   *isa;
    int32_t flags;
    int32_t reserved;
    void  (*invoke)(void);
    void   *descriptor;
} RCI_NetAppleBlock;

typedef struct RCI_NetAppleHop {
    RCI_NetRequest *req;
    id              task;
    id              held;
    size_t          heldAt;
    size_t          kept;
    int             status;
    bool            headed;
    bool            paused;
    bool            encoded;
    bool            gzip;
    bool            coded;
    bool            chunked;
    bool            lastChunked;
    int64_t         length;
    int64_t         got;
    bool            whole;
    bool            canceled;
    bool            ended;
    bool            published;
    bool            done;
    RC_FetchError   error;
    const char     *why;
    const char     *broken;
    RC_FetchError   endError;
    const char     *endWhy;
    RCI_NetAppleInt endCode;
    char            domain[40];
} RCI_NetAppleHop;

typedef struct RCI_NetAppleEnd {
    RCI_NetRequest *req;
    int             status;
    RC_FetchError   error;
    const char     *detail;
    char            text[128];
} RCI_NetAppleEnd;

static int             rci_net_apple_ready;
static const char     *rci_net_apple_missing;
static id              rci_net_apple_delegate;
static id              rci_net_apple_session;
static id              rci_net_apple_direct;
static pthread_mutex_t rci_net_apple_lock = PTHREAD_MUTEX_INITIALIZER;
static RCI_NetAppleHop *rci_net_apple_hops[RCI_NET_HOPS_MAX];

static id rci_net_apple_msg(id o, const char *sel) {
    id (*send)(id, SEL) = (id (*)(id, SEL))objc_msgSend;
    return send(o, sel_registerName(sel));
}

