#define RCI_SOUND_CA_FOURCC(a, b, c, d) \
    ((uint32_t)(a) << 24 | (uint32_t)(b) << 16 | (uint32_t)(c) << 8 | (uint32_t)(d))

typedef struct RCI_SoundCaDesc {
    uint32_t type, subType, manufacturer, flags, flagsMask;
} RCI_SoundCaDesc;
typedef struct RCI_SoundCaFormat {
    double   sampleRate;
    uint32_t formatId, formatFlags, bytesPerPacket, framesPerPacket, bytesPerFrame;
    uint32_t channelsPerFrame, bitsPerChannel, reserved;
} RCI_SoundCaFormat;
typedef struct RCI_SoundCaBuffer {
    uint32_t channels, bytes;
    void    *data;
} RCI_SoundCaBuffer;
typedef struct RCI_SoundCaBufferList {
    uint32_t          count;
    RCI_SoundCaBuffer buffers[1];
} RCI_SoundCaBufferList;
typedef int32_t (*RCI_SoundCaRender)(void *ref, uint32_t *flags, const void *stamp, uint32_t bus,
                                     uint32_t frames, RCI_SoundCaBufferList *io);
typedef struct RCI_SoundCaCallback {
    RCI_SoundCaRender proc;
    void             *ref;
} RCI_SoundCaCallback;
typedef struct RCI_SoundCaAddress {
    uint32_t selector, scope, element;
} RCI_SoundCaAddress;

#define RCI_SOUND_CA_PROP_FORMAT   8u
#define RCI_SOUND_CA_PROP_RENDER   23u
#define RCI_SOUND_CA_SCOPE_INPUT   1u
#define RCI_SOUND_CA_SCOPE_OUTPUT  2u
#define RCI_SOUND_CA_FLOAT_PACKED  (1u | 8u)
#define RCI_SOUND_CA_SYSTEM        1u

static RCI_SoundCaApi        rci_media_sound_ca_api;
static const RCI_SoundCaApi *rci_media_sound_ca_test;
static void                 *rci_media_sound_ca_unit;
static bool                  rci_media_sound_ca_loaded, rci_media_sound_ca_listening;

void rci_media_sound_apple_use(const RCI_SoundCaApi *api) {
    rci_media_sound_ca_test   = api;
    rci_media_sound_ca_loaded = false;
}

static int32_t rci_media_sound_ca_render(void *ref, uint32_t *flags, const void *stamp, uint32_t bus,
                                   uint32_t frames, RCI_SoundCaBufferList *io) {
    RCI_SoundCaBuffer *b;

    (void)ref;
    (void)flags;
    (void)stamp;
    (void)bus;
    if (!io)
        return 0;
    b = io->buffers;
    if (io->count == 1 && b[0].data && b[0].bytes >= (uint64_t)frames * 2u * sizeof(float)) {
        rci_media_sound_mix((float *)b[0].data, frames);
        return 0;
    }
    for (uint32_t i = 0; i < io->count; i++) {
        if (b[i].data)
            memset(b[i].data, 0, b[i].bytes);
    }
    return 0;
}

static bool rci_media_sound_ca_load(char *why) {
    RCI_SoundCaApi *a = &rci_media_sound_ca_api;
    void           *lib;

    if (rci_media_sound_ca_loaded)
        return true;
    if (rci_media_sound_ca_test) {
        *a = *rci_media_sound_ca_test;
    } else {
        lib = dlopen("/System/Library/Frameworks/AudioToolbox.framework/AudioToolbox",
                     RTLD_LAZY | RTLD_LOCAL);
        if (!lib) {
            snprintf(why, RCI_SOUND_DETAIL_MAX, "%s", "AudioToolbox could not be opened");
            return false;
        }
        memset(a, 0, sizeof *a);
        *(void **)&a->find    = dlsym(lib, "AudioComponentFindNext");
        *(void **)&a->make    = dlsym(lib, "AudioComponentInstanceNew");
        *(void **)&a->dispose = dlsym(lib, "AudioComponentInstanceDispose");
        *(void **)&a->set     = dlsym(lib, "AudioUnitSetProperty");
        *(void **)&a->get     = dlsym(lib, "AudioUnitGetProperty");
        *(void **)&a->init    = dlsym(lib, "AudioUnitInitialize");
        *(void **)&a->uninit  = dlsym(lib, "AudioUnitUninitialize");
        *(void **)&a->start   = dlsym(lib, "AudioOutputUnitStart");
        *(void **)&a->stop    = dlsym(lib, "AudioOutputUnitStop");
#if !TARGET_OS_IPHONE
        lib = dlopen("/System/Library/Frameworks/CoreAudio.framework/CoreAudio", RTLD_LAZY | RTLD_LOCAL);
        if (lib) {
            *(void **)&a->listen   = dlsym(lib, "AudioObjectAddPropertyListener");
            *(void **)&a->unlisten = dlsym(lib, "AudioObjectRemovePropertyListener");
        }
#endif
    }
    if (!a->find || !a->make || !a->dispose || !a->set || !a->get || !a->init || !a->uninit ||
        !a->start || !a->stop) {
        snprintf(why, RCI_SOUND_DETAIL_MAX, "%s", "AudioToolbox lacks an AudioUnit call");
        return false;
    }
    rci_media_sound_ca_loaded = true;
    return true;
}

#if TARGET_OS_IPHONE

#define RCI_SOUND_CA_BEGAN  1u
#define RCI_SOUND_CA_BY_APP 1

static struct {
    id   observer;
    id   inactive, resumed, interrupted, typeKey, contextKey;
    long reactivate;
} rci_media_sound_ios;

static id rci_media_sound_ios_msg(id o, const char *sel) {
    id (*send)(id, SEL) = (id (*)(id, SEL))objc_msgSend;
    return send(o, sel_registerName(sel));
}

static id rci_media_sound_ios_constant(void *lib, const char *name) {
    id *p = lib ? (id *)dlsym(lib, name) : NULL;
    return p ? *p : nil;
}

static bool rci_media_sound_ios_is(id note, id name) {
    BOOL (*same)(id, SEL, id) = (BOOL (*)(id, SEL, id))objc_msgSend;
    return name && same(rci_media_sound_ios_msg(note, "name"), sel_registerName("isEqualToString:"), name);
}

static id rci_media_sound_ios_info(id note, id key) {
    id (*get)(id, SEL, id) = (id (*)(id, SEL, id))objc_msgSend;
    id info = rci_media_sound_ios_msg(note, "userInfo");
    return info && key ? get(info, sel_registerName("objectForKey:"), key) : nil;
}

static void rci_media_sound_ios_on_session(id self, SEL cmd, id note) {
    (void)self;
    (void)cmd;
    if (rci_media_sound_ios_is(note, rci_media_sound_ios.inactive)) {
        long (*source)(id, SEL) = (long (*)(id, SEL))objc_msgSend;
        id   context = rci_media_sound_ios_info(note, rci_media_sound_ios.contextKey);

        if (context && source(context, sel_registerName("source")) == RCI_SOUND_CA_BY_APP)
            return;
        rci_media_backend_atomic_store(&rci_media_sound_ios.reactivate, 1);

        if (context && !rci_media_sound_ios_msg(context, "interruptionContext"))
            rci_media_sound_device_changed(false);
        else
            rci_media_sound_device_hold(RCI_SOUND_HOLD_INTERRUPTED, true);
    } else if (rci_media_sound_ios_is(note, rci_media_sound_ios.resumed)) {
        rci_media_sound_device_hold(RCI_SOUND_HOLD_INTERRUPTED, false);
    } else if (rci_media_sound_ios_is(note, rci_media_sound_ios.interrupted)) {
        unsigned long (*value)(id, SEL) = (unsigned long (*)(id, SEL))objc_msgSend;
        id            type = rci_media_sound_ios_info(note, rci_media_sound_ios.typeKey);
        const bool    began = type && value(type, sel_registerName("unsignedIntegerValue")) ==
                                          RCI_SOUND_CA_BEGAN;

        if (began)
            rci_media_backend_atomic_store(&rci_media_sound_ios.reactivate, 1);
        rci_media_sound_device_hold(RCI_SOUND_HOLD_INTERRUPTED, began);
    }
}

static void rci_media_sound_ios_on_hidden(id self, SEL cmd, id note) {
    (void)self;
    (void)cmd;
    (void)note;
    rci_media_sound_device_hold(RCI_SOUND_HOLD_HIDDEN, true);
}

static void rci_media_sound_ios_on_shown(id self, SEL cmd, id note) {
    (void)self;
    (void)cmd;
    (void)note;
    rci_media_sound_device_hold(RCI_SOUND_HOLD_HIDDEN, false);
}

static void rci_media_sound_ios_on_active(id self, SEL cmd, id note) {
    (void)self;
    (void)cmd;
    (void)note;
    rci_media_backend_atomic_store(&rci_media_sound_ios.reactivate, 1);
    rci_media_sound_device_hold(RCI_SOUND_HOLD_INTERRUPTED | RCI_SOUND_HOLD_HIDDEN, false);
}

static void rci_media_sound_ios_on_route(id self, SEL cmd, id note) {
    (void)self;
    (void)cmd;
    (void)note;
    rci_media_sound_device_changed(false);
}

static void rci_media_sound_ios_on_reset(id self, SEL cmd, id note) {
    (void)self;
    (void)cmd;
    (void)note;
    rci_media_backend_atomic_store(&rci_media_sound_ios.reactivate, 1);
    rci_media_sound_device_changed(true);
}

static void rci_media_sound_ios_observe(void) {
    static const struct {
        const char *sel;
        IMP         imp;
    } methods[] = {
        { "rcSoundSession:", (IMP)rci_media_sound_ios_on_session },
        { "rcSoundHidden:", (IMP)rci_media_sound_ios_on_hidden },
        { "rcSoundShown:", (IMP)rci_media_sound_ios_on_shown },
        { "rcSoundActive:", (IMP)rci_media_sound_ios_on_active },
        { "rcSoundRoute:", (IMP)rci_media_sound_ios_on_route },
        { "rcSoundReset:", (IMP)rci_media_sound_ios_on_reset },
    };
    void (*observe)(id, SEL, id, SEL, id, id) = (void (*)(id, SEL, id, SEL, id, id))objc_msgSend;
    void *avfa = dlopen("/System/Library/Frameworks/AVFAudio.framework/AVFAudio", RTLD_LAZY | RTLD_LOCAL);
    id    center, inactive, resumed;
    char  name[64];
    Class cls;
    const char *sel[8];
    id          note[8];
    int         n = 0;
    void       *pool;

    if (rci_media_sound_ios.observer || rci_media_sound_ca_test)
        return;
    snprintf(name, sizeof name, "RCISoundAppleObserver_%p", (void *)&rci_media_sound_ios);
    cls = objc_allocateClassPair(objc_getClass("NSObject"), name, 0);
    if (!cls)
        return;
    for (size_t i = 0; i < sizeof methods / sizeof *methods; i++)
        class_addMethod(cls, sel_registerName(methods[i].sel), methods[i].imp, "v@:@");
    objc_registerClassPair(cls);
    pool = objc_autoreleasePoolPush();
    rci_media_sound_ios.observer = rci_media_sound_ios_msg(rci_media_sound_ios_msg((id)cls, "alloc"), "init");
    if (!rci_media_sound_ios.observer) {
        objc_autoreleasePoolPop(pool);
        return;
    }

    inactive = rci_media_sound_ios_constant(avfa, "AVAudioSessionDidBecomeInactiveNotification");
    resumed  = rci_media_sound_ios_constant(avfa, "AVAudioSessionResumptionRecommendationNotification");
    if (inactive && resumed) {
        rci_media_sound_ios.inactive   = inactive;
        rci_media_sound_ios.resumed    = resumed;
        rci_media_sound_ios.contextKey = rci_media_sound_ios_constant(avfa, "AVAudioSessionDeactivationContextKey");
        sel[n] = "rcSoundSession:";
        note[n++] = inactive;
        sel[n] = "rcSoundSession:";
        note[n++] = resumed;
    } else {
        rci_media_sound_ios.interrupted = rci_media_sound_ios_constant(avfa, "AVAudioSessionInterruptionNotification");
        rci_media_sound_ios.typeKey     = rci_media_sound_ios_constant(avfa, "AVAudioSessionInterruptionTypeKey");
        sel[n] = "rcSoundSession:";
        note[n++] = rci_media_sound_ios.interrupted;
    }
    sel[n] = "rcSoundRoute:";
    note[n++] = rci_media_sound_ios_constant(avfa, "AVAudioSessionRouteChangeNotification");
    sel[n] = "rcSoundReset:";
    note[n++] = rci_media_sound_ios_constant(avfa, "AVAudioSessionMediaServicesWereResetNotification");
    sel[n] = "rcSoundHidden:";
    note[n++] = rci_media_sound_ios_constant(RCI_RTLD_ANY, "UIApplicationDidEnterBackgroundNotification");
    sel[n] = "rcSoundShown:";
    note[n++] = rci_media_sound_ios_constant(RCI_RTLD_ANY, "UIApplicationWillEnterForegroundNotification");
    sel[n] = "rcSoundActive:";
    note[n++] = rci_media_sound_ios_constant(RCI_RTLD_ANY, "UIApplicationDidBecomeActiveNotification");
    center = rci_media_sound_ios_msg((id)objc_getClass("NSNotificationCenter"), "defaultCenter");
    for (int i = 0; i < n; i++) {
        if (note[i])
            observe(center, sel_registerName("addObserver:selector:name:object:"),
                    rci_media_sound_ios.observer, sel_registerName(sel[i]), note[i], nil);
    }
    objc_autoreleasePoolPop(pool);
}
#endif

static const RCI_SoundCaAddress rci_media_sound_ca_default = {
    RCI_SOUND_CA_FOURCC('d', 'O', 'u', 't'),
    RCI_SOUND_CA_FOURCC('g', 'l', 'o', 'b'),
    0
};

static int32_t rci_media_sound_ca_moved(uint32_t object, uint32_t count, const void *at, void *user) {
    (void)object;
    (void)count;
    (void)at;
    (void)user;
    rci_media_sound_device_changed(false);
    return 0;
}

static bool rci_media_sound_ca_configure(int *rate) {
    const RCI_SoundCaApi *a = &rci_media_sound_ca_api;
    RCI_SoundCaFormat     hw, fmt;
    uint32_t              size = sizeof hw;

    memset(&hw, 0, sizeof hw);
    if (a->get(rci_media_sound_ca_unit, RCI_SOUND_CA_PROP_FORMAT, RCI_SOUND_CA_SCOPE_OUTPUT, 0, &hw, &size) != 0 ||
        !(hw.sampleRate >= 8000.0 && hw.sampleRate <= 384000.0))
        hw.sampleRate = 48000.0;
    memset(&fmt, 0, sizeof fmt);
    fmt.sampleRate       = hw.sampleRate;
    fmt.formatId         = RCI_SOUND_CA_FOURCC('l', 'p', 'c', 'm');
    fmt.formatFlags      = RCI_SOUND_CA_FLOAT_PACKED;
    fmt.bytesPerPacket   = 2 * sizeof(float);
    fmt.framesPerPacket  = 1;
    fmt.bytesPerFrame    = 2 * sizeof(float);
    fmt.channelsPerFrame = 2;
    fmt.bitsPerChannel   = 32;
    if (a->set(rci_media_sound_ca_unit, RCI_SOUND_CA_PROP_FORMAT, RCI_SOUND_CA_SCOPE_INPUT, 0, &fmt,
               sizeof fmt) != 0 || a->init(rci_media_sound_ca_unit) != 0)
        return false;
    *rate = (int)hw.sampleRate;
    return true;
}

static void rci_media_sound_ca_close(void) {
    const RCI_SoundCaApi *a = &rci_media_sound_ca_api;

    if (rci_media_sound_ca_listening && a->unlisten)
        a->unlisten(RCI_SOUND_CA_SYSTEM, &rci_media_sound_ca_default, rci_media_sound_ca_moved, NULL);
    rci_media_sound_ca_listening = false;
    if (rci_media_sound_ca_unit) {
        a->uninit(rci_media_sound_ca_unit);
        a->dispose(rci_media_sound_ca_unit);
        rci_media_sound_ca_unit = NULL;
    }
}

static bool rci_media_sound_ca_open(int *rate, char *why) {
    const RCI_SoundCaApi *a = &rci_media_sound_ca_api;
    RCI_SoundCaDesc       desc;
    RCI_SoundCaCallback   cb;
    void                 *component;

    if (!rci_media_sound_ca_load(why))
        return false;
#if TARGET_OS_IPHONE
    rci_media_sound_ios_observe();
    if (!rci_media_sound_ca_test) {

        rci_media_backend_atomic_store(&rci_media_sound_ios.reactivate, 0);
        rci_media_session_sync();
        if (!rci_media_session_activate())
            rci_media_backend_atomic_store(&rci_media_sound_ios.reactivate, 1);
    }
#endif
    memset(&desc, 0, sizeof desc);
    desc.type         = RCI_SOUND_CA_FOURCC('a', 'u', 'o', 'u');
#if TARGET_OS_IPHONE
    desc.subType      = RCI_SOUND_CA_FOURCC('r', 'i', 'o', 'c');
#else
    desc.subType      = RCI_SOUND_CA_FOURCC('d', 'e', 'f', ' ');
#endif
    desc.manufacturer = RCI_SOUND_CA_FOURCC('a', 'p', 'p', 'l');
    component = a->find(NULL, &desc);
    if (!component || a->make(component, &rci_media_sound_ca_unit) != 0 || !rci_media_sound_ca_unit) {
        rci_media_sound_ca_unit = NULL;
        snprintf(why, RCI_SOUND_DETAIL_MAX, "%s", "no CoreAudio output unit");
        return false;
    }
    cb.proc = rci_media_sound_ca_render;
    cb.ref  = NULL;
    if (a->set(rci_media_sound_ca_unit, RCI_SOUND_CA_PROP_RENDER, RCI_SOUND_CA_SCOPE_INPUT, 0, &cb,
               sizeof cb) != 0 || !rci_media_sound_ca_configure(rate)) {
        a->dispose(rci_media_sound_ca_unit);
        rci_media_sound_ca_unit = NULL;
        snprintf(why, RCI_SOUND_DETAIL_MAX, "%s", "the CoreAudio output refused stereo float");
        return false;
    }
#if !TARGET_OS_IPHONE
    rci_media_sound_ca_listening = a->listen && a->listen(RCI_SOUND_CA_SYSTEM, &rci_media_sound_ca_default,
                                                    rci_media_sound_ca_moved, NULL) == 0;
#endif
    return true;
}

static bool rci_media_sound_ca_start(void) {
#if TARGET_OS_IPHONE
    if (!rci_media_sound_ca_test && rci_media_backend_atomic_load(&rci_media_sound_ios.reactivate)) {
        rci_media_backend_atomic_store(&rci_media_sound_ios.reactivate, 0);
        rci_media_session_sync();
        if (!rci_media_session_activate())
            rci_media_backend_atomic_store(&rci_media_sound_ios.reactivate, 1);
    }
#endif
    return rci_media_sound_ca_unit && rci_media_sound_ca_api.start(rci_media_sound_ca_unit) == 0;
}

static void rci_media_sound_ca_stop(void) {
    if (rci_media_sound_ca_unit)
        rci_media_sound_ca_api.stop(rci_media_sound_ca_unit);
}

static bool rci_media_sound_ca_retune(int *rate) {
    if (!rci_media_sound_ca_unit)
        return false;
    rci_media_sound_ca_api.uninit(rci_media_sound_ca_unit);
    return rci_media_sound_ca_configure(rate);
}

const RCI_SoundDevice rci_media_sound_apple_device = {
    "CoreAudio", rci_media_sound_ca_open, rci_media_sound_ca_start, rci_media_sound_ca_stop, rci_media_sound_ca_close,
    rci_media_sound_ca_retune
};

#endif

