static const RCI_FilesBackend rci_files_cocoa_provider = {
    rci_files_cocoa_show, rci_files_cocoa_close, rci_files_cocoa_release, NULL, false, false, NULL
};

const RCI_FilesBackend *rci_files_cocoa_backend(void);
const RCI_FilesBackend *rci_files_cocoa_backend(void) {
    return &rci_files_cocoa_provider;
}

