RC_FileStatus rcSaveFile(const char *path, const void *bytes, size_t length, unsigned flags) {
    if (!rci_storage_path(path) || (!bytes && length) || (flags & ~RCI_STORAGE_SAVE_FLAGS))
        return RC_FILE_INVALID;
    return rci_storage_save(path, (const unsigned char *)bytes, length, flags);
}

RC_FileStatus rcPathInfo(const char *path, RC_PathInfo *out) {
    RC_PathInfo info;
    RC_FileStatus status = RC_FILE_INVALID;

    memset(&info, 0, sizeof info);
    if (rci_storage_path(path))
        status = rci_storage_info(path, &info);
    if (status != RC_FILE_OK)
        memset(&info, 0, sizeof info);
    if (out)
        *out = info;
    return status;
}

RC_FileStatus rcMakeDirectory(const char *path, unsigned flags) {
    if (!rci_storage_path(path) || (flags & ~RCI_STORAGE_FLAGS))
        return RC_FILE_INVALID;
    return rci_storage_make(path, flags);
}

RC_FileStatus rcRemovePath(const char *path, unsigned flags) {
    if (!rci_storage_path(path) || (flags & ~(unsigned)RC_FILE_RECURSIVE))
        return RC_FILE_INVALID;
    return rci_storage_remove(path, flags);
}

RC_FileStatus rcListDirectory(const char *path, RC_DirectoryEntryCallback callback,
                              void *userData) {
    if (!rci_storage_path(path) || !callback)
        return RC_FILE_INVALID;
    return rci_storage_list(path, callback, userData);
}

#include <string.h>

#if defined(_WIN32)
#  ifndef WIN32_LEAN_AND_MEAN
#    define WIN32_LEAN_AND_MEAN
#  endif
#  include <windows.h>
#else
#  include <time.h>
#  if defined(__EMSCRIPTEN__)
#    include <emscripten.h>
#  endif
#endif

#define RCI_TIME_MS_MIN (-INT64_C(62167219200000))
#define RCI_TIME_MS_MAX INT64_C(253402300799999)
#define RCI_TIME_MS_DAY INT64_C(86400000)
#define RCI_TIME_ISO_LENGTH 24u

double rcMonotonicSeconds(void) {
#if defined(_WIN32)
    LARGE_INTEGER count, rate;

    QueryPerformanceFrequency(&rate);
    QueryPerformanceCounter(&count);
    return (double)(count.QuadPart / rate.QuadPart) +
           (double)(count.QuadPart % rate.QuadPart) / (double)rate.QuadPart;
#elif defined(__EMSCRIPTEN__)
    return emscripten_get_now() / 1000.0;
#elif defined(CLOCK_MONOTONIC)
    struct timespec ts;

#  if defined(CLOCK_BOOTTIME)
    if (clock_gettime(CLOCK_BOOTTIME, &ts) == 0)
        return (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
#  endif
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
        return 0.0;
    return (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
#else
    return 0.0;
#endif
}

double rcUnixTimeSeconds(void) {
#if defined(_WIN32)

    FILETIME       ft;
    ULARGE_INTEGER u;
    GetSystemTimeAsFileTime(&ft);
    u.LowPart  = ft.dwLowDateTime;
    u.HighPart = ft.dwHighDateTime;
    return ((double)u.QuadPart - 116444736000000000.0) / 1e7;
#elif defined(CLOCK_REALTIME)

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0)
        return 0.0;
    return (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
#else

    time_t t = time(NULL);
    return (t == (time_t)-1) ? 0.0 : (double)t;
#endif
}

static int rci_time_digits(const char *p, int count) {
    int v = 0;

    while (count-- > 0) {
        if (*p < '0' || *p > '9')
            return -1;
        v = v * 10 + (*p++ - '0');
    }
    return v;
}

static int64_t rci_time_days(int64_t y, int m, int d) {
    int64_t era;
    int yoe, doy, doe;

    y  -= m <= 2;
    era = (y >= 0 ? y : y - 399) / 400;
    yoe = (int)(y - era * 400);
    doy = (153 * (m > 2 ? m - 3 : m + 9) + 2) / 5 + d - 1;
    doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    return era * 146097 + doe - 719468;
}

static void rci_time_civil(int64_t z, int *y, int *m, int *d) {
    int64_t era;
    int doe, yoe, doy, mp;

    z  += 719468;
    era = (z >= 0 ? z : z - 146096) / 146097;
    doe = (int)(z - era * 146097);
    yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    mp  = (5 * doy + 2) / 153;
    *d  = doy - (153 * mp + 2) / 5 + 1;
    *m  = mp < 10 ? mp + 3 : mp - 9;
    *y  = (int)(yoe + era * 400 + (*m <= 2));
}

bool rcTimeParse(const char *text, size_t length, double *unixSeconds) {
    static const int days_in[12] = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    int y, mo, d, h, mi, s, offset = 0;
    long nanos = 0, scale = 1000000000L;
    size_t i = 19;

    if (!text)
        return false;
    if (length == 0)
        length = strlen(text);

    if (length < 20)
        return false;
    y  = rci_time_digits(text, 4);
    mo = rci_time_digits(text + 5, 2);
    d  = rci_time_digits(text + 8, 2);
    h  = rci_time_digits(text + 11, 2);
    mi = rci_time_digits(text + 14, 2);
    s  = rci_time_digits(text + 17, 2);
    if (y < 0 || mo < 1 || mo > 12 || d < 1 || h < 0 || h > 23 || mi < 0 || mi > 59 ||
        s < 0 || s > 60 || text[4] != '-' || text[7] != '-' ||
        (text[10] != 'T' && text[10] != 't' && text[10] != ' ') || text[13] != ':' ||
        text[16] != ':')
        return false;
    if (d > days_in[mo - 1] + (mo == 2 && ((y % 4 == 0 && y % 100 != 0) || y % 400 == 0)))
        return false;
    if (text[i] == '.') {
        size_t first = ++i;

        for (; i < length && text[i] >= '0' && text[i] <= '9'; i++) {
            if (scale > 1) {
                scale /= 10;
                nanos += (text[i] - '0') * scale;
            }
        }
        if (i == first || i == length)
            return false;
    }
    if (text[i] == 'Z' || text[i] == 'z') {
        i++;
    } else if (text[i] == '+' || text[i] == '-') {

        size_t n = length - i - 1;
        int oh = n >= 2 ? rci_time_digits(text + i + 1, 2) : -1;
        int om = -1;

        if (n == 2)
            om = 0;
        else if (n == 4)
            om = rci_time_digits(text + i + 3, 2);
        else if (n == 5 && text[i + 3] == ':')
            om = rci_time_digits(text + i + 4, 2);
        if (oh < 0 || oh > 23 || om < 0 || om > 59)
            return false;
        offset = (oh * 60 + om) * 60 * (text[i] == '+' ? 1 : -1);
        i = length;
    } else {
        return false;
    }
    if (i != length)
        return false;
    if (unixSeconds)
        *unixSeconds = (double)(rci_time_days(y, mo, d) * 86400 + h * 3600 + mi * 60 + s -
                                offset) + (double)nanos / 1e9;
    return true;
}

static char *rci_time_put(char *p, int value, int count) {
    int k;

    for (k = count - 1; k >= 0; k--, value /= 10)
        p[k] = (char)('0' + value % 10);
    return p + count;
}

size_t rcTimeFormatUtc(char *buffer, size_t capacity, double unixSeconds) {
    char    text[RCI_TIME_ISO_LENGTH + 1], *p = text;
    double  ms = unixSeconds * 1000.0;
    int64_t whole, days, rest;
    int     y, m, d;

    if (!(ms > (double)RCI_TIME_MS_MIN - 0.5 && ms < (double)RCI_TIME_MS_MAX + 0.5)) {
        if (buffer && capacity > 0)
            buffer[0] = '\0';
        return 0;
    }
    whole = (int64_t)(ms < 0.0 ? ms - 0.5 : ms + 0.5);
    days  = whole / RCI_TIME_MS_DAY;
    rest  = whole % RCI_TIME_MS_DAY;
    if (rest < 0) {
        rest += RCI_TIME_MS_DAY;
        days--;
    }
    rci_time_civil(days, &y, &m, &d);
    p    = rci_time_put(p, y, 4);
    *p++ = '-';
    p    = rci_time_put(p, m, 2);
    *p++ = '-';
    p    = rci_time_put(p, d, 2);
    *p++ = 'T';
    p    = rci_time_put(p, (int)(rest / 3600000), 2);
    *p++ = ':';
    p    = rci_time_put(p, (int)(rest / 60000 % 60), 2);
    *p++ = ':';
    p    = rci_time_put(p, (int)(rest / 1000 % 60), 2);
    *p++ = '.';
    p    = rci_time_put(p, (int)(rest % 1000), 3);
    *p++ = 'Z';
    *p   = '\0';

    if (buffer && capacity > 0) {
        if (capacity > RCI_TIME_ISO_LENGTH)
            memcpy(buffer, text, sizeof text);
        else
            buffer[0] = '\0';
    }
    return RCI_TIME_ISO_LENGTH;
}

