static int64_t rci_localtime_days(int64_t y, int m, int d) {
    int64_t era;
    int yoe, doy, doe;

    y  -= m <= 2;
    era = (y >= 0 ? y : y - 399) / 400;
    yoe = (int)(y - era * 400);
    doy = (153 * (m > 2 ? m - 3 : m + 9) + 2) / 5 + d - 1;
    doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    return era * 146097 + doe - 719468;
}

static void rci_localtime_fill(RC_LocalTime *out, int year, int month, int day, int hour,
                               int minute, int second, int64_t when) {
    const int64_t days = rci_localtime_days(year, month, day);
    const int64_t local = days * 86400 + hour * 3600 + minute * 60 + (second > 59 ? 59 : second);

    out->year             = year;
    out->month            = month;
    out->day              = day;
    out->hour             = hour;
    out->minute           = minute;
    out->second           = second;
    out->weekday          = (int)(((days % 7) + 11) % 7);
    out->yearDay          = (int)(days - rci_localtime_days(year, 1, 1));
    out->utcOffsetSeconds = (int)(local - when);
}

bool rcLocalTime(double unixSeconds, RC_LocalTime *out) {
    int64_t when;

    if (!out)
        return false;
    memset(out, 0, sizeof *out);

    if (!(unixSeconds >= -11644473600.0 && unixSeconds < 253402300800.0))
        return false;
    when = (int64_t)unixSeconds;
    if ((double)when > unixSeconds)
        when--;
#if RCI_LOCALTIME_WIN32
    {

        const uint64_t ticks = (uint64_t)(when + INT64_C(11644473600)) * UINT64_C(10000000);
        DYNAMIC_TIME_ZONE_INFORMATION zone;
        TIME_ZONE_INFORMATION year;
        SYSTEMTIME utc, local;
        FILETIME ft;

        ft.dwLowDateTime  = (DWORD)(ticks & 0xFFFFFFFFu);
        ft.dwHighDateTime = (DWORD)(ticks >> 32);
        if (!FileTimeToSystemTime(&ft, &utc) ||
            GetDynamicTimeZoneInformation(&zone) == TIME_ZONE_ID_INVALID ||
            !SystemTimeToTzSpecificLocalTimeEx(&zone, &utc, &local))
            return false;
        rci_localtime_fill(out, local.wYear, local.wMonth, local.wDay, local.wHour,
                           local.wMinute, local.wSecond, when);
        if (GetTimeZoneInformationForYear(local.wYear, &zone, &year))
            out->daylightSaving = out->utcOffsetSeconds != -(year.Bias + year.StandardBias) * 60;
    }
#else
    {
        const time_t t = (time_t)when;
        struct tm    tm;

        if ((int64_t)t != when)
            return false;
#  if RCI_LOCALTIME_POSIX
        if (!localtime_r(&t, &tm))
            return false;
#  else
        {

            const struct tm *shared = localtime(&t);

            if (!shared)
                return false;
            tm = *shared;
        }
#  endif
        rci_localtime_fill(out, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour,
                           tm.tm_min, tm.tm_sec, when);
        out->daylightSaving = tm.tm_isdst > 0;
    }
#endif
    return true;
}

