#elif defined(NTBI_BUILD_LINUX)

#ifndef NTB_NO_X11
#include <X11/Xlib.h>
#include <X11/Xutil.h>
#include <X11/Xatom.h>
#include <limits.h>

enum {
    NTBI_MR_SIZE_TOPLEFT = 0, NTBI_MR_SIZE_TOP = 1, NTBI_MR_SIZE_TOPRIGHT = 2,
    NTBI_MR_SIZE_RIGHT = 3,   NTBI_MR_SIZE_BOTTOMRIGHT = 4, NTBI_MR_SIZE_BOTTOM = 5,
    NTBI_MR_SIZE_BOTTOMLEFT = 6, NTBI_MR_SIZE_LEFT = 7, NTBI_MR_MOVE = 8
};

static int ntbi_x11_dir_from_edge(ntb_edge e) {
    switch (e) {
    case NTB_EDGE_TOP:         return NTBI_MR_SIZE_TOP;
    case NTB_EDGE_BOTTOM:      return NTBI_MR_SIZE_BOTTOM;
    case NTB_EDGE_LEFT:        return NTBI_MR_SIZE_LEFT;
    case NTB_EDGE_RIGHT:       return NTBI_MR_SIZE_RIGHT;
    case NTB_EDGE_TOPLEFT:     return NTBI_MR_SIZE_TOPLEFT;
    case NTB_EDGE_TOPRIGHT:    return NTBI_MR_SIZE_TOPRIGHT;
    case NTB_EDGE_BOTTOMLEFT:  return NTBI_MR_SIZE_BOTTOMLEFT;
    case NTB_EDGE_BOTTOMRIGHT: return NTBI_MR_SIZE_BOTTOMRIGHT;
    }
    return NTBI_MR_MOVE;
}

static int ntbi_x11_install(ntb_native_window w) {
    Display *dpy = (Display *)w.x11_display; Window win = (Window)w.x11_window;
    if (!dpy || !win) return 0;
    struct { unsigned long flags, functions, decorations; long input_mode; unsigned long status; }
        hints; memset(&hints, 0, sizeof hints);
    hints.flags = (1L << 1);
    hints.decorations = 0;
    Atom motif = XInternAtom(dpy, "_MOTIF_WM_HINTS", False);
    XChangeProperty(dpy, win, motif, motif, 32, PropModeReplace,
                    (unsigned char *)&hints, 5);
    XFlush(dpy);
    return 1;
}

static int ntbi_x11_moveresize(ntb_native_window w, int direction) {
    Display *dpy = (Display *)w.x11_display; Window win = (Window)w.x11_window;
    if (!dpy || !win) return 0;
    Window root = DefaultRootWindow(dpy), child;
    int rx = 0, ry = 0, wx = 0, wy = 0; unsigned mask = 0;

    XQueryPointer(dpy, win, &root, &child, &rx, &ry, &wx, &wy, &mask);

    if (!(mask & Button1Mask)) return 0;
    XUngrabPointer(dpy, CurrentTime);
    XEvent ev; memset(&ev, 0, sizeof ev);
    ev.xclient.type = ClientMessage;
    ev.xclient.message_type = XInternAtom(dpy, "_NET_WM_MOVERESIZE", False);
    ev.xclient.display = dpy; ev.xclient.window = win; ev.xclient.format = 32;
    ev.xclient.data.l[0] = rx; ev.xclient.data.l[1] = ry;
    ev.xclient.data.l[2] = direction;
    ev.xclient.data.l[3] = Button1; ev.xclient.data.l[4] = 1;
    XSendEvent(dpy, root, False,
               SubstructureRedirectMask | SubstructureNotifyMask, &ev);
    XFlush(dpy);
    return 1;
}

static void ntbi_x11_set_state(ntb_native_window w, const char *atom, int add) {
    Display *dpy = (Display *)w.x11_display; Window win = (Window)w.x11_window;
    XEvent ev; memset(&ev, 0, sizeof ev);
    ev.xclient.type = ClientMessage;
    ev.xclient.message_type = XInternAtom(dpy, "_NET_WM_STATE", False);
    ev.xclient.display = dpy; ev.xclient.window = win; ev.xclient.format = 32;
    ev.xclient.data.l[0] = add ? 1 : 0;
    ev.xclient.data.l[1] = (long)XInternAtom(dpy, atom, False);
    ev.xclient.data.l[2] = 0; ev.xclient.data.l[3] = 1;
    XSendEvent(dpy, DefaultRootWindow(dpy), False,
               SubstructureRedirectMask | SubstructureNotifyMask, &ev);
    XFlush(dpy);
}

static int ntbi_x11_set_max(ntb_native_window w, int on) {
    if (!w.x11_display || !w.x11_window) return 0;
    ntbi_x11_set_state(w, "_NET_WM_STATE_MAXIMIZED_VERT", on);
    ntbi_x11_set_state(w, "_NET_WM_STATE_MAXIMIZED_HORZ", on);
    return 1;
}

static int ntbi_x11_is_max(ntb_native_window w) {
    Display *dpy = (Display *)w.x11_display; Window win = (Window)w.x11_window;
    if (!dpy || !win) return 0;
    Atom state = XInternAtom(dpy, "_NET_WM_STATE", False);
    Atom mv = XInternAtom(dpy, "_NET_WM_STATE_MAXIMIZED_VERT", False);
    Atom mh = XInternAtom(dpy, "_NET_WM_STATE_MAXIMIZED_HORZ", False);
    Atom actual; int fmt; unsigned long n = 0, after = 0; unsigned char *data = 0;
    int have_v = 0, have_h = 0;

    if (XGetWindowProperty(dpy, win, state, 0, LONG_MAX, False, XA_ATOM,
            &actual, &fmt, &n, &after, &data) == Success && data) {
        Atom *atoms = (Atom *)data;
        for (unsigned long i = 0; i < n; i++) {
            if (atoms[i] == mv) have_v = 1;
            else if (atoms[i] == mh) have_h = 1;
            if (have_v && have_h) break;
        }
        XFree(data);
    }

    return have_v && have_h;
}

static int ntbi_x11_wm_supports(ntb_native_window w, const char *atom,
                                int *list_present) {
    Display *dpy = (Display *)w.x11_display;
    Atom supported, want, actual;
    int fmt; unsigned long n = 0, after = 0; unsigned char *data = 0;
    int found = 0;
    if (list_present) *list_present = 0;
    if (!dpy) return 0;
    supported = XInternAtom(dpy, "_NET_SUPPORTED", False);
    want      = XInternAtom(dpy, atom, False);
    if (XGetWindowProperty(dpy, DefaultRootWindow(dpy), supported, 0, LONG_MAX,
            False, XA_ATOM, &actual, &fmt, &n, &after, &data) == Success && data) {
        Atom *atoms = (Atom *)data;
        if (list_present) *list_present = 1;
        for (unsigned long i = 0; i < n; i++)
            if (atoms[i] == want) { found = 1; break; }
        XFree(data);
    }
    return found;
}

static int ntbi_x11_has_wm(ntb_native_window w) {
    Display *dpy = (Display *)w.x11_display;
    Atom check, actual;
    int fmt; unsigned long n = 0, after = 0; unsigned char *data = 0;
    int live = 0;
    if (!dpy) return 0;
    check = XInternAtom(dpy, "_NET_SUPPORTING_WM_CHECK", False);
    if (XGetWindowProperty(dpy, DefaultRootWindow(dpy), check, 0, 1, False,
            XA_WINDOW, &actual, &fmt, &n, &after, &data) == Success && data) {
        live = (n >= 1 && *(Window *)data != 0);
        XFree(data);
    }
    return live;
}

static int ntbi_x11_topmost_permitted(ntb_native_window w) {
    int list_present = 0;
    if (ntbi_x11_wm_supports(w, "_NET_WM_STATE_ABOVE", &list_present)) return 1;
    return list_present ? 0 : ntbi_x11_has_wm(w);
}

static int ntbi_x11_has_state(ntb_native_window w, const char *atom) {
    Display *dpy = (Display *)w.x11_display; Window win = (Window)w.x11_window;
    Atom state, want, actual;
    int fmt; unsigned long n = 0, after = 0; unsigned char *data = 0;
    int found = 0;
    if (!dpy || !win) return 0;
    state = XInternAtom(dpy, "_NET_WM_STATE", False);
    want  = XInternAtom(dpy, atom, False);
    if (XGetWindowProperty(dpy, win, state, 0, LONG_MAX, False, XA_ATOM,
            &actual, &fmt, &n, &after, &data) == Success && data) {
        Atom *atoms = (Atom *)data;
        for (unsigned long i = 0; i < n; i++)
            if (atoms[i] == want) { found = 1; break; }
        XFree(data);
    }
    return found;
}

static int ntbi_x11_minimize(ntb_native_window w) {
    Display *dpy = (Display *)w.x11_display; Window win = (Window)w.x11_window;
    if (!dpy || !win) return 0;
    XIconifyWindow(dpy, win, DefaultScreen(dpy)); XFlush(dpy);
    return 1;
}
#endif

static int ntbi_wayland_install_nothing_to_remove(void) { return 1; }

static int ntbi_native_install(ntb_native_window w, ntb_config cfg) {
    (void)cfg;
    switch (ntbi_resolve(w)) {
#ifndef NTB_NO_X11
    case NTB_PLATFORM_X11:     return ntbi_x11_install(w);
#endif
    case NTB_PLATFORM_WAYLAND: return ntbi_wayland_install_nothing_to_remove();
    default:                   return 0;
    }
}
