static int ntbi_native_minimize(ntb_native_window w) {
#ifndef NTB_NO_X11
    if (ntbi_resolve(w) == NTB_PLATFORM_X11) return ntbi_x11_minimize(w);
#endif
    (void)w; return 0;
}

static int ntbi_native_max_hover(ntb_native_window w) { (void)w; return 0; }
static int ntbi_native_max_press(ntb_native_window w) { (void)w; return 0; }
static unsigned ntbi_native_max_clicks(ntb_native_window w) { (void)w; return 0; }

static unsigned ntbi_native_caps(ntb_native_window w) {
    switch (ntbi_resolve(w)) {
#ifndef NTB_NO_X11
    case NTB_PLATFORM_X11:

        if (!w.x11_display || !w.x11_window) return 0;

        return NTB_CAP_REMOVE_TITLEBAR | NTB_CAP_MOVE | NTB_CAP_RESIZE |
               NTB_CAP_MAXIMIZE | NTB_CAP_TOPMOST | NTB_CAP_MINIMIZE;
#endif
    case NTB_PLATFORM_WAYLAND: {
        unsigned c = NTB_CAP_NEEDS_UNDECORATED_AT_CREATE;
        if (w.hooks.start_move)    c |= NTB_CAP_MOVE;
        if (w.hooks.start_resize)  c |= NTB_CAP_RESIZE;
        if (w.hooks.set_maximized) c |= NTB_CAP_MAXIMIZE;

        if (w.hooks.minimize)      c |= NTB_CAP_MINIMIZE;
        return c;
    }
    default: return 0;
    }
}

#elif defined(NTBI_BUILD_MACOS)

#include <objc/objc.h>
#include <objc/runtime.h>
#include <objc/message.h>
#include <time.h>

typedef long          ntbi_nsint;
typedef unsigned long ntbi_nsuint;

enum { NTBI_STYLE_RESIZABLE = 1u << 3,
       NTBI_STYLE_FULLSIZECONTENTVIEW = 1u << 15 };

enum { NTBI_LEVEL_NORMAL = 0, NTBI_LEVEL_FLOATING = 3 };
enum { NTBI_TITLE_VISIBLE = 0, NTBI_TITLE_HIDDEN = 1 };
enum { NTBI_BTN_CLOSE = 0, NTBI_BTN_MINIATURIZE = 1, NTBI_BTN_ZOOM = 2 };

static id ntbi_msg_id(id o, const char *sel) {
    id (*typed_send)(id, SEL) = (id (*)(id, SEL))objc_msgSend;
    return typed_send(o, sel_registerName(sel));
}
static id ntbi_msg_id_int(id o, const char *sel, ntbi_nsint a) {
    id (*typed_send)(id, SEL, ntbi_nsint) =
        (id (*)(id, SEL, ntbi_nsint))objc_msgSend;
    return typed_send(o, sel_registerName(sel), a);
}
static void ntbi_msg_void_id(id o, const char *sel, id a) {
    void (*typed_send)(id, SEL, id) = (void (*)(id, SEL, id))objc_msgSend;
    typed_send(o, sel_registerName(sel), a);
}
static void ntbi_msg_void_bool(id o, const char *sel, BOOL a) {
    void (*typed_send)(id, SEL, BOOL) = (void (*)(id, SEL, BOOL))objc_msgSend;
    typed_send(o, sel_registerName(sel), a);
}
static void ntbi_msg_void_int(id o, const char *sel, ntbi_nsint a) {
    void (*typed_send)(id, SEL, ntbi_nsint) =
        (void (*)(id, SEL, ntbi_nsint))objc_msgSend;
    typed_send(o, sel_registerName(sel), a);
}
static void ntbi_msg_void_uint(id o, const char *sel, ntbi_nsuint a) {
    void (*typed_send)(id, SEL, ntbi_nsuint) =
        (void (*)(id, SEL, ntbi_nsuint))objc_msgSend;
    typed_send(o, sel_registerName(sel), a);
}
static ntbi_nsuint ntbi_msg_uint(id o, const char *sel) {
    ntbi_nsuint (*typed_send)(id, SEL) =
        (ntbi_nsuint (*)(id, SEL))objc_msgSend;
    return typed_send(o, sel_registerName(sel));
}

static ntbi_nsint ntbi_msg_int(id o, const char *sel) {
    ntbi_nsint (*typed_send)(id, SEL) =
        (ntbi_nsint (*)(id, SEL))objc_msgSend;
    return typed_send(o, sel_registerName(sel));
}
static BOOL ntbi_msg_bool(id o, const char *sel) {
    BOOL (*typed_send)(id, SEL) = (BOOL (*)(id, SEL))objc_msgSend;
    return typed_send(o, sel_registerName(sel));
}
static BOOL ntbi_msg_bool_id(id o, const char *sel, id a) {
    BOOL (*typed_send)(id, SEL, id) = (BOOL (*)(id, SEL, id))objc_msgSend;
    return typed_send(o, sel_registerName(sel), a);
}

typedef struct ntbi_nsrect { double x, y, w, h; } ntbi_nsrect;

static ntbi_nsrect ntbi_msg_rect(id o, const char *sel) {
#if defined(__x86_64__)
    ntbi_nsrect (*typed_send)(id, SEL) =
        (ntbi_nsrect (*)(id, SEL))objc_msgSend_stret;
#else
    ntbi_nsrect (*typed_send)(id, SEL) =
        (ntbi_nsrect (*)(id, SEL))objc_msgSend;
#endif
    return typed_send(o, sel_registerName(sel));
}

static void ntbi_msg_set_frame_display(id o, ntbi_nsrect r, BOOL display) {
    void (*typed_send)(id, SEL, ntbi_nsrect, BOOL) =
        (void (*)(id, SEL, ntbi_nsrect, BOOL))objc_msgSend;
    typed_send(o, sel_registerName("setFrame:display:"), r, display);
}

static int ntbi_rect_eq(ntbi_nsrect a, ntbi_nsrect b) {
    double dx = a.x - b.x, dy = a.y - b.y, dw = a.w - b.w, dh = a.h - b.h;

    if (dx < 0) dx = -dx;
    if (dy < 0) dy = -dy;
    if (dw < 0) dw = -dw;
    if (dh < 0) dh = -dh;
    return dx < 1.0 && dy < 1.0 && dw < 1.0 && dh < 1.0;
}

#ifndef NTB_MACOS_ZOOM_SLOTS
#define NTB_MACOS_ZOOM_SLOTS 8
#endif

#define NTBI_MACOS_ZOOM_FLIGHT_S 0.40

static double ntbi_macos_now(void) {
    struct timespec ts;

    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
        return 1e300;
    return (double)ts.tv_sec + (double)ts.tv_nsec * 1e-9;
}

enum {
    NTBI_MACOS_FLIGHT_NONE    = 0,
    NTBI_MACOS_FLIGHT_ZOOM    = 1,
    NTBI_MACOS_FLIGHT_RESTORE = 2
};

typedef struct ntbi_macos_zoom {
    id          window;
    ntbi_nsrect restored;
    ntbi_nsrect zoomed;
    double      deadline;
    int         flight;
    int         confirmed;
} ntbi_macos_zoom;

static ntbi_macos_zoom ntbi_macos_zoom_slots[NTB_MACOS_ZOOM_SLOTS];

static ntbi_macos_zoom *ntbi_macos_zoom_find(id w) {
    if (!w)
        return (ntbi_macos_zoom *)0;
    for (int i = 0; i < NTB_MACOS_ZOOM_SLOTS; i++)
        if (ntbi_macos_zoom_slots[i].window == w)
            return &ntbi_macos_zoom_slots[i];
    return (ntbi_macos_zoom *)0;
}

static ntbi_macos_zoom *ntbi_macos_zoom_take(int i, id w) {
    ntbi_macos_zoom *s = &ntbi_macos_zoom_slots[i];

    s->window    = w;
    s->deadline  = 0.0;
    s->flight    = NTBI_MACOS_FLIGHT_NONE;
    s->confirmed = 0;
    return s;
}

static ntbi_macos_zoom *ntbi_macos_zoom_claim(id w) {
    ntbi_macos_zoom *s = ntbi_macos_zoom_find(w);

    if (s)
        return s;
    for (int i = 0; i < NTB_MACOS_ZOOM_SLOTS; i++) {
        if (!ntbi_macos_zoom_slots[i].window)
            return ntbi_macos_zoom_take(i, w);
    }

    for (int i = 0; i < NTB_MACOS_ZOOM_SLOTS; i++) {
        ntbi_macos_zoom *o = &ntbi_macos_zoom_slots[i];

        if (o->flight == NTBI_MACOS_FLIGHT_RESTORE && ntbi_macos_now() >= o->deadline)
            return ntbi_macos_zoom_take(i, w);
    }

    return (ntbi_macos_zoom *)0;
}

static void ntbi_macos_zoom_release(id w) {
    ntbi_macos_zoom *s = ntbi_macos_zoom_find(w);

    if (s) {
        s->window   = 0;

        s->deadline  = 0.0;
        s->flight    = NTBI_MACOS_FLIGHT_NONE;
        s->confirmed = 0;
    }
}

static int ntbi_macos_flight_landed(const ntbi_macos_zoom *s, ntbi_nsrect f) {
    ntbi_nsrect target;

    if (s->flight == NTBI_MACOS_FLIGHT_NONE)
        return 1;
    target = (s->flight == NTBI_MACOS_FLIGHT_RESTORE) ? s->restored : s->zoomed;
    if (ntbi_rect_eq(f, target))
        return 1;
    return ntbi_macos_now() >= s->deadline;
}

static int ntbi_macos_zoom_on_its_way(const ntbi_macos_zoom *s, ntbi_nsrect f);

static int ntbi_macos_zoom_settle(ntbi_macos_zoom *s, id w) {
    ntbi_nsrect f;

    if (s->flight == NTBI_MACOS_FLIGHT_NONE)
        return 1;
    f = ntbi_msg_rect(w, "frame");
    if (!ntbi_macos_flight_landed(s, f))
        return 0;
    if (s->flight == NTBI_MACOS_FLIGHT_ZOOM)
        s->flight = NTBI_MACOS_FLIGHT_NONE;
    else if (!ntbi_macos_zoom_on_its_way(s, f))
        ntbi_macos_zoom_release(w);
    return 1;
}

static int ntbi_macos_can_zoom(id w) {
    return (ntbi_msg_uint(w, "styleMask") & NTBI_STYLE_RESIZABLE) != 0;
}

static int ntbi_macos_on_zoom_path(const ntbi_macos_zoom *s, ntbi_nsrect f) {
    const ntbi_nsrect rr = s->restored, zz = s->zoomed;
    const double r[4] = { rr.x, rr.y, rr.w, rr.h };
    const double z[4] = { zz.x, zz.y, zz.w, zz.h };
    const double v[4] = { f.x, f.y, f.w, f.h };
    double span = 0.0, t, d;
    int i, k = 0;

    for (i = 0; i < 4; i++) {
        d = z[i] - r[i];
        if (d < 0) d = -d;
        if (d > span) { span = d; k = i; }
    }
    if (span < 1.0)
        return ntbi_rect_eq(f, s->restored);
    t = (v[k] - r[k]) / (z[k] - r[k]);
    if (t * span < -2.0 || (t - 1.0) * span > 2.0)
        return 0;
    for (i = 0; i < 4; i++) {
        d = v[i] - (r[i] + t * (z[i] - r[i]));
        if (d <= -2.0 || d >= 2.0)
            return 0;
    }
    return 1;
}

static int ntbi_macos_zoom_on_its_way(const ntbi_macos_zoom *s, ntbi_nsrect f) {
    if (s->deadline <= 0.0)
        return 0;
    if (s->flight == NTBI_MACOS_FLIGHT_RESTORE)
        return !ntbi_rect_eq(f, s->restored) && ntbi_macos_on_zoom_path(s, f);
    return !s->confirmed && !ntbi_rect_eq(f, s->zoomed) && ntbi_macos_on_zoom_path(s, f);
}

static int ntbi_macos_zoom_dead(const ntbi_macos_zoom *s, id w) {
    if (!s->window || s->flight != NTBI_MACOS_FLIGHT_NONE)
        return 0;
    return s->confirmed || !ntbi_macos_zoom_on_its_way(s, ntbi_msg_rect(w, "frame"));
}

static void ntbi_macos_zoom_observe(id w, int zoomed) {
    ntbi_macos_zoom *slot = ntbi_macos_zoom_find(w);
    if (!slot)
        return;
    ntbi_macos_zoom_settle(slot, w);
    if (zoomed) {
        if (slot->window)
            slot->confirmed = 1;
    } else if (ntbi_macos_zoom_dead(slot, w)) {
        ntbi_macos_zoom_release(w);
    }
}

static void ntbi_macos_reseat_responder(id w) {
    id view = ntbi_msg_id(w, "contentView");
    if (view) ntbi_msg_bool_id(w, "makeFirstResponder:", view);
}

static void ntbi_macos_show_buttons(id w, BOOL hidden) {
    id b;
    if ((b = ntbi_msg_id_int(w, "standardWindowButton:", NTBI_BTN_CLOSE)))        ntbi_msg_void_bool(b, "setHidden:", hidden);
    if ((b = ntbi_msg_id_int(w, "standardWindowButton:", NTBI_BTN_MINIATURIZE)))  ntbi_msg_void_bool(b, "setHidden:", hidden);
    if ((b = ntbi_msg_id_int(w, "standardWindowButton:", NTBI_BTN_ZOOM)))         ntbi_msg_void_bool(b, "setHidden:", hidden);
}

static int ntbi_macos_install_impl(ntb_native_window win, ntb_config cfg) {
    (void)cfg;
    id w = (id)win.cocoa_nswindow;
    if (!w) return 0;

    ntbi_nsuint mask = ntbi_msg_uint(w, "styleMask");
    mask |= NTBI_STYLE_FULLSIZECONTENTVIEW;
    ntbi_msg_void_uint(w, "setStyleMask:", mask);
    ntbi_macos_reseat_responder(w);
    ntbi_msg_void_bool(w, "setTitlebarAppearsTransparent:", YES);
    ntbi_msg_void_int (w, "setTitleVisibility:", NTBI_TITLE_HIDDEN);
    ntbi_macos_show_buttons(w, YES);
    return 1;
}

static void ntbi_macos_uninstall_impl(ntb_native_window win) {
    id w = (id)win.cocoa_nswindow;
    if (!w) return;

    ntbi_msg_void_bool(w, "setTitlebarAppearsTransparent:", NO);
    ntbi_msg_void_int (w, "setTitleVisibility:", NTBI_TITLE_VISIBLE);
    ntbi_nsuint mask = ntbi_msg_uint(w, "styleMask");
    mask &= ~(ntbi_nsuint)NTBI_STYLE_FULLSIZECONTENTVIEW;
    ntbi_msg_void_uint(w, "setStyleMask:", mask);
    ntbi_macos_reseat_responder(w);
    ntbi_macos_show_buttons(w, NO);

    ntbi_macos_zoom_release(w);
}

static int ntbi_macos_move_impl(ntb_native_window win) {
    id w = (id)win.cocoa_nswindow;
    id evw;
    if (!w) return 0;

    Class app_cls = objc_getClass("NSApplication");
    if (!app_cls) return 0;
    id app = ntbi_msg_id((id)app_cls, "sharedApplication");
    id ev  = app ? ntbi_msg_id(app, "currentEvent") : (id)0;
    if (!ev) return 0;

    evw = ntbi_msg_id(ev, "window");
    if (evw && evw != w) return 0;
    ntbi_msg_void_id(w, "performWindowDragWithEvent:", ev);
    return 1;
}

static int ntbi_native_resize(ntb_native_window win, ntb_edge e) {

    (void)win; (void)e; return 0;
}

static int ntbi_macos_set_max_impl(ntb_native_window win, int on) {
    id w = (id)win.cocoa_nswindow;
    ntbi_macos_zoom *slot;
    id screen, animator;

    if (!w) return 0;
    if (!ntbi_macos_can_zoom(w)) return 0;

    if ((on != 0) == (ntbi_msg_bool(w, "isZoomed") != 0)) {

        ntbi_macos_zoom_observe(w, on != 0);
        return 1;
    }

    animator = ntbi_msg_id(w, "animator");
    if (!animator) {
        ntbi_msg_void_id(w, "zoom:", (id)0);
        return 1;
    }

    if (on) {

        screen = ntbi_msg_id(w, "screen");
        slot   = screen ? ntbi_macos_zoom_claim(w) : (ntbi_macos_zoom *)0;
        if (!slot) {

            ntbi_msg_void_id(w, "zoom:", (id)0);
            return 1;
        }

        if (ntbi_macos_now() >= slot->deadline) {
            ntbi_nsrect frame = ntbi_msg_rect(w, "frame");

            if (!ntbi_macos_zoom_on_its_way(slot, frame))
                slot->restored = frame;
        }
        slot->zoomed    = ntbi_msg_rect(screen, "visibleFrame");
        slot->deadline  = ntbi_macos_now() + NTBI_MACOS_ZOOM_FLIGHT_S;
        slot->flight    = NTBI_MACOS_FLIGHT_ZOOM;
        slot->confirmed = 0;
        ntbi_msg_set_frame_display(animator, slot->zoomed, YES);
        return 1;
    }

    slot = ntbi_macos_zoom_find(w);
    if (slot)
        ntbi_macos_zoom_settle(slot, w);
    if (!slot || !slot->window ||
        !ntbi_macos_on_zoom_path(slot, ntbi_msg_rect(w, "frame"))) {
        ntbi_msg_void_id(w, "zoom:", (id)0);
        ntbi_macos_zoom_release(w);
        return 1;
    }

    slot->deadline = ntbi_macos_now() + NTBI_MACOS_ZOOM_FLIGHT_S;
    slot->flight   = NTBI_MACOS_FLIGHT_RESTORE;
    ntbi_msg_set_frame_display(animator, slot->restored, YES);
    return 1;
}

static int ntbi_macos_is_max_impl(ntb_native_window win) {
    id w = (id)win.cocoa_nswindow;
    int zoomed;
    if (!w || !ntbi_macos_can_zoom(w))
        return 0;
    zoomed = ntbi_msg_bool(w, "isZoomed") ? 1 : 0;
    ntbi_macos_zoom_observe(w, zoomed);
    return zoomed;
}

static int ntbi_macos_max_settled_impl(ntb_native_window win) {
    id w = (id)win.cocoa_nswindow;
    ntbi_macos_zoom *slot;

    if (!w)
        return 1;
    slot = ntbi_macos_zoom_find(w);
    if (!slot)
        return 1;
    if (!ntbi_macos_zoom_settle(slot, w))
        return 0;

    ntbi_macos_zoom_observe(w, ntbi_msg_bool(w, "isZoomed") ? 1 : 0);
    return 1;
}

static int ntbi_macos_minimize_impl(ntb_native_window win) {
    id w = (id)win.cocoa_nswindow;
    if (!w) return 0;
    ntbi_msg_void_id(w, "miniaturize:", (id)0);
    return 1;
}

static int ntbi_native_max_hover(ntb_native_window win) { (void)win; return 0; }
static int ntbi_native_max_press(ntb_native_window win) { (void)win; return 0; }
static unsigned ntbi_native_max_clicks(ntb_native_window win) { (void)win; return 0; }

static int ntbi_macos_set_topmost_impl(ntb_native_window win, int on) {
    id w = (id)win.cocoa_nswindow;
    if (!w) return 0;
    ntbi_msg_void_int(w, "setLevel:", on ? NTBI_LEVEL_FLOATING : NTBI_LEVEL_NORMAL);
    return 1;
}

static int ntbi_macos_is_topmost_impl(ntb_native_window win) {
    id w = (id)win.cocoa_nswindow;
    if (!w) return 0;
    return ntbi_msg_int(w, "level") > (ntbi_nsint)NTBI_LEVEL_NORMAL;
}

static int ntbi_native_topmost_honoured(ntb_native_window win) { (void)win; return 1; }

