static ntb_native_window ntb_from_sdl(SDL_Window *win)
{
    SDL_PropertiesID props;
    void *p;

    if (!win)
        return ntbi_sdl_none();

    props = SDL_GetWindowProperties(win);
    if (!props)
        return ntbi_sdl_none();

#if defined(_WIN32)
    p = SDL_GetPointerProperty(props, SDL_PROP_WINDOW_WIN32_HWND_POINTER, NULL);
    return p ? ntb_from_win32(p) : ntbi_sdl_none();
#elif defined(__APPLE__)
    p = SDL_GetPointerProperty(props, SDL_PROP_WINDOW_COCOA_WINDOW_POINTER, NULL);
    return p ? ntb_from_cocoa(p) : ntbi_sdl_none();
#else

    p = SDL_GetPointerProperty(props, SDL_PROP_WINDOW_WAYLAND_SURFACE_POINTER, NULL);
    if (p) {
        void *disp = SDL_GetPointerProperty(props,
                                            SDL_PROP_WINDOW_WAYLAND_DISPLAY_POINTER, NULL);
        ntb_native_window w = ntb_from_wayland(disp, p);

        w.hooks.set_maximized = ntbi_sdl_set_maximized;
        w.hooks.is_maximized  = ntbi_sdl_is_maximized;
        w.hooks.minimize      = ntbi_sdl_minimize;
        w.hooks.user          = win;
        return w;
    }

    p = SDL_GetPointerProperty(props, SDL_PROP_WINDOW_X11_DISPLAY_POINTER, NULL);
    if (p) {

        Sint64 xid = SDL_GetNumberProperty(props, SDL_PROP_WINDOW_X11_WINDOW_NUMBER, 0);
        if (xid)
            return ntb_from_x11(p, (unsigned long)xid);
    }

    return ntbi_sdl_none();
#endif
}

